INSERT INTO lex.ingested_documents (external_id, doc_type, source_system, title, body, meta, organized, crawl_batch_id, content_hash)
VALUES
  ('cpiuris2025::5d3595a343475c5e31d475685a5d72a5', 'doutrina', 'cp_iuris', 'Direito Econômico — Influência do Estado no Direito e Constitucionalismo Social', '## Influência do Estado no Direito e Constitucionalismo Social

O constitucionalismo social tem interferência do Estado, com direitos sociais acrescentados aos direitos liberais, promovendo o dirigismo contratual e a inclusão de novos direitos.

### Conceitos
- **Direito Social**: direitos que limitam a autonomia da vontade e promovem o dirigismo contratual
- **Dirigismo Contratual**: liberdade de contrato dentro de certos limites
- **Constitucionalismo Social**: modelo de constitucionalismo que tem interferência do Estado
- **Estado Social**: Estado que presta serviços públicos e protege os direitos sociais
- **Liberdade Pública**: direito proveniente do constitucionalismo liberal
- **Welfare State**: Estado de Bem-estar Social, com rol de direitos fundamentais ampliado

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre liberdade de contrato e dirigismo contratual.
- Conheça o conceito de Estado Social e sua relação com os direitos sociais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:02:07.010644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=29", "doc_key": "5d3595a343475c5e31d475685a5d72a5"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '44cb72b3b76bbccca2af6007685a3c8eafecd5ea97f2662009442d45ca431453'),
  ('cpiuris2025::31f072897a1db2efcf9d398139c60c38', 'doutrina', 'cp_iuris', 'Direito Econômico — Desenvolvimento do Estado e do Constitutionalismo', '## Desenvolvimento do Estado e do Constitutionalismo

O desenvolvimento do Estado e do constitutionalismo ocorre quando o Estado incorpora direitos sociais nas constituições, criando uma obrigação de fazer e não mais de se abster. Isso modifica toda a teoria, arranjo e arquitetura institucional.

### Conceitos
- **Direito Social**: Direitos que exigem a atuação estatal para serem protegidos
- **Princípio da Separação dos Poderes**: Princípio que limita o poder do Estado e garante a proteção de direitos fundamentais
- **Estado Liberal**: Forma de Estado que prioriza a liberdade individual e limita a intervenção estatal
- **Estado Social**: Forma de Estado que prioriza a proteção dos direitos sociais e exige a atuação estatal para sua realização

### Referências legais
- Art. 5º, § 1º da Constituição Brasileira de 1988
- Súmula 634 do Supremo Tribunal Federal (STF)

### Jurisprudência
- REsp 1488639/SE

### Dicas de prova
- Entenda a distinção entre o Estado Liberal e o Estado Social
- Conheça a importância da separação dos poderes no contexto de direitos sociais
- Avalie a necessidade de mudança na arquitetura do Estado para atender aos direitos sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito Econômico", "legal_refs": ["Art. 5º, § 1º da Constituição Brasileira de 1988", "Súmula 634 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["REsp 1488639/SE"], "confidence": 0.8, "extracted_at": "2026-05-26T20:02:55.635056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=30", "doc_key": "31f072897a1db2efcf9d398139c60c38"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '022dea399a3fbf010960c035901a76676b910cbb53bf0380b4fdc2c8f37bc1a5'),
  ('cpiuris2025::6717cfe3a83581f51fa2ccd5af06b310', 'doutrina', 'cp_iuris', 'Direito Econômico — Ativismo Judicial', '## Ativismo Judicial

O ativismo judicial surge de uma lógica que impõe ao Estado uma obrigação de fazer, corrigindo inconstitucionalidades e realizando direitos fundamentais.

### Conceitos
- **Direitos Sociais**: Prestacionais que exigem uma prestação positiva do Estado
- **Ativismo Judicial**: Correção de inconstitucionalidades e realização de direitos fundamentais
- **Obrigação de Fazer**: Imperativo para o Estado agir, corrigindo inconstitucionalidades

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre direitos fundamentais e interesses da maioria
- Entendimento do orçamento público como um programa de estratégia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:03:19.836125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=30", "doc_key": "6717cfe3a83581f51fa2ccd5af06b310"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '2f92ef9620ce6299f3990e5891b8ac071d9aa0d3f64c7ffdb6dd9e2a81e801ee'),
  ('cpiuris2025::de0d48c889dacb78e93d9e53efc88e23', 'doutrina', 'cp_iuris', 'Direito Econômico — Recepção do Estado Social na Constituição Federal de 1988', '## Recepção do Estado Social na Constituição Federal de 1988

O artigo 6º da CF/88 consagra o papel do Estado Social, garantindo direitos sociais como educação, saúde e previdência social. A EC n°. 114/2021 acrescentou o direito a uma renda básica familiar para brasileiros em situação de vulnerabilidade social.

### Conceitos
- **Estado Social**: Conceito que se refere ao papel do Estado na garantia dos direitos sociais e na promoção da igualdade social.
- **Direitos Sociais**: Direitos garantidos pela Constituição para assegurar a dignidade e o bem-estar das pessoas
- **Prestações Públicas**: Serviços e benefícios fornecidos pelo Estado às suas cidadãos, como educação, saúde e previdência social.

### Referências legais
- Art. 6º da Constituição Federal de 1988
- EC n°. 114/2021

### Dicas de prova
- Entenda a noção de Estado Social e seus impactos na sociedade brasileira.
- Conheça os direitos sociais garantidos pela Constituição Federal de 1988.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito Econômico", "legal_refs": ["Art. 6º da Constituição Federal de 1988", "EC n°. 114/2021"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-26T20:03:54.296915+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=31", "doc_key": "de0d48c889dacb78e93d9e53efc88e23"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'c36baa35451a63e48915d74af87f44f0fb2f4723c48ffe9dc3becf25d3941b2a'),
  ('cpiuris2025::d9ef98a57900df31e381a104978341f8', 'doutrina', 'cp_iuris', 'Direito Econômico — Garantia de Direitos Sociais pelo Estado', '## Garantia de Direitos Sociais pelo Estado

O Estado tem a atribuição de garantir os direitos sociais, podendo praticar diretamente ou delegando atribuições, e a titularidade desses direitos passa a ser do Estado.

### Conceitos
- **Garantia de Direitos Sociais**: O dever do Estado de proteger os direitos sociais
- **Atribuição do Estado**: O poder concedido ao Estado para garantir os direitos sociais
- **Titularidade do Estado**: A responsabilidade do Estado pela prestação dos direitos sociais

### Referências legais
- Art. 6º da Constituição Federal
- Art. 170 da Constituição Federal

### Dicas de prova
- Entenda a importância da garantia de direitos sociais pelo Estado
- Conheça os princípios que regem a ordem econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito Econômico", "legal_refs": ["Art. 6º da Constituição Federal", "Art. 170 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:04:27.355220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=31", "doc_key": "d9ef98a57900df31e381a104978341f8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f114cb022751dfbee7a98677bcb5e2a471cbbafd391b32dd1d309ba6111a2dc6'),
  ('cpiuris2025::c974c93f5484f8095c47d16a4ef89267', 'doutrina', 'cp_iuris', 'Direito Econômico — Recepção do Estado Social na Constituição dos EUA', '## Recepção do Estado Social na Constituição dos EUA

A Constituição americana não incorporou direitos sociais, mas os valores da justiça social e igualdade material são entendidos como limites para a interferência estatal na economia e nas relações sociais.

### Conceitos
- **Constitucionalismo Social**: Movimento que busca incorporar direitos sociais na Constituição americana de uma forma diferente do que ocorreu em outras constituições ocidentais.
- **Liberalismo Econômico**: Sistema econômico consagrado na Constituição americana e considerado inconstitucional qualquer interferência estatal nas relações privadas.
- **Era Locke**: Período de 1930 caracterizado pela defesa do liberalismo econômico pela Suprema Corte americana.

### Referências legais
- Art. I da Constituição dos EUA

### Jurisprudência
- Caso Locke x Nova Iorque
- Súmula 123 da Suprema Corte Americana

### Dicas de prova
- Entenda a diferença entre o constitucionalismo social e o liberalismo econômico.
- Conheça a Era Locke e sua importância na história do direito americano.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito Econômico", "legal_refs": ["Art. I da Constituição dos EUA"], "jurisprudence": ["Caso Locke x Nova Iorque", "Súmula 123 da Suprema Corte Americana"], "confidence": 0.8, "extracted_at": "2026-05-26T20:05:03.569459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=32", "doc_key": "c974c93f5484f8095c47d16a4ef89267"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '176e1efccffccde1cec93eb91c435324d9716f858368dab09a96020670625011'),
  ('cpiuris2025::b930638b055156d9c12613f83e5caece', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervencionismo Econômico Estatal', '## Intervencionismo Econômico Estatal

A crise econômica de 1929 levou ao surgimento do intervencionismo econômico estatal, defendido por John Maynard Keynes. O Estado pode intervir na economia para evitar crises, com o objetivo de promover a regulação e direcionamento da atividade econômica.

### Conceitos
- **Intervencionismo Econômico Estatal**: Política econômica que defende a intervenção do Estado na economia para evitar crises e promover a regulação.
- **Liberalismo Econômico**: Filosofia econômica que defende a liberdade individual e o mercado livre, sem intervenção estatal.
- **Era Locke**: Período histórico que se refere à influência do filósofo John Locke na jurisprudência e na política americana.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo: Intervencionismo Econômico Estatal

### Dicas de prova
- Entenda a diferença entre intervencionismo econômico estatal e liberalismo econômico.
- Conheça a Era Locke e sua influência na jurisprudência americana.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo: Intervencionismo Econômico Estatal"], "confidence": 0.8, "extracted_at": "2026-05-26T20:05:34.272025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=32", "doc_key": "b930638b055156d9c12613f83e5caece"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '0e96a17f97d77ed81b635935b796466c7b720671d06483a29eee80fdcd96a129'),
  ('cpiuris2025::86665b81514a69f0453e7a1b163bf5db', 'doutrina', 'cp_iuris', 'Direito Econômico — Constitucionalismo Social e Crise do Estado Social', '## Constitucionalismo Social e Crise do Estado Social

A crise do constitucionalismo social e do estado social ocorre devido à expansão do poder executivo e à relativização dos direitos individuais, levando a uma ideia totalitária.

### Conceitos
- **Constitucionalismo Social**: Sistema que prioriza o Estado Social e os direitos coletivos
- **Estado Liberal**: Sistema que prioriza o parlamento e os direitos individuais
- **Poder Executivo**: Poder responsável pelas ações do Estado
- **Máquina Pública**: Instituição governamental responsável por realizar as ações do Estado
- **Individualismo**: Ideia que prioriza os direitos individuais
- **Interesse Coletivo**: Priorização dos interesses da coletividade sobre os interesses individuais
- **Totalitarismo**: Sistema político que prioriza o poder do Estado sobre os direitos individuais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a relação entre o constitucionalismo social e a crise do estado social.
- Análise a expansão do poder executivo e sua impacto nos direitos individuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:06:19.494090+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=33", "doc_key": "86665b81514a69f0453e7a1b163bf5db"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f3858d8e6e0eb947b9a50db65c78716197dcc13c055e1a6dda912754a36caed0'),
  ('cpiuris2025::d951cf32a6a115ae32de41bd019bd03a', 'doutrina', 'cp_iuris', 'Direito Econômico — Estado Totalitário e Direitos Individuais', '## Estado Totalitário e Direitos Individuais

O Estado totalitário é um Estado organicista que considera os indivíduos como partes do todo, com direitos limitados ou inexistentes se não forem compatíveis com o interesse do Estado.

### Conceitos
- **Estado Organicista**: parte do pressuposto de que os indivíduos são partes do todo
- **Direitos Individuais**: direitos garantidos ao indivíduo, limitados ou inexistentes em um Estado totalitário
- **Coletivo vs Indivíduo**: conceito que elimina o indivíduo se estiver contra o coletivo

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Estado Totalitário

### Dicas de prova
- Entenda a diferença entre Estado Organicista e Direitos Individuais
- Conheça o conceito de Coletivo vs Indivíduo e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Estado Totalitário"], "confidence": 0.8, "extracted_at": "2026-05-26T20:06:44.808909+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=33", "doc_key": "d951cf32a6a115ae32de41bd019bd03a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6548693244cf6fde7adf7725693d422838fcb2729703cc97811ef94907f6ce05'),
  ('cpiuris2025::dff920a2ce1ab8eb2c8dd40734f1c9da', 'doutrina', 'cp_iuris', 'Direito Econômico — Desenvolvimento do Estado e do Constitucionalismo', '## Desenvolvimento do Estado e do Constitucionalismo

O texto discute como o Executivo pode editar leis sem seguir o processo legislativo previsto na Constituição, levando a leis discriminatórias como as Leis de Nuremberg. O constitucionalismo europeu reconheceu a necessidade de mudanças no Estado para estabelecer um sistema em que a Constituição seja uma garantia contra os Poderes.

### Conceitos
- **Constitucionalismo**: Sistema jurídico que prioriza a Constituição como fonte do direito
- **Positivismo**: Teoria jurídica que separa direito e moral, considerando apenas o conteúdo da norma
- **Neoconstitucionalismo**: Período de mudanças no Estado para estabelecer um sistema em que a Constituição seja uma garantia contra os Poderes
- **Controle de Constitucionalidade**: Mecanismo que permite a interpretação e aplicação da Constituição

### Referências legais
- Art. 62 da Constituição Weimar

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de positivismo jurídico e sua separação entre direito e moral
- Identifique as características do neoconstitucionalismo e seu objetivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direito Econômico", "legal_refs": ["Art. 62 da Constituição Weimar"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:07:18.687839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=34", "doc_key": "dff920a2ce1ab8eb2c8dd40734f1c9da"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '97e3598a66b2e049af62021ed2c4c117541e2ce472fd7b11f7080271507922ba'),
  ('cpiuris2025::e68a4517465ad922fc47ca9473f158a4', 'doutrina', 'cp_iuris', 'Direito Econômico — Dignidade Humana como Fundamento Constitucional', '## Dignidade Humana como Fundamento Constitucional

A dignidade humana é inviolável, sendo um princípio axiológico das Constituições e o Estado existe para protegê-la. A Constituição Federal de 1988 prevê a dignidade da pessoa humana como fundamento da República.

### Conceitos
- **Dignidade Humana**: Inviolabilidade e princípio axiológico das Constituições
- **Neoconstitucionalismo**: Movimento que supera o positivismo jurídico e reaproxima direito e moral
- **Pós-positivismo**: Aproximação do direito à moralidade
- **Soberania**: Fundamento da República Federativa do Brasil
- **Cidadania**: Direito inalienável de todos os cidadãos brasileiros
- **Valores Sociais do Trabalho e da Livre Iniciativa**: Fundamentos da República, junto à soberania e à cidadania

### Referências legais
- Art. 1º da Constituição Federal de 1988

### Dicas de prova
- Entenda a relação entre direito e moralidade
- Conheça os fundamentos da República Federativa do Brasil
- Aproxie-se do conceito de dignidade humana como princípio axiológico das Constituições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º da Constituição Federal de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:08:01.689284+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=34", "doc_key": "e68a4517465ad922fc47ca9473f158a4"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '7b3b3e7e9dba4622ba1c40244847ad58253b2d4f10c26ee601ebde74fc20fcb1'),
  ('cpiuris2025::e83965790deeb296990dacc4578fe042', 'doutrina', 'cp_iuris', 'Direito Econômico — Neoliberalismo', '## Neoliberalismo

O neoliberalismo é uma corrente teórica que prioriza a liberdade econômica e reduz a intervenção estatal na economia, buscando promover o crescimento econômico e a prosperidade.

### Conceitos
- **Neoliberalismo**: Corrente teórica que prioriza a liberdade econômica e reduz a intervenção estatal na economia.
- **Intervenção Estatal**: Ações do Estado em relação à economia, como regulamentação e controle de mercados.
- **Liberdade Econômica**: Direito dos indivíduos e empresas de operar livremente no mercado, sem restrições excessivas do Estado.

### Referências legais
- Art. 170 da CF/88

### Dicas de prova
- Entenda a distinção entre neoliberalismo e liberalismo.
- Conheça as principais características do neoliberalismo, como menor intervenção estatal e liberdade econômica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Direito Econômico", "legal_refs": ["Art. 170 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:08:30.433223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=35", "doc_key": "e83965790deeb296990dacc4578fe042"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '4be6b14b5a9022edb2ccaa03cf859cbe54422ccfaeb274bb6127da56938e6ae9'),
  ('cpiuris2025::7155cf14c8a7ca02b80bb8a24eb87548', 'doutrina', 'cp_iuris', 'Direito Econômico — Neoliberalismo no Brasil', '## Neoliberalismo no Brasil

Regra geral do movimento neoliberal no Brasil, destacando a promoção de liberdade econômica e redução da intervenção estatal.

### Conceitos
- **Intervenção Estatal**: Limitação ou ausência de intervenção governamental em atividades econômicas
- **Privatização**: Transferência de propriedade de empresas estatais para o setor privado
- **Livre Comércio**: Remoção de barreiras alfandegárias e tarifas para facilitar o comércio internacional
- **Globalização**: Processo de integração econômica e política entre países

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a promoção de liberdade econômica como um princípio fundamental do neoliberalismo.
- Identifique as formas de intervenção estatal reduzida ou eliminada no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:08:53.699492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=35", "doc_key": "7155cf14c8a7ca02b80bb8a24eb87548"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'deedb3dba2646ea9f147d34b556db39e3f31310494992b3da5d5c372b4edc7d4'),
  ('cpiuris2025::040dc9914b49c065adaf654c8f38a78a', 'doutrina', 'cp_iuris', 'Direito Econômico — Neoliberalismo no Brasil', '## Neoliberalismo no Brasil

O neoliberalismo no Brasil se desenvolveu na década de 1980, caracterizando-se por abertura econômica, privatizações e reforma administrativa, com o objetivo de reduzir o papel do Estado na economia.

### Conceitos
- **Abertura Econômica**: Ação do governo para aumentar a liberdade de negócios e investimentos.
- **Privatizações**: Venda de empresas estatais para privados.
- **Reforma Administrativa**: Mudanças no sistema administrativo para reduzir o papel do Estado na economia.
- **Estado Regulador**: Papel subsidiário do Estado em relação às agências reguladoras.
- **Parcerias Público-Privadas**: Colaboração entre o governo e empresas privadas para desenvolver projetos.
- **Lei da Liberdade Econômica**: Lei que regula a liberdade econômica no Brasil.
- **Agências Reguladoras**: Entidades governamentais responsáveis por regular atividades econômicas.

### Referências legais
- Art. 2º da Lei n.º 13.848/2019

### Dicas de prova
- Entenda a abertura econômica e suas implicações no Brasil.
- Conheça as privatizações e sua importância na reforma administrativa.
- Análise o papel do Estado regulador em relação às agências reguladoras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direito Econômico", "legal_refs": ["Art. 2º da Lei n.º 13.848/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:09:42.682139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=36", "doc_key": "040dc9914b49c065adaf654c8f38a78a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '9a2413806d48c40cd6ae9d5569307faf5dbd9bd717d1fba5f833eb40ae176791'),
  ('cpiuris2025::3c6f30f452d3e9b83637995741fcd844', 'doutrina', 'cp_iuris', 'Direito Econômico — Movimento Constitucional Brasileiro', '## Movimento Constitucional Brasileiro

O estudo do Direito Econômico está interligado com o Direito Constitucional Econômico, analisando as normas constitucionais que tratam da política econômica do Estado.

### Conceitos
- **Direito Econômico**: disciplina que estuda a economia e a política econômica
- **Direito Constitucional Econômico**: subárea do Direito Econômico que analisa as normas constitucionais de política econômica
- **Constitucionalismo**: teoria jurídica que estuda a estrutura e o desenvolvimento das constituições

### Referências legais
- Art. 5º da CF/88

### Dicas de prova
- Entenda a relação entre Direito Econômico e Direito Constitucional Econômico
- Análise as normas constitucionais de política econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direito Econômico", "legal_refs": ["Art. 5º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:10:04.605043+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=36", "doc_key": "3c6f30f452d3e9b83637995741fcd844"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'c2e81b0e2769e6319741ca31b9415b17551e2792e0cbe541598e642c6ce26fe1'),
  ('cpiuris2025::f6d44e9e350db79118e0f365bca5a171', 'doutrina', 'cp_iuris', 'Direito Econômico — Desenvolvimento do Estado e do Constitucionalismo', '## Desenvolvimento do Estado e do Constitucionalismo

A Constituição de 1824 refletia a ideologia liberal da época, defendendo a ausência do Estado na economia e simbolizando a mão invisível do mercado. A Constituição Federal de 1891 manteve os valores liberais de Adam Smith, assegurando direitos à liberdade, à livre iniciativa e à propriedade.

### Conceitos
- **Mão Invisível**: Princípio econômico que defende a ausência do Estado na economia e a regulação do mercado conforme a oferta e a procura.
- **Liberalismo Econômico**: Ideologia que defende a liberdade individual e a propriedade privada como fundamentos da economia.
- **Constitucionalismo**: Sistema de governo que baseia-se na Constituição como fonte principal do direito.

### Referências legais
- Art. 179 da Constituição de 1824
- Art. 72 da Constituição de 1891

### Dicas de prova
- Diferenciar entre o liberalismo econômico e o constitucionalismo.
- Entender a importância da mão invisível no desenvolvimento do Estado e do constitucionalismo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito Econômico", "legal_refs": ["Art. 179 da Constituição de 1824", "Art. 72 da Constituição de 1891"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:10:37.589614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=37", "doc_key": "f6d44e9e350db79118e0f365bca5a171"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '528be723db3ebd7324b6a0c11de51cb3a5af71965b1a1af9a3d7c4405556343d'),
  ('cpiuris2025::1751d3289663aa370cfa422188bada17', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopolização e Regulação Econômica', '## Monopolização e Regulação Econômica

O texto estabelece regras para a monopolização de indústrias ou atividades econômicas, bem como a regulação do crédito e da economia popular.

### Conceitos
- **Monopolização**: A autorização da União para controlar uma indústria ou atividade econômica
- **Lei especial**: Uma lei que autoriza a União a tomar medidas específicas em um determinado setor
- **Economia popular**: Um modelo de economia que visa promover o desenvolvimento social e econômico de uma região ou país
- **Crédito**: O direito ao acesso a recursos financeiros para realizar atividades econômicas
- **Nacionalização**: A aquisição pelo Estado de empresas ou setores da economia
- **Usura**: A prática de cobrar juros excessivos em prestações de dinheiro
- **Propriedade do subsolo**: O direito de explorar e aproveitar as minas, águas e energia hidráulica

### Referências legais
- Art. 116 da Lei X
- Art. 117 da Lei X
- Art. 118 da Lei X
- Art. 119 da Lei X

### Dicas de prova
- Entenda a diferença entre monopolização e nacionalização
- Conheça as regras para autorizar ou conceder concessões federais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito Econômico", "legal_refs": ["Art. 116 da Lei X", "Art. 117 da Lei X", "Art. 118 da Lei X", "Art. 119 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:11:22.787978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=37", "doc_key": "1751d3289663aa370cfa422188bada17"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '66305d6f731b043eb38e732d6af3b00235b7c67a6bb44589ef2843d435b53a8a'),
  ('cpiuris2025::465da5b066c4cf00895d34ea89bab372', 'doutrina', 'cp_iuris', 'Direito Econômico — Desenvolvimento do Estado e do Constitucionalismo', '## Desenvolvimento do Estado e do Constitucionalismo

Artigos relacionados ao desenvolvimento do Estado e à constitucionalização das atividades econômicas.

### Conceitos
- **Aproveitamento de energia hidráulica**: Independência de autorização ou concessão para uso exclusivo do proprietário
- **Nacionalização progressiva das minas e jazidas minerais**: Regulação da nacionalização por lei, com base em condições técnicas e administrativas
- **Atribuição dos Estados à exploração de recursos hídricos**: Exercício da atribuição constante do artigo dentro dos respectivos territórios

### Referências legais
- Art. 120
- Art. 121
- Art. 4º

### Dicas de prova
- Distinção entre aproveitamento de energia hidráulica e exploração de minas
- Conceito de nacionalização progressiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito Econômico", "legal_refs": ["Art. 120", "Art. 121", "Art. 4º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:11:50.885225+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=38", "doc_key": "465da5b066c4cf00895d34ea89bab372"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '14017385d0034ce8154a49547eb57bfe7d197212004b72c98dae3b490140cddc'),
  ('cpiuris2025::75837cf771b7c66d28fb0149bdac38f3', 'doutrina', 'cp_iuris', 'Direito Econômico — Lei de Trabalho', '## Lei de Trabalho

Regulamentação do trabalho, incluindo contribuições para velhice, invalidez e maternidade, bem como reconhecimento de convenções coletivas.

### Conceitos
- **Contribuição para a Previdência Social**: Pagamento obrigatório para avelhamento, invalidade, maternidade e acidentes de trabalho
- **Convenção Coletiva**: Acordo entre empregadores e empregados sobre condições de trabalho e salários
- **Trabalho Agrícola**: Atividades relacionadas à agricultura

### Referências legais
- Art. 7 da Lei nº 7.853/89

### Dicas de prova
- Distinção entre trabalho manual e intelectual
- Importância das convenções coletivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito Econômico", "legal_refs": ["Art. 7 da Lei nº 7.853/89"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:12:13.889770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=38", "doc_key": "75837cf771b7c66d28fb0149bdac38f3"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '17922af019c74e87b028984865273d030387ab5c064e21c29f93702f747eed56'),
  ('cpiuris2025::31096c0591f2f595e77f804513f75399', 'doutrina', 'cp_iuris', 'Direito Econômico — Desenvolvimento do Estado e do Constitucionalismo', '## Desenvolvimento do Estado e do Constitucionalismo

Discute-se o desenvolvimento do estado e do constitucionalismo, destacando a importância da Justiça do Trabalho e a regulamentação de direitos trabalhistas.

### Conceitos
- **Justiça do Trabalho**: Instituição que dirime questões entre empregadores e empregados, regidas pela legislação social.
- **Legislação Social**: Lei que regula os direitos e benefícios dos trabalhadores.
- **Tribunais do Trabalho**: Entidades judiciais que julgam questões trabalhistas.
- **Comissões de Conciliação**: Órgãos que tentam resolver conflitos entre empregadores e empregados antes da instauração do processo judicial.
- **Eleição de Membros**: Princípio que determina a escolha dos membros dos Tribunais do Trabalho e das Comissões de Conciliação, com metade representada por associações de empregados e metade por associações de empregadores.

### Referências legais
- Art. 122 da Constituição
- Art. 123 da Constituição
- Art. 124 da Constituição
- Art. 125 da Constituição

### Dicas de prova
- Entenda a importância da Justiça do Trabalho e como ela regula os direitos trabalhistas.
- Conheça as principais instituições que compõem o sistema judiciário trabalhista, como os Tribunais do Trabalho e as Comissões de Conciliação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Econômico", "legal_refs": ["Art. 122 da Constituição", "Art. 123 da Constituição", "Art. 124 da Constituição", "Art. 125 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:13:06.111688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=39", "doc_key": "31096c0591f2f595e77f804513f75399"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '7a06a097112e0348c8bef0a7d8f4c641e77bb91c55a80073105713ddc311404a'),
  ('cpiuris2025::dcf214edd2c52d192906a3e55b7baa6d', 'doutrina', 'cp_iuris', 'Direito Econômico — Propriedade e Controle de Empresas Jornalísticas e Noticiosas', '## Propriedade e Controle de Empresas Jornalísticas e Noticiosas

Artigos 131, 132 e 133 regulamentam a propriedade e controle de empresas jornalísticas e noticiosas, estabelecendo restrições à propriedade estrangeira e requisitos para a nacionalidade dos proprietários e profissionais.

### Conceitos
- **Propriedade Estatal**: 
- **Restrição à Propriedade Estrangeira**: 
- **Nacionalidade dos Proprietários**: 
- **Profissões Liberais**: 

### Referências legais
- Art. 131
- Art. 132
- Art. 133

### Dicas de prova
- Entenda a importância da nacionalidade dos proprietários e profissionais em empresas jornalísticas e noticiosas.
- Identifique as restrições à propriedade estrangeira estabelecidas pela lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Econômico", "legal_refs": ["Art. 131", "Art. 132", "Art. 133"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:13:29.594596+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=39", "doc_key": "dcf214edd2c52d192906a3e55b7baa6d"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'dd36d063a79f9d6d7e95f0a9dc5b4de39b856f80224126b74dd837cbfe2cfd52'),
  ('cpiuris2025::cfb4fd85906b44df3d16cc8383ba77a1', 'doutrina', 'cp_iuris', 'Direito Econômico — Vocação para suceder em bens de estrangeiros e regulamentações', '## Vocação para suceder em bens de estrangeiros e regulamentações

Artigos 134 a 140 regulam a vocação para suceder em bens de estrangeiros, a fiscalização de serviços públicos federais, estaduais e municipais, a proteção da juventude e a educação, além de outros aspectos econômicos.

### Conceitos
- **Vocação para suceder**: Direito do brasileiro a herdar bens de estrangeiros
- **Fiscalização de serviços públicos**: Regulamentação da fiscalização e revisão de tarifas de serviços explodidos por concessão ou delegação
- **Proteção da juventude**: Medidas legais e administrativas para proteger a juventude contra exploração e abandono
- **Educação**: Amparo à educação eugênica, maternidade, infância, famílias de prole numerosa e proteção da juventude

### Referências legais
- Art. 134
- Art. 135
- Art. 136
- Art. 137
- Art. 138
- Art. 139
- Art. 140

### Dicas de prova
- Entenda a vocação para suceder em bens de estrangeiros e suas regulamentações
- Conheça as medidas legais e administrativas para proteger a juventude
- Aprenda sobre a fiscalização de serviços públicos federais, estaduais e municipais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Econômico", "legal_refs": ["Art. 134", "Art. 135", "Art. 136", "Art. 137", "Art. 138", "Art. 139", "Art. 140"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:14:08.877286+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=40", "doc_key": "cfb4fd85906b44df3d16cc8383ba77a1"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '678ab2929f7b96d415c81e5924ef3bf972136efb1c6188c03bbab4ca54bb73a6'),
  ('cpiuris2025::05af4a877468b7a111c36a03491ca6ab', 'doutrina', 'cp_iuris', 'Direito Econômico — Direitos Sociais e Ordem Econômica', '## Direitos Sociais e Ordem Econômica

O texto discute a obrigação de destinar um por cento das rendas tributárias para amparo à maternidade e à infância, bem como os avanços dos direitos sociais na Constituição de 1934. Além disso, é apresentada uma breve descrição da Constituição de 1937, conhecida como ''Polaca'', que fortaleceu o poder executivo federal e adotou características do corporativismo e nacionalismo.

### Conceitos
- **Direitos Sociais**: Benefícios destinados a proteger os trabalhadores e suas famílias
- **Ordem Econômica**: Estrutura organizacional do sistema econômico

### Referências legais
- Art. 135 a 155 da Constituição

### Dicas de prova
- Entenda o conceito de Direitos Sociais e sua importância no contexto econômico.
- Conheça as características da Constituição de 1937, conhecida como ''Polaca''.
- Destaque a influência do fascismo na Constituição de 1937.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Econômico", "legal_refs": ["Art. 135 a 155 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:14:45.611193+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=40", "doc_key": "05af4a877468b7a111c36a03491ca6ab"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '2713326b31dc12abf24b3b13803735fd2622de69c76219e74ee86f1d5c738a0a'),
  ('cpiuris2025::b02d0a1523295cc5a639cb8d37aece44', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção do Estado no domínio econômico', '## Intervenção do Estado no domínio econômico

A intervenção do Estado no domínio econômico é justificada para suprir as deficiências da iniciativa individual e coordenar os fatores da produção, evitando conflitos e promovendo o pensamento dos interesses da Nação.

### Conceitos
- **Iniciativa Individual**: A capacidade do indivíduo de criar, organizar e inovar no domínio econômico
- **Bem Público**: O interesse coletivo da sociedade que deve ser protegido pelo Estado
- **Intervenção Estatal**: A ação do Estado no domínio econômico para suprir deficiências e coordenar produção

### Referências legais
- Art. 135 da Constituição
- Art. 136 da Constituição
- Art. 139 da Constituição
- Art. 140 da Constituição
- Art. 141 da Constituição
- Art. 142 da Constituição
- Art. 143 da Constituição

### Dicas de prova
- Entenda a distinção entre iniciativa individual e intervenção estatal no domínio econômico
- Conheça as garantias especiais para a economia popular previstas na Constituição
- Aprenda a aplicação da lei em relação à usura e crimes contra a economia popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Econômico", "legal_refs": ["Art. 135 da Constituição", "Art. 136 da Constituição", "Art. 139 da Constituição", "Art. 140 da Constituição", "Art. 141 da Constituição", "Art. 142 da Constituição", "Art. 143 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:15:21.713297+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=41", "doc_key": "b02d0a1523295cc5a639cb8d37aece44"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6eea0c7722e730b1bb7ba393aefb5da83954bf73432061067574bb1a0c9c5981'),
  ('cpiuris2025::5ea9083d98d59fe6756c00263a2c2889', 'doutrina', 'cp_iuris', 'Direito Econômico — Autorização para aproveitamento de energia hidráulica', '## Autorização para aproveitamento de energia hidráulica

A autorização para aproveitar energia hidráulica é necessária, independentemente da propriedade privada, e só será concedida a brasileiros ou empresas com acionistas brasileiros.

### Conceitos
- **Autorização**: necessária para aproveitamento de energia hidráulica
- **Propriedade Privada**: não garante autorização para aproveitamento de energia hidráulica
- **Governo**: pode permitir aproveitamento a empresas que já exercem utilizações amparadas pelo § 4º
- **Utilizações Amparadas**: exercidas por empresas que já têm autorização para explorar recursos naturais

### Referências legais
- Art. 144 da Constituição
- Art. 145 da Constituição

### Dicas de prova
- Distinção entre aproveitamento de energia hidráulica e utilizações amparadas pelo § 4º
- Importância da propriedade privada para autorização do aproveitamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Econômico", "legal_refs": ["Art. 144 da Constituição", "Art. 145 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:15:48.654480+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=41", "doc_key": "5ea9083d98d59fe6756c00263a2c2889"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'dd4f7ea35b9379d53360ee3a506af763013b0bcc6e5e3fa84f98d7c8c3b95260'),
  ('cpiuris2025::a9320fe2838ca9d5a69b1c28aa96c2e1', 'doutrina', 'cp_iuris', 'Direito Econômico — Concessões de Serviços Públicos Federais, Estaduais e Municipais', '## Concessões de Serviços Públicos Federais, Estaduais e Municipais

A lei estabelece requisitos para as empresas concessionárias de serviços públicos federais, estaduais e municipais, incluindo a composição da administração e a fiscalização das tarifas.

### Conceitos
- **Concessão**: Permissão concedida pelo Estado para que uma empresa realize um serviço público.
- **Administração**: A gestão e o controle de uma empresa ou organização.
- **Fiscalização**: O ato de controlar e monitorar a conformidade com as leis e regulamentos.
- **Tarifa**: Preço pago por um serviço público.
- **Constituição**: A lei fundamental do país, que estabelece os princípios básicos da organização política e social do Estado.

### Referências legais
- Art. 146
- Art. 147

### Dicas de prova
- Entenda a composição da administração das empresas concessionárias.
- Conheça as exigências para a fiscalização das tarifas dos serviços públicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito Econômico", "legal_refs": ["Art. 146", "Art. 147"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:16:33.084448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=42", "doc_key": "a9320fe2838ca9d5a69b1c28aa96c2e1"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '422627d87e56db8b4a11e0b5dd8be35022a6280076573cb57d1f8ffa5e997637'),
  ('cpiuris2025::603d86ac5be022de132d89e83aedf97a', 'doutrina', 'cp_iuris', 'Direito Econômico — Inviolabilidade dos Direitos Humanos', '## Inviolabilidade dos Direitos Humanos

A Constituição assegura a inviolabilidade dos direitos concernentes à vida, liberdade, segurança individual e propriedade.

### Conceitos
- **Inviolabilidade dos Direitos Humanos**: Direito fundamental que não pode ser violado por qualquer ente público ou privado.
- **Igualdade perante a lei**: Todos os brasileiros e estrangeiros residentes no País são tratados igualmente pela lei.
- **Direito adquirido**: Direito que é reconhecido e protegido pela lei após a sua acquisição.
- **Ato jurídico perfeito**: Ato que tem todas as características necessárias para ser considerado legalmente válido.
- **Cosa julgada**: Decisão final e definitiva de um processo que não pode ser revisada ou alterada.
- **Liberdade de expressão**: Direito à liberdade de pensamento, manifestação e comunicação.
- **Propaganda**: Ação de promover uma ideia, produto ou serviço para influenciar a opinião pública.

### Referências legais
- Art. 141 da Constituição Brasileira

### Dicas de prova
- Entenda a importância da inviolabilidade dos direitos humanos e como ela é garantida pela Constituição.
- Identifique os princípios que regem a liberdade de expressão e propaganda, e como elas são regulamentadas pela lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito Econômico", "legal_refs": ["Art. 141 da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:17:09.280879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=42", "doc_key": "603d86ac5be022de132d89e83aedf97a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '70da8466ba9dcf97a1917106d339d39db730ba4a3f0bb336f240ee39d19e0b0c'),
  ('cpiuris2025::88c2b0567bea173bc3b9208f9d68761b', 'doutrina', 'cp_iuris', 'Direito Econômico — Direitos e Garantias Fundamentais', '## Direitos e Garantias Fundamentais

O texto destaca a importância de garantir direitos fundamentais, como liberdade religiosa, liberdade de associação, liberdade de expressão e proteção à propriedade.

### Conceitos
- **Direito à Liberdade Religiosa**: O direito de praticar qualquer religião sem medo de perseguição ou repressão.
- **Liberdade de Associação**: A liberdade de se associar a outras pessoas para fins lícitos, sem medo de dissolução compulsória.
- **Proteção à Propriedade**: A garantia do direito de propriedade, salvo em casos de desapropriação por necessidade ou utilidade pública.
- **Direito à Vida Privada**: O direito à vida privada, incluindo a inviolabilidade da casa e o respeito à privacidade.
- **Liberdade de Expressão**: A liberdade de expressar opiniões, pensamentos e ideias sem medo de censura ou repressão.
- **Direitos Fundamentais**: Os direitos fundamentais garantidos pela Constituição, que são inalienáveis e invioláveis.

### Referências legais
- Art. 129, n.ºs I e II
- Art. 147, § 1º

### Dicas de prova
- Entenda a importância da liberdade religiosa e como ela é garantida pela Constituição.
- Conheça as diferentes formas de associação e como elas são regulamentadas pelo Estado.
- Aprenda a distinguir entre direitos fundamentais e direitos não fundamentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito Econômico", "legal_refs": ["Art. 129, n.ºs I e II", "Art. 147, § 1º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:17:50.387261+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=43", "doc_key": "88c2b0567bea173bc3b9208f9d68761b"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '1ab22fd02116162818a8c22726d94a46dd65f622fc7acbebc6b785675533e674'),
  ('cpiuris2025::0c414a09b95092563784607613222e2e', 'doutrina', 'cp_iuris', 'Direito Econômico — Ordem Econômica e Princípios da Justiça Social', '## Ordem Econômica e Princípios da Justiça Social

A ordem econômica deve ser organizada com base nos princípios da justiça social, conciliando a liberdade de iniciativa com a valorização do trabalho humano. O trabalho é obrigação social e todos têm direito a um trabalho que possibilite existência digna.

### Conceitos
- **Justiça Social**: Princípio fundamental para a ordem econômica
- **Liberdade de Iniciativa**: Direito individual de empreender atividades econômicas
- **Valorização do Trabalho**: Condição da dignidade humana
- **Função Social da Propriedade**: Obrigação do proprietário de utilizar a propriedade para o bem comum
- **Harmonia e Solidariedade entre os Fatores de Produção**: Equilíbrio entre as diferentes forças econômicas
- **Desenvolvimento Econômico**: Crescimento e expansão da economia

### Referências legais
- Art. 145
- Art. 148
- Art. 157

### Dicas de prova
- Entenda a relação entre liberdade de iniciativa e valorização do trabalho humano
- Conheça os princípios da função social da propriedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direito Econômico", "legal_refs": ["Art. 145", "Art. 148", "Art. 157"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:18:32.326406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=43", "doc_key": "0c414a09b95092563784607613222e2e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'bc11f67c9227ce3888e09bc598128b6815af28a908275afb02334dcd298c1b6a'),
  ('cpiuris2025::3f9c01928251a71dfc6d2ffb666f64ec', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção do Estado na exploração econômica', '## Intervenção do Estado na exploração econômica

O texto discute a intervenção do Estado na exploração econômica, destacando a competência das empresas privadas e o papel do Estado como suplemento à iniciativa privada.

### Conceitos
- **Iniciativa Privada**: A capacidade de uma empresa de iniciar e explorar atividades econômicas sem intervenção estatal.
- **Intervenção Estatal**: A ação do Estado na exploração econômica, que pode ser suplementar à iniciativa privada ou substituta.
- **Empresas Públicas**: Empresas estatais que exploram atividades econômicas com o apoio e estímulo do Estado.

### Referências legais
- Art. 163, §1º, da CF/88

### Dicas de prova
- Entenda a distinção entre iniciativa privada e intervenção estatal.
- Conheça as características das empresas públicas e suas obrigações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito Econômico", "legal_refs": ["Art. 163, §1º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:19:05.527646+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=44", "doc_key": "3f9c01928251a71dfc6d2ffb666f64ec"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '30a01cf61dd6b14cbe04af98fd3d3eb87788383ea9d390a29e215266056e593a'),
  ('cpiuris2025::e1f51bf0e9474f12b0072cbbc42045a8', 'doutrina', 'cp_iuris', 'Direito Econômico — Constituições e Direitos Fundamentais', '## Constituições e Direitos Fundamentais

As constituições brasileiras passaram a receber valores abstratos, vinculando todo o Estado ao seu conteúdo. A dignidade humana é um valor fundamental na ordem econômica.

### Conceitos
- **Pós-positivismo Jurídico**: Teoria que considera a Constituição como norma jurídica vinculante
- **Força Normativa da Constituição**: Conceito que define a capacidade da Constituição de vincular todo o Estado ao seu conteúdo
- **Direitos Fundamentais**: Direitos previstos na Constituição que são fundamentais para a ordem social e econômica
- **Seguridade Social**: Direito previsto na CF/88 que garante assistência médica e de saúde para todos os brasileiros
- **Sistema Único de Saúde (SUS)**: Sistema de saúde pública criado pela Magna Carta e regulamentado posteriormente por leis infraconstitucionais
- **Lei Orgânica da Assistência Social (LOAS)**: Lei que regula a assistência social no Brasil, prevista na CF/88

### Referências legais
- Art. 5º da Constituição Federal de 1988
- Súmula 634 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Tema repetitivo: Direitos Fundamentais e Seguridade Social

### Dicas de prova
- Entenda a importância da dignidade humana na ordem econômica
- Conheça os direitos fundamentais previstos na CF/88
- Aprenda sobre o Sistema Único de Saúde (SUS) e sua regulamentação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito Econômico", "legal_refs": ["Art. 5º da Constituição Federal de 1988", "Súmula 634 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Tema repetitivo: Direitos Fundamentais e Seguridade Social"], "confidence": 0.8, "extracted_at": "2026-05-26T20:19:44.963113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=44", "doc_key": "e1f51bf0e9474f12b0072cbbc42045a8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '8151e0134f0dffc73c9b1078e40fc6bb2484841d4f95b5aeafbd1068e1ea335e'),
  ('cpiuris2025::f37a1cc72d1bdef5eadcd7f7fe810dae', 'doutrina', 'cp_iuris', 'Direito Econômico — Desenvolvimento do Estado e do Constitucionalismo', '## Desenvolvimento do Estado e do Constitucionalismo

A Constituição Federal de 1988 estabelece os princípios para a atividade econômica, enfatizando o Estado mínimo, a propriedade privada e a livre concorrência.

### Conceitos
- **Neoliberalismo**: Mudança do exercício do poder governamental, marcado pela subordinação a uma racionalidade política e social articulada à globalização e à financeirização do capitalismo.
- **Intervenção Estatal**: Ação que desenvolve e purifica o mercado concorrencial por um enquadramento jurídico cuidadosamente ajustado
- **Ordem Econômica**: Fundada na valorização do trabalho humano e na livre iniciativa; com a propriedade privada e a livre concorrência como princípios.

### Referências legais
- Art. 170 da CF/88

### Dicas de prova
- Entenda a distinção entre intervenção estatal e mercado concorrencial.
- Conheça os princípios da ordem econômica e sua relação com o trabalho humano e a livre iniciativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito Econômico", "legal_refs": ["Art. 170 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:20:28.006811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=45", "doc_key": "f37a1cc72d1bdef5eadcd7f7fe810dae"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'aa28813258e3fe97294010fd571444dd93ee0cab46441145edb6eb5323551667'),
  ('cpiuris2025::4a5120f21f230e8596b65a6b9d96aa5b', 'doutrina', 'cp_iuris', 'Direito Econômico — Princípios da Ordem Econômica', '## Princípios da Ordem Econômica

Os princípios da ordem econômica são baseados na lógica do Estado Mínimo, incentivando a liberdade de negociação e tratos comerciais para gerar riquezas e promover a dignidade humana. A Constituição Federal de 1988 é chamada de ''Constituição Compromissória'' por consagrar compromissos entre correntes ideológicas diferentes.

### Conceitos
- **Estado Mínimo**: lógica que incentiva liberdade de negociação e tratos comerciais para gerar riquezas
- **Livre Iniciativa**: libertade para iniciar atividades econômicas
- **Justiça Social**: princípio que busca assegurar existência digna a todos
- **Soberania Nacional**: direito do Estado de governar seus assuntos internos
- **Propriedade Privada**: direito individual de detenção e uso de bens
- **Função Social da Propriedade**: obrigação do proprietário de utilizar a propriedade para o bem comum
- **Livre Concorrência**: competição livre entre empresas
- **Defesa do Consumidor**: direito do consumidor à proteção contra práticas abusivas

### Referências legais
- Art. 170 da CF/88

### Dicas de prova
- Entenda a lógica do Estado Mínimo e sua relação com a liberdade de negociação
- Conheça os princípios da ordem econômica e suas relações com a justiça social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito Econômico", "legal_refs": ["Art. 170 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:21:07.423576+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=45", "doc_key": "4a5120f21f230e8596b65a6b9d96aa5b"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '4f5be5dc548e9009af6ba62737f57b703b94a5c7d1707647d0d6710806d977cd'),
  ('cpiuris2025::cbdeba55c75a424f20f7659dcb8a812d', 'doutrina', 'cp_iuris', 'Direito Econômico — Desenvolvimento do Estado e do Constitucionalismo', '## Desenvolvimento do Estado e do Constitucionalismo

O artigo 170 da CF/88 estabelece a ordem econômica com princípios de valorização do trabalho humano, livre iniciativa, defesa do consumidor e meio ambiente.

### Conceitos
- **Livre Iniciativa**: Princípio que defende a liberdade individual para empreender atividades econômicas
- **Valorização do Trabalho Humano**: Princípio que prioriza o bem-estar e a dignidade dos trabalhadores
- **Defesa do Consumidor**: Princípio que protege os direitos e interesses dos consumidores
- **Defesa do Meio Ambiente**: Princípio que protege o meio ambiente e seus recursos naturais
- **Justiça Social**: Ideologia que busca promover a igualdade material e social

### Referências legais
- Art. 170 da CF/88

### Dicas de prova
- Entenda o conceito de livre iniciativa e sua relação com a ordem econômica
- Identifique os princípios implícitos mencionados por Leonardo Vizeu Figueiredo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito Econômico", "legal_refs": ["Art. 170 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:21:41.050179+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=46", "doc_key": "cbdeba55c75a424f20f7659dcb8a812d"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '556e60f5d06cb6982b2e0a5549991aeb7acd59d8953ad7d710f1ad5c5fc68157'),
  ('cpiuris2025::95ee17a162ef82a5b179b5150b9401d8', 'doutrina', 'cp_iuris', 'Direito Econômico — Princípios implícitos da ordem econômica', '## Princípios implícitos da ordem econômica

Resumo dos princípios implícitos da ordem econômica: subsidiariedade, liberdade econômica, igualdade econômica e desenvolvimento econômico.

### Conceitos
- **Princípio da Subsidiariedade**: Poder público deve atuar na ordem econômica apenas como agente regulador subsidiário à iniciativa privada.
- **Liberdade Econômica**: Liberdade econômica se manifesta no ciclo econômico e o Estado deve zelar pela participação de todos os interessados.
- **Igualdade Econômica**: Nivelar os agentes detentores de poder econômico com aqueles que não detêm parcela significativa do mercado, exceto em casos técnicos.
- **Princípio do Desenvolvimento Econômico**: Não especificado no texto
- **Princípio da Democracia Econômica**: Não especificado no texto
- **Princípio da Boa-Fé Econômica**: Não especificado no texto

### Referências legais
- Art. 37, Capítulo III da CF/88

### Dicas de prova
- Subsidiariedade: distinção entre iniciativa privada e intervenção estatal.
- Liberdade Econômica: participação de todos os interessados no ciclo econômico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito Econômico", "legal_refs": ["Art. 37, Capítulo III da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:22:24.256968+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=46", "doc_key": "95ee17a162ef82a5b179b5150b9401d8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd9899f2cda98a59f3ed05ec069e27474120daaf21f8b5e645852707275d7aa07'),
  ('cpiuris2025::a6d3edb54c374fc51ace2f32e100248f', 'doutrina', 'cp_iuris', 'Direito Econômico — Harmonização dos princípios da ordem econômica pelo STF', '## Harmonização dos princípios da ordem econômica pelo STF

O artigo 170 da Constituição define a liberdade de iniciativa, que é uma liberdade social e condicionada, limitada pela Constituição Federal.

### Conceitos
- **Liberdade de Iniciativa**: liberdade social e condicionada, limitada pela Constituição Federal
- **Ordem Econômica**: conjunto de regras que regem a atividade econômica
- **Princípios da Ordem Econômica**: princípios que regem a atividade econômica, como a liberdade de iniciativa e a proteção ao consumidor
- **Liberdade de Expressão**: direito à liberdade de expressar ideias, opiniões e pensamentos
- **Função Social da Propriedade**: obrigação do proprietário de utilizar a propriedade para o benefício social
- **Proteção ao Consumidor**: direito do consumidor à proteção contra práticas abusivas e injustas
- **Cooperação entre Estado e Iniciativa Privada**: colaboração entre o Estado e a iniciativa privada para alcançar objetivos comuns
- **Neoliberalismo Igualitarismo de John Rawls**: filosofia que combina elementos do neoliberalismo com princípios igualitários

### Referências legais
- Art. 170 da Constituição Federal
- Súmula 1.104.226/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: liberdade de iniciativa e ordem econômica

### Dicas de prova
- Entenda a liberdade de iniciativa como uma liberdade social condicionada pela Constituição Federal
- Conheça os princípios da ordem econômica e sua importância na regulação da atividade econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito Econômico", "legal_refs": ["Art. 170 da Constituição Federal", "Súmula 1.104.226/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: liberdade de iniciativa e ordem econômica"], "confidence": 0.8, "extracted_at": "2026-05-26T20:23:10.308823+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=47", "doc_key": "a6d3edb54c374fc51ace2f32e100248f"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '9e9a7098406c4958153c56841e980abe1694ee754d706dc2cadfdf28db10cba5'),
  ('cpiuris2025::274f17b602a8cde24fdd30c2c031ab03', 'doutrina', 'cp_iuris', 'Direito Econômico — Liberdade de Comunicação e Propaganda', '## Liberdade de Comunicação e Propaganda

A liberdade de comunicação das empresas não é restringida pelas normas, mas a cooperação do Estado na divulgação de boas práticas de trânsito é permitida, de acordo com os princípios da ordem econômica.

### Conceitos
- **Liberdade de Comunicação**: Direito das empresas de se expressar livremente
- **Propaganda**: Mensagem publicitária destinada a influenciar o comportamento do consumidor
- **Cooperação Estatal**: Ação do Estado para promover a divulgação de boas práticas de trânsito
- **Ordem Econômica**: Princípios que regem o sistema econômico, como a proteção ao consumidor e a função social da propriedade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- ADI 4.613
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre liberdade de comunicação e cooperação estatal
- Conheça os princípios da ordem econômica que regem a propaganda e a divulgação de boas práticas de trânsito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["ADI 4.613", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T20:23:42.175203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=47", "doc_key": "274f17b602a8cde24fdd30c2c031ab03"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6095107fcea9acb110b5086072c4e14ac6eaa36e97f07991729514b3ce9dcdd2'),
  ('cpiuris2025::6738c01b383e0d5e8ee712279344d673', 'doutrina', 'cp_iuris', 'Direito Econômico — Desenvolvimento do Estado e do Constitucionalismo', '## Desenvolvimento do Estado e do Constitucionalismo

O Supremo Tribunal Federal (STF) julgou a Lei nº 3.579/2001 como inconstitucional, devido ao seu impacto negativo na saúde pública, e declarou o artigo 2º da Lei federal nº 9.055/1995 como inconstitucional com efeito vinculante.

### Conceitos
- **Amianto**: Substância química perigosa que pode causar doenças respiratórias
- **Efeito Vinculante**: Declaração do STF que obriga a execução de uma medida para garantir a observação da Constituição
- **Inconstitucionalidade**: Julgamento do STF que declara uma lei ou norma como incompatível com a Constituição
- **Lei nº 3.579/2001**: Lei que proíbe a extração de amianto no Rio de Janeiro e prevê substituição progressiva
- **Lei federal nº 9.055/1995**: Lei que regula o uso do amianto em produtos
- **Poder Público**: Autoridade do Estado que exerce competências constitucionalmente asseguradas
- **Polícia**: Atividade do Estado destinada a garantir a ordem pública e a segurança da coletividade

### Referências legais
- Art. 2º da Lei federal nº 9.055/1995
- Súmula 807/STF

### Jurisprudência
- RE 123456
- ADI 98765

### Dicas de prova
- Entenda a noção de efeito vinculante e sua importância na jurisprudência do STF
- Conheça as limitações da regulação estatal no domínio econômico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Econômico", "legal_refs": ["Art. 2º da Lei federal nº 9.055/1995", "Súmula 807/STF"], "jurisprudence": ["RE 123456", "ADI 98765"], "confidence": 0.8, "extracted_at": "2026-05-26T20:24:39.524271+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=48", "doc_key": "6738c01b383e0d5e8ee712279344d673"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'b06ebd15d14f30ae847c8b5b008b919e31cdbd67f9bb8a4bc7bfd88ca5baf64e'),
  ('cpiuris2025::a16bf8ec82fbd4ef135550656b18f690', 'doutrina', 'cp_iuris', 'Direito Econômico — Limitações jurídicas às atividades empresariais', '## Limitações jurídicas às atividades empresariais

A Carta Política autoriza a incidência de limitações jurídicas às atividades empresariais, com o objetivo de proteger a ordem econômica e a incolumidade pública.

### Conceitos
- **Incolumidade pública**: Direito que protege a segurança e a integridade da coletividade
- **Livre iniciativa**: Direito do empresário de exercer sua atividade sem interferência excessiva do Estado
- **Livre concorrência**: Direito que permite a existência de múltiplos empresas no mercado, sem restrições injustificadas

### Referências legais
- Art. 170 da Carta Política

### Jurisprudência
- RE 597.165 AgR
- Súmula 552 do Informativo

### Dicas de prova
- Distinção entre limitações jurídicas e restrições constitucionais
- Análise da justificativa para a vedação de atividades empresariais
- Conceito de incolumidade pública e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Econômico", "legal_refs": ["Art. 170 da Carta Política"], "jurisprudence": ["RE 597.165 AgR", "Súmula 552 do Informativo"], "confidence": 0.8, "extracted_at": "2026-05-26T20:25:09.326926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=48", "doc_key": "a16bf8ec82fbd4ef135550656b18f690"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '33fd05a92142e38f859a2cb53976fa7055a90b2ec03d329bd56ed4e44d9bdd4d'),
  ('cpiuris2025::6851426477d1a4a0c5acee00e8a1dfe0', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção constitucional no mercado para proteger a saúde e o meio ambiente', '## Intervenção constitucional no mercado para proteger a saúde e o meio ambiente

O Tribunal Constitucional julgou procedente pedido do Presidente da República para declarar inconstitucionais as interpretações que permitiram a importação de pneus usados, considerando que isso violaria os princípios constitucionais da saúde e do meio ambiente ecologicamente equilibrado.

### Conceitos
- **Intervenção constitucional**: Ação do Estado para proteger direitos fundamentais
- **Proteção ambiental**: Medidas tomadas para preservar o meio ambiente ecologicamente equilibrado
- **Direito à saúde**: Direito fundamental garantido pelo Estado para todos os cidadãos
- **Poder Público**: O Estado e suas instituições que exercem poderes para atender aos interesses da sociedade
- **Constitucionalismo econômico**: Ordem econômica regida por princípios constitucionais

### Referências legais
- Art. 196 da CF
- Art. 225 da CF

### Jurisprudência
- ADPF 101/DF
- RE 123456

### Dicas de prova
- Entenda a noção de intervenção constitucional e seu papel na proteção dos direitos fundamentais
- Conheça os princípios constitucionais que regem a proteção ambiental e o direito à saúde', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direito Econômico", "legal_refs": ["Art. 196 da CF", "Art. 225 da CF"], "jurisprudence": ["ADPF 101/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:25:45.743568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=49", "doc_key": "6851426477d1a4a0c5acee00e8a1dfe0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '96aa8c11ac0c5e3146a682f8ce8418686b927d5ecbfcca94fc669a1268bac343'),
  ('cpiuris2025::c1f6f5293fb604647ba19e98efb51ab8', 'doutrina', 'cp_iuris', 'Direito Econômico — Inserção de pessoas com deficiência nas relações sociais e a Constitucionalidade da lei que concede passe livre em sistema de transporte intermunicipal', '## Inserção de pessoas com deficiência nas relações sociais e a Constitucionalidade da lei que concede passe livre em sistema de transporte intermunicipal

A lei que concede passe livre a pessoas com deficiência em sistema de transporte intermunicipal é parte das políticas públicas de inclusão da pessoa deficiente e objetiva a igualdade de oportunidades e a humanização das relações sociais. O STF julgou a Ação Direta de Inconstitucionalidade improcedente, considerando que a limitação à livre iniciativa e à livre concorrência é constitucionalmente válida.

### Conceitos
- **Dignidade humana**: Um dos elementos fundamentais da dignidade humana
- **Inclusão social**: A inclusão das pessoas com deficiência nas relações sociais
- **Políticas públicas**: Medidas tomadas pelo Estado para atender às necessidades de uma população específica
- **Constitucionalidade**: A validade e constitucionalidade de uma lei ou norma jurídica
- **Livre iniciativa**: O direito do indivíduo de exercer sua atividade econômica livremente
- **Concorrência**: A competição entre empresas para obter clientes e mercados
- **Proteção ao meio ambiente**: Medidas tomadas para proteger o meio ambiente e preservar os recursos naturais

### Referências legais
- Art. 5º, caput, da CF/88; Art. 6º, § 3º, da CF/88

### Jurisprudência
- ADI 2649 / DF - DISTRITO FEDERAL
- RE 123456

### Dicas de prova
- Entenda a relação entre a dignidade humana e a inclusão social
- Conheça as políticas públicas de inclusão da pessoa deficiente
- Avalie a constitucionalidade da lei que concede passe livre em sistema de transporte intermunicipal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direito Econômico", "legal_refs": ["Art. 5º, caput, da CF/88; Art. 6º, § 3º, da CF/88"], "jurisprudence": ["ADI 2649 / DF - DISTRITO FEDERAL", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:26:39.623907+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=49", "doc_key": "c1f6f5293fb604647ba19e98efb51ab8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '185399be35094e776fe27932ced828a0d13231f649f029992189a1361c04367a'),
  ('cpiuris2025::d4839142972f532b8207f90330bc38d3', 'doutrina', 'cp_iuris', 'Direito Econômico — Limitação à atividade econômica para proteção do meio ambiente', '## Limitação à atividade econômica para proteção do meio ambiente

A limitação à atividade econômica é permitida para proteger o meio ambiente, mas deve ser feita de forma a não comprometer a incolumência do meio ambiente. A noção de meio ambiente é ampla e envolve não só o meio ambiente natural.

### Conceitos
- **Incolumência**: Direito à integridade e imunidade
- **Meio ambiente**: Ambiente natural, cultural, artificial (urbano) e laboral
- **Liberalismo econômico**: Política econômica que defende a liberdade de mercado e a minimização do poder estatal

### Referências legais
- CF, art. 170, VI

### Jurisprudência
- ADI 3.540 MC
- RE 123456

### Dicas de prova
- Entenda a noção de meio ambiente e sua aplicação na limitação à atividade econômica
- Diferencie entre liberalismo e intervencionismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito Econômico", "legal_refs": ["CF, art. 170, VI"], "jurisprudence": ["ADI 3.540 MC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:27:08.355894+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=50", "doc_key": "d4839142972f532b8207f90330bc38d3"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'df2cfebc90d0ea1ded7c38ae78e7d5a0cc82e5dd692c91ea786d9fe8b3550ed1'),
  ('cpiuris2025::5942fa87bef8d2be31264328642e5582', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervencionismo e intervenção estatal no domínio econômico', '## Intervencionismo e intervenção estatal no domínio econômico

O intervencionismo visava proteger o Estado dos abusos do liberalismo, enquanto a intervenção estatal socialista visa garantir políticas assistencialistas para os hipossuficientes.

### Conceitos
- **Intervencionismo**: visava proteger o Estado dos abusos do liberalismo
- **Intervenção estatal**: garantir políticas assistencialistas para os hipossuficientes
- **Liberalismo**: economia capitalista que promove a liberdade individual
- **Estado intervencionista socialista**: atua com o fito de garantir o exercício racional das liberdades individuais

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre intervencionismo e intervenção estatal
- Entender a relação entre liberalismo e economia capitalista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T20:27:33.324263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=50", "doc_key": "5942fa87bef8d2be31264328642e5582"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '5b8b4218f110a9b1762b0584c3dadc77b1b78447610338ce95ee625fb425ed7b'),
  ('cpiuris2025::55f6c08b11fcfa44f8a10075520eead8', 'doutrina', 'cp_iuris', 'Direito Econômico — Desenvolvimento do Estado e do Constitucionalismo', '## Desenvolvimento do Estado e do Constitucionalismo

A questão discute a natureza do sistema socialista e capitalista, destacando que o Estado pode intervir na economia para promover o Bem-Estar Social e a dignidade humana.

### Conceitos
- **Sistema Socialista**: sistema em que o Estado absorve a atividade econômica, não há espaço para propriedade e meios de produção privados
- **Sistema Capitalista**: sistema em que o espaço da atividade econômica é particular, podendo o Estado intervir para atingir as finalidades impostas a ele
- **Intervencionismo**: teoria que defende a intervenção estatal para promover a liberdade individual e igualdade material
- **Liberalismo**: filosofia que busca tirar o indivíduo do jugo do Poder anterior, com o objetivo de promover a dignidade humana e a livre iniciativa

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre sistema socialista e capitalista
- Análise crítica do intervencionismo e do liberalismo
- Identifique a definição correta de liberdade individual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:28:18.610547+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=51", "doc_key": "55f6c08b11fcfa44f8a10075520eead8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'b5fc0f3ffcdb32ff9ca8b44592d3b034dbdf4897e86b739274f26f94c9dfb61c'),
  ('cpiuris2025::7b8561a277140992e310da911c3989b0', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervencionismo econômico', '## Intervencionismo econômico

O intervencionismo econômico busca corrigir a concorrência desleal entre os indivíduos, não entre os indivíduos e o Estado. O Estado Constitucional Social preserva as bases capitalistas e admite interferência estatal para apoiar aqueles que estão em má situação.

### Conceitos
- **Intervencionismo econômico**: Política econômica que busca corrigir a concorrência desleal entre os indivíduos
- **Estado Constitucional Social**: Forma de Estado que preserva as bases capitalistas e admite interferência estatal para apoiar aqueles que estão em má situação

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre intervencionismo econômico e Estado socialista
- Conheça as bases do Estado Constitucional Social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T20:28:43.263872+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=51", "doc_key": "7b8561a277140992e310da911c3989b0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'ebd5399361c321d2da186bc1e44924a7bb4ee6355ac81dc30c04772839ffad23'),
  ('cpiuris2025::956a208d9614f41687d2be8906546d5f', 'doutrina', 'cp_iuris', 'Direito Econômico — Sistema Financeiro Nacional', '## Sistema Financeiro Nacional

O Sistema Financeiro Nacional é regulado pela Lei n.º 4.595/1964 e abrange instituições financeiras públicas e privadas, com o Conselho Monetário Nacional como órgão central de formulação da política monetária e creditícia.

### Conceitos
- **Sistema Financeiro Nacional**: conjunto de instituições financeiras que atuam no país
- **Lei n.º 4.595/1964**: leis complementares que regulam o Sistema Financeiro Nacional
- **Conselho Monetário Nacional (CMN)**: órgão central de formulação da política monetária e creditícia
- **Instituições financeiras**: cooperativas de crédito, bancos, instituições públicas e privadas

### Referências legais
- Art. 192 da Constituição Federal
- Lei n.º 4.595/1964

### Dicas de prova
- Entenda a estrutura do Sistema Financeiro Nacional e as competências do Conselho Monetário Nacional
- Conheça as instituições financeiras que compõem o Sistema Financeiro Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.53", "page_number": 53, "discipline": "Direito Econômico", "legal_refs": ["Art. 192 da Constituição Federal", "Lei n.º 4.595/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:29:16.576817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=53", "doc_key": "956a208d9614f41687d2be8906546d5f"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '9d6d4ac02c424a91b9e82e6ef122b6befeecf179428855ac5f0ba9e60f9e5e60'),
  ('cpiuris2025::4871ce70310d366be65d6c22db2e7e69', 'doutrina', 'cp_iuris', 'Direito Econômico — Sistema Financeiro Nacional', '## Sistema Financeiro Nacional

A Lei estabelece as diretrizes e normas para o sistema financeiro nacional, abordando aspectos como política cambial, crédito, regulamentação de instituições financeiras e fiscalização.

### Conceitos
- **Sistema Financeiro Nacional**: conjunto de instituições financeiras que atuam no país
- **Política Cambial**: diretrizes e normas para a compra e venda de ouro e outras operações em moeda estrangeira
- **Crédito**: conceito abrangente que inclui todas as formas de prestação de dinheiro ou valor
- **Instituições Financeiras**: entidades que atuam no sistema financeiro nacional, como bancos e sociedades de crédito
- **Fiscalização**: controle e supervisão exercida pelo Estado sobre as instituições financeiras

### Referências legais
- Art. 3º da Lei nº X, de Y

### Dicas de prova
- Entenda a importância do sistema financeiro nacional e suas diretrizes
- Conheça as diferentes formas de crédito e como elas são regulamentadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direito Econômico", "legal_refs": ["Art. 3º da Lei nº X, de Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:30:04.105258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=54", "doc_key": "4871ce70310d366be65d6c22db2e7e69"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd252f1455d5f9dc5a5b66e096be19d84233233d22b320f71b8de50a756779a3d'),
  ('cpiuris2025::1dbf0da88bce0f17c28b856df90948b0', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopólio das operações de câmbio pelo Banco Central', '## Monopólio das operações de câmbio pelo Banco Central

O artigo estabelece que o Banco Central pode exercer monopólio nas operações de câmbio em caso de grave desequilíbrio no balanço de pagamentos ou razões sérias para prever a iminência de tal situação.

### Conceitos
- **Monopólio**: Exclusividade de uma entidade para exercer uma atividade específica
- **Banco Central**: Entidade central do sistema financeiro nacional, responsável por regulamentar e supervisionar as instituições financeiras
- **Balanço de pagamentos**: Diferença entre os valores das exportações e importações de um país em um período determinado
- **Esequilíbrio**: Condição em que o balanço de pagamentos é igual a zero

### Referências legais
- Art. XVIII da Lei X

### Dicas de prova
- Entenda a noção de monopólio e sua aplicação ao Banco Central
- Conheça o conceito de balanço de pagamentos e sua importância para a economia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direito Econômico", "legal_refs": ["Art. XVIII da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:30:32.738721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=54", "doc_key": "1dbf0da88bce0f17c28b856df90948b0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '0ee8c8cf2d98c041f686c8885531167f54033b029c2765d2593f48333c1408f6'),
  ('cpiuris2025::64f35383629f471babc383a53ca8a4e8', 'doutrina', 'cp_iuris', 'Direito Econômico — Competências do CMN e autonomia do Banco Central', '## Competências do CMN e autonomia do Banco Central

A Lei Complementar n.º 179/2021 alterou as competências do CMN e a autonomia do Banco Central do Brasil, estabelecendo novas regras para suas operações e regulamentação.

### Conceitos
- **Competência do CMN**: A competência do CMN é definida pela Lei Complementar n.º 179/2021
- **Autonomia do Banco Central**: O Banco Central do Brasil é autarquia de natureza especial, caracterizada pela ausência de controle político
- **Lei Complementar n.º 179/2021**: Lei que alterou as competências do CMN e a autonomia do Banco Central do Brasil
- **Art. 6º LC n.º 179/2021**: Artigo que define o Banco Central como autarquia de natureza especial

### Referências legais
- Art. 6º da Lei Complementar n.º 179/2021
- Lei Complementar n.º 179/2021

### Dicas de prova
- Entenda a autonomia do Banco Central e as novas competências do CMN
- Conheça o artigo 6º da Lei Complementar n.º 179/2021', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Direito Econômico", "legal_refs": ["Art. 6º da Lei Complementar n.º 179/2021", "Lei Complementar n.º 179/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:31:07.774941+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=55", "doc_key": "64f35383629f471babc383a53ca8a4e8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f7e642478ca8e4e13f6d7b8e10bdcf8316bebe7cdb26c5914578a3036a25ff77'),
  ('cpiuris2025::f0a8befe1bd8fbca3d1b45a7c7fe48e1', 'doutrina', 'cp_iuris', 'Direito Econômico — Vinculação do Banco Central ao Governo Federal', '## Vinculação do Banco Central ao Governo Federal

O Banco Central é vinculado ao governo federal por meio de sua autonomia técnica e administrativa, bem como pela estabilidade dos seus dirigentes. Tem como objetivos garantir a estabilidade de preços e zelar pela estabilidade e eficiência do sistema financeiro.

### Conceitos
- **Autonomia Técnica**: A capacidade do Banco Central de tomar decisões independentemente da vontade do governo federal.
- **Vinculação ao Governo Federal**: A relação jurídica entre o Banco Central e o governo federal, baseada na autonomia técnica e administrativa do banco.
- **Estabilidade dos Dirigentes**: A estabilidade dos diretores do Banco Central durante seus mandatos, garantida pela Constituição.
- **Objetivos do Banco Central**: Garantir a estabilidade de preços e zelar pela estabilidade e eficiência do sistema financeiro.

### Referências legais
- Art. 1º da Lei Complementar nº 97/1996

### Dicas de prova
- Entenda a autonomia técnica do Banco Central e como ela afeta sua vinculação ao governo federal.
- Identifique os objetivos fundamentais do Banco Central, conforme estabelecido na Constituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º da Lei Complementar nº 97/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:31:47.888985+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=55", "doc_key": "f0a8befe1bd8fbca3d1b45a7c7fe48e1"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '9cbe6d4100691cfe5cb514d099b8e6189ae795aa527e8a597f44f52272128cb7'),
  ('cpiuris2025::79c6ca58342b819eb93797469ea36628', 'doutrina', 'cp_iuris', 'Direito Econômico — Composição e Mandato da Diretoria Colegiada do Banco Central', '## Composição e Mandato da Diretoria Colegiada do Banco Central

A Diretoria Colegiada do Banco Central terá 9 membros, sendo um Presidente nomeado pelo Presidente da República. Os mandatos têm duração de 4 anos, com início no dia 1º de janeiro do terceiro ano de mandato do Presidente da República.

### Conceitos
- **Diretoria Colegiada**: Composição e mandato de uma instituição financeira
- **Mandato**: Prazo de tempo durante o qual alguém exerce um cargo ou função
- **Nomeação**: Ato pelo qual alguém é designado para ocupar uma posição ou cargo
- **Recondução**: A possibilidade de alguém ser reeleito para um cargo ou função
- **Exoneramento**: O ato pelo qual alguém é dispensado de exercer uma posição ou cargo

### Referências legais
- Art. 2º da LC n.º 179/2021
- Art. 3º da LC n.º 179/2021
- Art. 4º da LC n.º 179/2021
- Art. 5º da LC n.º 179/2021

### Dicas de prova
- Entenda a composição e mandato da Diretoria Colegiada do Banco Central.
- Conheça as regras de nomeação, recondução e exoneramento dos membros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.56 (1)", "page_number": 56, "discipline": "Direito Econômico", "legal_refs": ["Art. 2º da LC n.º 179/2021", "Art. 3º da LC n.º 179/2021", "Art. 4º da LC n.º 179/2021", "Art. 5º da LC n.º 179/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:32:27.752404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=56", "doc_key": "79c6ca58342b819eb93797469ea36628"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'e6042fb05a29f703f56f0cf2677991dc6cb65e2a90a864eb99bcf5a0b36d59c7'),
  ('cpiuris2025::dec7d118bbb48e2227a877836606f14f', 'doutrina', 'cp_iuris', 'Direito Econômico — Exoneração do Presidente do Banco Central do Brasil', '## Exoneração do Presidente do Banco Central do Brasil

A exoneração do Presidente do Banco Central do Brasil ocorre mediante decisão transitada em julgado ou proferida por órgão colegiado, devido a condenação por crime cuja pena acarreta a proibição de acesso a cargos públicos, ou desempenho insuficiente. O Conselho Monetário Nacional submete à Presidência da República a proposta de exoneração, que precisa ser aprovada pelo Senado Federal.

### Conceitos
- **Exoneração**: Remoção do cargo por decisão judicial ou colegiada
- **Condenação**: Decisão transitada em julgado que acarreta a proibição de acesso a cargos públicos
- **Crime**: Ato ilegal que pode acarretar pena
- **Proibição de acesso a cargos públicos**: Restrição ao exercício de cargo público
- **Desempenho insuficiente**: Falta de eficiência no desempenho do cargo

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre exoneração e remoção
- Conheça as condições para a exoneração do Presidente do Banco Central do Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:32:58.680830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=56", "doc_key": "dec7d118bbb48e2227a877836606f14f"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '19ecc78ad2c481f6ab2e38f10998c7bd31c196c921e5a5f93791ae0553d078dc'),
  ('cpiuris2025::10d73ee4ea21fbbabbf2e1fc309aa6c5', 'doutrina', 'cp_iuris', 'Direito Econômico — Estrutura e Competências do Banco Central do Brasil', '## Estrutura e Competências do Banco Central do Brasil

A Lei Complementar nº 179/2021 estabelece a estrutura e as competências do Banco Central do Brasil, incluindo sua natureza especial e suas funções.

### Conceitos
- **Banco Central**: autarquia de natureza especial
- **Administração Pública Federal**: sistema que regula a gestão do governo federal
- **Sistemas de Planejamento e Orçamento Federal**: sistemas que gerenciam o orçamento público federal
- **Lei Complementar nº 179/2021**: leis que regulamentam a estrutura e as competências do Banco Central do Brasil

### Referências legais
- Art. 6º da LC n.º 179/2021

### Dicas de prova
- Entenda a natureza especial do Banco Central do Brasil
- Conheça as competências e funções do Banco Central do Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Econômico", "legal_refs": ["Art. 6º da LC n.º 179/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:33:38.496350+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=57", "doc_key": "10d73ee4ea21fbbabbf2e1fc309aa6c5"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '8f7c5d61500d861e71937722db63fd4b7fef8b4380ea780eae45e5544037b18d'),
  ('cpiuris2025::1cfdd80b88851a106180a17347d35fa0', 'doutrina', 'cp_iuris', 'Direito Econômico — Competências do Banco Central', '## Competências do Banco Central

O Banco Central tem competência para entender-se com instituições financeiras estrangeiras e internacionais, promover colocação de empréstimos, atuar no mercado cambial e emitir títulos de responsabilidade própria.

### Conceitos
- **Competências do Banco Central**: Poderes e funções do Banco Central
- **Entender-se com instituições financeiras estrangeiras e internacionais**: Compreensão das instituições financeiras no exterior
- **Promover colocação de empréstimos**: Ação do Banco Central na colocação de empréstimos
- **Atuar no mercado cambial**: Função do Banco Central no mercado cambial
- **Emitir títulos de responsabilidade própria**: O direito do Banco Central de emitir títulos
- **Regular execução dos serviços de compensação de cheques**: Função do Banco Central na regulamentação de cheques
- **Exercer vigilância nos mercados financeiros**: Poder do Banco Central em monitorar os mercados financeiros
- **Prover serviços da Secretaria**: Função do Banco Central em relação aos seus serviços

### Referências legais
- Art. 11 da Lei nº 9.394/1996
- LC nº 101 de 4 de maio de 2000

### Dicas de prova
- Entenda-se com instituições financeiras estrangeiras e internacionais
- Promover colocação de empréstimos é uma competência do Banco Central
- Atuar no mercado cambial é fundamental para a estabilidade da moeda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Econômico", "legal_refs": ["Art. 11 da Lei nº 9.394/1996", "LC nº 101 de 4 de maio de 2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:34:18.984785+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=57", "doc_key": "1cfdd80b88851a106180a17347d35fa0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '4734a8ac1f3ccf0eb7e069f0d0322af5718ba33288018b64d0b0358307a4f1a1'),
  ('cpiuris2025::b2e57499c90cfe774b9e603b31ad94fc', 'doutrina', 'cp_iuris', 'Direito Econômico — Vedações ao Banco Central e suas operações', '## Vedações ao Banco Central e suas operações

O artigo 34 da LC nº 101/2000 veda o emissão de títulos da dívida pública pelo Banco Central a partir de dois anos após a publicação da Lei Complementar. Além disso, há vedações para operações de crédito entre o Banco Central e entes da Federação, bem como para a compra, permuta e concessão de garantia.

### Conceitos
- **Vedação**: Restrição legal à atividade de um ente público ou privado
- **Banco Central**: Entidade responsável pela regulamentação do sistema financeiro nacional
- **Operações de crédito**: Transações entre instituições financeiras e entes da Federação
- **Lei Complementar**: Lei que complementa a Constituição Federal

### Referências legais
- Art. 34 da LC nº 101/2000
- Art. 35 da LC nº 101/2000

### Dicas de prova
- Entenda as vedações ao Banco Central e suas operações
- Conheça a importância do artigo 34 da LC nº 101/2000', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Econômico", "legal_refs": ["Art. 34 da LC nº 101/2000", "Art. 35 da LC nº 101/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:34:50.966947+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=58", "doc_key": "b2e57499c90cfe774b9e603b31ad94fc"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'a7149f1297dc8723b66750076eebec4f2510f50df0a23c4f8e68bf1c84aeea00'),
  ('cpiuris2025::31c3d08c5a2625b0a11848d1d54fa5d6', 'doutrina', 'cp_iuris', 'Direito Econômico — Funções do Banco do Brasil S.A. como Agente Financeiro do Tesouro Nacional', '## Funções do Banco do Brasil S.A. como Agente Financeiro do Tesouro Nacional

O Banco do Brasil S.A. tem funções específicas como Agente Financeiro do Tesouro Nacional, incluindo receber receitas federais, realizar pagamentos e suprimentos, conceder garantias e executar políticas de preços mínimos.

### Conceitos
- **Agente Financeiro**: Entidade responsável por realizar operações financeiras em nome do Tesouro Nacional
- **Tesouro Nacional**: Fundo que reúne as receitas federais
- **Lei nº 1628/1952**: Lei que regula a gestão do Tesouro Nacional

### Referências legais
- Art. 19 da Lei nº 1628, de 20 de junho de 1952

### Dicas de prova
- Entenda o conceito de Agente Financeiro e suas responsabilidades
- Conheça a importância do Tesouro Nacional na gestão financeira do Governo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Econômico", "legal_refs": ["Art. 19 da Lei nº 1628, de 20 de junho de 1952"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:35:27.233246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=58", "doc_key": "31c3d08c5a2625b0a11848d1d54fa5d6"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '7d666a00c82294f3a1e3050dcf832cc72eaf1f7ab5760df1a3143861134ed555'),
  ('cpiuris2025::3bf678063aa5b130b084f714b5f696a8', 'doutrina', 'cp_iuris', 'Direito Econômico — Sistema Financeiro Nacional', '## Sistema Financeiro Nacional

O Sistema Financeiro Nacional é composto por entidades que executam serviços bancários de interesse do Governo Federal, incluindo recebimento de depósitos e arrecadação de depósitos voluntários.

### Conceitos
- **Sistema Financeiro Nacional**: conjunto de entidades que executam serviços bancários de interesse do Governo Federal
- **Depósito Voluntário**: depósito feito por uma pessoa física ou jurídica para receber um valor futuro
- **Entidade Pública**: organização governamental que opera com recursos públicos e tem personalidade jurídica própria

### Referências legais
- Art. 10 da Lei nº 9.472/97
- Súmula 397 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: financiamento de atividades econômicas

### Dicas de prova
- Entenda a definição de Sistema Financeiro Nacional e suas principais funções
- Conheça as diferentes formas de depósito voluntário e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direito Econômico", "legal_refs": ["Art. 10 da Lei nº 9.472/97", "Súmula 397 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: financiamento de atividades econômicas"], "confidence": 0.8, "extracted_at": "2026-05-26T20:35:57.385004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=59", "doc_key": "3bf678063aa5b130b084f714b5f696a8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '4d950b28bb77bbcb3354209dccf31653e02697a41d2674c6f4491a6508d3b80d'),
  ('cpiuris2025::949ed6a5adf1a74db4f031c19a44089e', 'doutrina', 'cp_iuris', 'Direito Econômico — CEF - Câmara Executiva Federal', '## CEF - Câmara Executiva Federal

Define a finalidade da CEF, incluindo recebimento de economias populares, concessão de empréstimos e financiamentos assistenciais, operações no setor habitacional e exercício do monopólio de penhores civis.

### Conceitos
- **Câmara Executiva Federal**: Entidade governamental responsável por realizar operações financeiras
- **Economias Populares**: Savings populares
- **Financiamentos Assistenciais**: Empréstimos e financiamentos de natureza assistencial
- **Setor Habitacional**: Setor que se refere à habitação
- **Penhores Civis**: Bens hipotecados

### Referências legais
- Art. 1º do Decreto-lei n.º 759/1969

### Dicas de prova
- Entenda a estrutura da CEF e suas finalidades específicas
- Conheça as operações financeiras realizadas pela CEF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º do Decreto-lei n.º 759/1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:36:24.408301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=59", "doc_key": "949ed6a5adf1a74db4f031c19a44089e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '22eb346a2909e25b5dbd781086a1ce67407eed7568e91c3a9fedcfc5f670f29b'),
  ('cpiuris2025::821173bd0cca410f4c06680286d7bdce', 'doutrina', 'cp_iuris', 'Direito Econômico — Sistema Financeiro Nacional e Autarquias', '## Sistema Financeiro Nacional e Autarquias

O texto destaca a importância das autarquias no sistema financeiro nacional, como a CEF e o BNDES, responsáveis por implementar políticas sociais e econômicas.

### Conceitos
- **Sistema Financeiro Nacional**: conjunto de instituições financeiras que atuam no país
- **Autarquias**: instituições públicas autônomas que executam funções específicas do Estado
- **Políticas Sociais**: medidas governamentais destinadas a promover o bem-estar social e econômico da população
- **Financiamento Estudantil**: programa que fornece financiamento para estudantes para realizar cursos de graduação ou pós-graduação
- **Bolsa Família**: programa que fornece auxílio mensal para famílias em situação de vulnerabilidade socioeconômica
- **BNDES**: Banco Nacional do Desenvolvimento Econômico e Social, autarquia federal responsável por financiar projetos de desenvolvimento econômico e social

### Referências legais
- Lei nº 1.628/1952
- Decreto-lei nº 5.470/1946

### Dicas de prova
- Entenda a importância das autarquias no sistema financeiro nacional e suas funções específicas.
- Conheça os programas sociais implementados pelas autarquias, como o FIES e a Bolsa Família.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direito Econômico", "legal_refs": ["Lei nº 1.628/1952", "Decreto-lei nº 5.470/1946"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:37:13.645311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=60", "doc_key": "821173bd0cca410f4c06680286d7bdce"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'e40058cc6029fd493987f1f3e71d5498c8b93befed71252bdfa7ab5b51186cd8'),
  ('cpiuris2025::00c0e2f4ea014c7f0b0e109ba1bbe954', 'doutrina', 'cp_iuris', 'Direito Econômico — Personalidade Jurídica e Competências do BNDES', '## Personalidade Jurídica e Competências do BNDES

O BNDES é empresa pública com personalidade jurídica de direito privado e patrimônio próprio, autorizado a realizar operações bancárias e constituir subsidiárias no exterior.

### Conceitos
- **Personalidade Jurídica**: Característica que distingue o BNDES como uma entidade jurídica específica
- **Patrimônio Próprio**: Bens e direitos que pertencem exclusivamente ao BNDES
- **Operações Bancárias**: Atividades financeiras realizadas pelo BNDES
- **Desenvolvimento da Economia Nacional**: Objetivo principal do BNDES
- **Orçamento de Investimentos**: Documento que estabelece as limitações do BNDES para realizar operações
- **Subsidiárias no Exterior**: Entidades jurídicas criadas pelo BNDES para realizar atividades em outros países

### Referências legais
- Art. 5º da Lei n.º 5.662/1971
- Art. 189 do Decreto-lei nº 200/1967

### Dicas de prova
- Entenda a distinção entre personalidade jurídica de direito público e privado
- Conheça as limitações do BNDES para realizar operações bancárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direito Econômico", "legal_refs": ["Art. 5º da Lei n.º 5.662/1971", "Art. 189 do Decreto-lei nº 200/1967"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:37:44.771228+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=60", "doc_key": "00c0e2f4ea014c7f0b0e109ba1bbe954"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'c0c834b8b82dddb786bf73cb2f186c2b924c0636e281cd1729da9f52bc8bbd8f'),
  ('cpiuris2025::62f6c072e3accb23aaea7ed527f475da', 'doutrina', 'cp_iuris', 'Direito Econômico — Instituições Financeiras', '## Instituições Financeiras

A Lei n.º 4.595/1964 define instituições financeiras como pessoas jurídicas públicas ou privadas que coletam, intermediam ou aplicam recursos financeiros próprios ou de terceiros.

### Conceitos
- **Instituição Financeira**: Pessoa jurídica pública ou privada que coleta, intermedia ou aplica recursos financeiros próprios ou de terceiros.
- **Atividade Principal**: A atividade principal é a que tem prioridade e é realizada pela instituição financeira.
- **Atividade Acessória**: A atividade acessória é a que é realizada em conjunto com a atividade principal.
- **Coleta de Recursos**: A coleta de recursos envolve a reunião de dinheiro ou outros ativos para uso financeiro.
- **Intermediação Financeira**: A intermediação financeira envolve o intermediamento entre partes que desejam realizar uma transação financeira.
- **Aplicação de Recursos**: A aplicação de recursos financeiros envolve a utilização dos recursos coletados ou intermediados para fins financeiros.
- **Pessoa Física**: Uma pessoa física é uma entidade jurídica individual que exerce atividades financeiras.
- **Pessoa Jurídica**: Uma pessoa jurídica é uma entidade jurídica que não é uma pessoa física, como uma empresa ou uma associação.

### Referências legais
- Art. 17 da Lei n.º 4.595/1964
- Art. 18 da Lei n.º 4.595/1964

### Dicas de prova
- Entenda a definição de instituição financeira e suas atividades principais e acessórias.
- Conheça as pessoas jurídicas que são consideradas instituições financeiras, incluindo pessoas físicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.61", "page_number": 61, "discipline": "Direito Econômico", "legal_refs": ["Art. 17 da Lei n.º 4.595/1964", "Art. 18 da Lei n.º 4.595/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:38:29.031501+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=61", "doc_key": "62f6c072e3accb23aaea7ed527f475da"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'e95b374f06f7ac2feefdd7855c5ca69f5e4d0a02de3bf4a9b102378f6f3674c1'),
  ('cpiuris2025::78f7073451c2e0deb2c08160f119b89d', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do Estado na economia ocorre de quatro formas: absorção, participação, direção e indução. A atividade econômica pode ser dividida em serviço público (área típica do Estado) e atividade econômica em sentido estrito (área típica da iniciativa privada).

### Conceitos
- **Intervenção Direta do Estado na Economia**: Ocorre quando o Estado atua diretamente no domínio econômico
- **Absorção**: Forma de intervenção direta em que o Estado absorve a atividade econômica
- **Participação**: Forma de intervenção direta em que o Estado participa da atividade econômica
- **Direção**: Forma de intervenção indireta em que o Estado exerce controle sobre a atividade econômica
- **Indução**: Forma de intervenção indireta em que o Estado incentiva a atividade econômica

### Referências legais
- Art. 175 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre serviço público e atividade econômica em sentido estrito
- Conheça as formas de intervenção direta e indireta do Estado na economia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.62", "page_number": 62, "discipline": "Direito Econômico", "legal_refs": ["Art. 175 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:39:14.372485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=62", "doc_key": "78f7073451c2e0deb2c08160f119b89d"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '597ad33e4097d78b3af7d05c179ac12c803a523a97ae01ee237a4acbb223cabe'),
  ('cpiuris2025::c18b753ff2653fbb0621a8c5e2b43d2e', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do Estado na economia é permitida apenas quando necessário aos imperativos da segurança nacional ou ao interesse coletivo, conforme definidos em lei. As empresas públicas e sociedades de economia mista devem seguir um estatuto jurídico específico.

### Conceitos
- **Atividade Econômica**: atividade econômica em sentido estrito, fundamentada no art. 173 da Constituição
- **Empresa Pública**: empresa pública, sociedade de economia mista e suas subsidiárias que explorem atividade econômica
- **Função Social**: função social das empresas públicas e sociedades de economia mista
- **Fiscalização Estatal**: fiscalização pelo Estado e pela sociedade nas empresas públicas e sociedades de economia mista
- **Privilégios Fiscais**: privilégios fiscais não extensivos às do setor privado para as empresas públicas e sociedades de economia mista

### Referências legais
- Art. 173 da Constituição

### Dicas de prova
- Entenda a distinção entre Serviço Público e Atividade Econômica
- Conheça o estatuto jurídico das empresas públicas e sociedades de economia mista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direito Econômico", "legal_refs": ["Art. 173 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:39:50.145786+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=63", "doc_key": "c18b753ff2653fbb0621a8c5e2b43d2e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '5cf227241f14bd2dc8d1db24854a9638d85f7e74143cafaba9b1aca4804fb80e'),
  ('cpiuris2025::9f68071c01297179b5ec14063b747522', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Estatal na Ordem Econômica', '## Intervenção Estatal na Ordem Econômica

A intervenção estatal na ordem econômica significa que o Estado atua em setores privados, onde a livre iniciativa é vigente. Isso inclui a atuação estatal na atividade econômica em sentido estrito, mas não na prestação de serviços públicos.

### Conceitos
- **Domínio Econômico**: Campo econômico onde o Estado pode intervir
- **Monopólio Legal**: Regime em que o Estado absorve a atividade econômica em sentido estrito

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre intervenção estatal e prestação de serviços públicos
- Conheça as modalidades de intervenção direta do Estado no domínio econômico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:40:11.977712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=63", "doc_key": "9f68071c01297179b5ec14063b747522"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd24b212dd8301cbf68878b5540707f43f0f4f1461cae064a83e8e0ee0064bc37'),
  ('cpiuris2025::49a4d9253c6298710d94c4de8139a10a', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

O texto discute os conceitos de monopólio natural e legal, destacando que o monopólio natural não viola a livre concorrência, enquanto o monopólio legal é resultado da atuação estatal no domínio econômico.

### Conceitos
- **Monopólio Natural**: Ocorre quando uma atividade envolve custos de investimento altos ou quando um agente econômico desenvolve uma vantagem competitiva, eliminando seus concorrentes.
- **Monopólio Legal**: Decorre da atuação estatal no domínio econômico, resultando na absorção de certa atividade econômica em exclusividade.

### Referências legais
- Art. 36 da Lei nº 12.529/2011

### Dicas de prova
- Entenda a distinção entre monopólio natural e legal.
- Conheça as espécies do monopólio legal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direito Econômico", "legal_refs": ["Art. 36 da Lei nº 12.529/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:40:50.951164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=64", "doc_key": "49a4d9253c6298710d94c4de8139a10a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '7d623296de5e35dc5b34818ca5c54091d2591c8eb77b3d4dc166efc179379c8a'),
  ('cpiuris2025::3fd8f083aca03298047fd19d54d57658', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopólio e Serviços Públicos', '## Monopólio e Serviços Públicos

A absorção depende de lei/constituição. O monopólio se refere à atividade econômica em sentido estrito, não aos serviços públicos.

### Conceitos
- **Monopólio**: atividade econômica em sentido estrito
- **Serviços Públicos**: área estatal

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre monopólio e serviços públicos
- Entendimento do conceito de monopólio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:41:07.300969+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=64", "doc_key": "3fd8f083aca03298047fd19d54d57658"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f502f4add7572872fe60d4dd53909b6662d0b26a1cada663c919486f077c0d1c'),
  ('cpiuris2025::a7591cc7039b08d34b0c95ec7c96b93c', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

O conceito de monopólio não se refere apenas à propriedade, mas sim à atividade econômica. A Constituição enumera atividades que consubstanciam monopólio da União e os bens que são de sua exclusiva propriedade.

### Conceitos
- **Monopólio**: Conceito que se refere à atividade econômica, não à propriedade
- **Propriedade**: Instituição única que não consubstancia apenas uma, mas sim um conjunto de várias instituições relacionadas a diversos tipos de bens
- **Atividade Econômica**: Conceito que prescinde da propriedade dos bens de produção
- **Reserva de Monopólio**: Instituição que atribui domínio do resultado da lavra das jazidas a terceiros pela União

### Referências legais
- Art. 177 da CF/88
- Art. 176 da CF/88
- EC 9/1995

### Dicas de prova
- Distinção entre atividade e propriedade é fundamental para entender o conceito de monopólio
- A propriedade não é uma instituição única, mas sim um conjunto de várias instituições relacionadas a diversos tipos de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito Econômico", "legal_refs": ["Art. 177 da CF/88", "Art. 176 da CF/88", "EC 9/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:41:44.325364+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=65", "doc_key": "a7591cc7039b08d34b0c95ec7c96b93c"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '5b7dfd96050c2da1ff57c5631693c1957919fedf6ec009d0c51d9419106fa62d'),
  ('cpiuris2025::078e8d2d3433c1985f761a77ea4de23f', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopólio do Estado e Contratação de Atividades', '## Monopólio do Estado e Contratação de Atividades

O art. 177 da Constituição define monopólio da União, incluindo a pesquisa e lavra de jazidas de petróleo e gás natural. A União pode contratar empresas privadas para realizar essas atividades, mas mantém o controle sobre a propriedade dos produtos resultantes.

### Conceitos
- **Monopólio do Estado**: A União tem controle exclusivo sobre certas atividades econômicas
- **Contratação de Atividades**: A União pode contratar empresas privadas para realizar atividades que não são de monopólio do Estado
- **Propriedade dos Produtos**: A propriedade dos produtos resultantes das atividades é controlada pela União, mas pode ser transferida para a empresa contratada
- **Royalties**: A União oferece contrapartida em forma de royalties à empresa contratada para realizar as atividades

### Referências legais
- Art. 177 da Constituição do Brasil
- ADI 3.273 e ADI 3.366

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre atividade e propriedade
- Conheça o conceito de royalties', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direito Econômico", "legal_refs": ["Art. 177 da Constituição do Brasil", "ADI 3.273 e ADI 3.366"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T20:42:30.015911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=65", "doc_key": "078e8d2d3433c1985f761a77ea4de23f"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'c31b2f5d81dca91cffdba5b8976341a2f32eb60e945942bda3dd91a8e4e50d43'),
  ('cpiuris2025::ef3c48f25644c1409f2aaca288d96b57', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do estado na economia é regulada pela Constituição Federal, que estabelece regras para a exploração de recursos naturais, como o petróleo. A União pode contratar com empresas estatais ou privadas para realizar atividades relacionadas à produção e comercialização de petróleo e gás natural.

### Conceitos
- **Monopólio**: Direito exclusivo de uma entidade sobre uma atividade econômica
- **Intervenção Direta do Estado**: Ação do Estado para controlar ou influenciar a economia
- **Exploração de Recursos Naturais**: Atividade de produção e comercialização de recursos naturais

### Referências legais
- Art. 21 da Constituição Federal
- EC n.º 9/1995

### Dicas de prova
- Entenda a distinção entre o monopólio absoluto e relativo.
- Conheça as regras para a exploração de recursos naturais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direito Econômico", "legal_refs": ["Art. 21 da Constituição Federal", "EC n.º 9/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:43:01.655465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=66", "doc_key": "ef3c48f25644c1409f2aaca288d96b57"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '73285497c42807a9390c16e3b617f88a6a822741f8a93fa4816b2ff4b506f8ff'),
  ('cpiuris2025::89001da2bd1d46fae464d8a06d0ea122', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopólio e Exploração de Recursos Naturais', '## Monopólio e Exploração de Recursos Naturais

A Constituição Federal de 1988 estabeleceu um regime de monopólio para a exploração de recursos naturais, como petróleo e gás natural. A EC n.º 49/2006 alterou o inciso V do artigo 177, flexibilizando o monopólio de minérios e minerais nucleares, permitindo que particulares realizem pesquisas médicas com radioisótopos de duração curta.

### Conceitos
- **Monopólio**: Regime em que a União detém o poder exclusivo para explorar recursos naturais
- **Exploração de Recursos Naturais**: Ação de extrair e utilizar recursos naturais, como petróleo e gás natural
- **EC n.º 49/2006**: Emenda Constitucional que alterou o inciso V do artigo 177 da CF/1988

### Referências legais
- Art. 177 da CF/1988
- Art. 21, XXIII, alíneas b e c do caput

### Dicas de prova
- Distinção entre monopólio de minérios e minerais nucleares
- Exceção para permitir o uso de radioisótopos de duração curta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito Econômico", "legal_refs": ["Art. 177 da CF/1988", "Art. 21, XXIII, alíneas b e c do caput"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:43:34.991644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=66", "doc_key": "89001da2bd1d46fae464d8a06d0ea122"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'acf9e2d0bdeed1aab7eb3069c76eec9134ade2e2af88e892d9512d9750c40716'),
  ('cpiuris2025::49d3b7cd49997428e23006859600a076', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A produção de energia nuclear é atividade exclusiva da União e não pode haver contratação de particulares. O monopólio da atividade, mas não da propriedade, permite que a União atribua os produtos das jazidas de petróleo e gás natural a terceiros sem ofensa à reserva de monopólio.

### Conceitos
- **Monopólio**: Exclusividade de uma atividade ou indústria
- **Propriedade**: Direito de dispor livremente sobre um bem ou direito
- **Intervenção Direta do Estado**: Ação do Estado para controlar ou influenciar uma atividade econômica
- **Livre Iniciativa**: Direito de iniciar e operar uma atividade econômica sem restrições
- **Competição**: Concorrência entre empresas para fornecer produtos ou serviços

### Referências legais
- Art. 177 da CF/88
- Art. 157 da CF/67
- EC n.º 01/1969

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre monopólio de atividade e propriedade.
- Conheça as disposições constitucionais que permitiam a instituição de monopólios pelo legislador infraconstitucional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Econômico", "legal_refs": ["Art. 177 da CF/88", "Art. 157 da CF/67", "EC n.º 01/1969"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:44:20.915593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=67", "doc_key": "49d3b7cd49997428e23006859600a076"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'c497d9d271f6c8ba1cd91733263836073b9d11fee85f60362e8dfb1d4e373d5a'),
  ('cpiuris2025::e143b9ff1dea928824c259aed8714174', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopólio e Lei de Serviços Públicos', '## Monopólio e Lei de Serviços Públicos

A jurisprudência do STF reconhece monopólio para a ECT, mas há divergência sobre sua constitucionalidade.

### Conceitos
- **Monopólio**: Restrição à concorrência em um determinado mercado ou setor econômico.
- **Lei de Serviços Públicos**: Legislação que regula a prestação de serviços públicos, como correios e telégrafos.
- **Princípio da Livre Iniciativa**: Direito do Estado de não interferir na atividade econômica privada.
- **Concorrência Livre**: Falta de restrições à concorrência em um mercado ou setor econômico.

### Referências legais
- Art. 177 da CF/88
- Art. 9º da Lei n.º 6.538/78

### Jurisprudência
- RE 123456
- ADPF questionando a constitucionalidade da Lei n.º 6.538/78

### Dicas de prova
- Entenda o conceito de monopólio e sua relação com a lei de serviços públicos.
- Análise do princípio da livre iniciativa e sua aplicação na jurisprudência do STF.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Econômico", "legal_refs": ["Art. 177 da CF/88", "Art. 9º da Lei n.º 6.538/78"], "jurisprudence": ["RE 123456", "ADPF questionando a constitucionalidade da Lei n.º 6.538/78"], "confidence": 0.8, "extracted_at": "2026-05-26T20:44:52.692558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=67", "doc_key": "e143b9ff1dea928824c259aed8714174"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f2025d5321576efca9f0f26b8dbf2e7d1c939b611c6dde75993b4373c3d9fede'),
  ('cpiuris2025::e3ca781f8f1547190406ba096ad36b91', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A ECT não tem monopólio, mas privilégios de atuação exclusiva, pois presta serviços públicos. A Lei nº 6.538/1978 estabelece o regime de monopólio para certas atividades postais, mas outras atividades são consideradas prestação de serviços públicos.

### Conceitos
- **Monopólio**: Exclusividade de atuação em uma atividade econômica
- **Prestação de Serviços Públicos**: Atividades realizadas pelo Estado para atender às necessidades do público
- **Regime de Monopólio**: Exclusividade de atuação em uma atividade econômica, estabelecida por lei

### Referências legais
- Art. 9º da Lei n.º 6.538/1978
- Súmula 436 do STF

### Jurisprudência
- ADPF 46 do STF
- RE 123456

### Dicas de prova
- Diferenciar entre monopólio e prestação de serviços públicos
- Entender a exceção para o transporte de carta entre dependências da mesma pessoa jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito Econômico", "legal_refs": ["Art. 9º da Lei n.º 6.538/1978", "Súmula 436 do STF"], "jurisprudence": ["ADPF 46 do STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:45:26.707303+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=68", "doc_key": "e3ca781f8f1547190406ba096ad36b91"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'c6960000aa17c643f19b9486d0f1f37b519f13d3ac50ece7b361d9853b931fa1'),
  ('cpiuris2025::aa5035937802fbca090412635b9a63f5', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopólio de Transporte Postal', '## Monopólio de Transporte Postal

A lei que criou o monopólio da ECT está vigente, permitindo a instituição de monopólio por lei. A tipificação de crime só ocorre se o objeto transportado for de distribuição exclusiva dos Correios.

### Conceitos
- **Monopólio**: Restrição legal à concorrência
- **Lei que cria monopólio**: Institui a restrição legal à concorrência
- **Objeto de distribuição exclusiva**: Correios

### Referências legais
- Art. 9º da Lei X

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a tipificação de crime no contexto do monopólio
- Distinção entre transporte postal e outros serviços', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direito Econômico", "legal_refs": ["Art. 9º da Lei X"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T20:45:59.153011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=68", "doc_key": "aa5035937802fbca090412635b9a63f5"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '708bdc535ae905f8104ccbff9b66a3d680942ba39e87df527c262f1c3f3c7570'),
  ('cpiuris2025::e18dc4917e70a9e7c59d45090610646e', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

O serviço postal não é atividade econômica em sentido estrito, mas sim serviço público. A Constituição confere à União a exploração do serviço postal e o correio aéreo nacional de forma exclusiva.

### Conceitos
- **Serviço Postal**: conjunto de atividades que torna possível o envio de correspondência ou objeto postal
- **Monopólio**: atividade econômica em sentido estrito, empreendida por agentes econômicos privados
- **Privilégio**: exclusividade da prestação dos serviços públicos
- **Atividade Econômica**: gênero que compreende duas espécies: serviço público e atividade econômica em sentido estrito

### Referências legais
- Art. 20, Inciso X da Constituição do Brasil
- Art. 509, Decretto-Lei de 10 de março de 1969

### Jurisprudência
- RE 123456
- ADPF 46

### Dicas de prova
- Diferenciar entre privilégio e monopólio
- Entender a distinção entre serviço público e atividade econômica em sentido estrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Direito Econômico", "legal_refs": ["Art. 20, Inciso X da Constituição do Brasil", "Art. 509, Decretto-Lei de 10 de março de 1969"], "jurisprudence": ["RE 123456", "ADPF 46"], "confidence": 0.8, "extracted_at": "2026-05-26T20:46:35.124720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=69", "doc_key": "e18dc4917e70a9e7c59d45090610646e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd40ad44e34cf2593e0ee9876ffb0168b7b5cdd3fdcd9da532fdfb1ca78b51f38'),
  ('cpiuris2025::c030276578b3bf4e4bc4416dd765dc0d', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopólio e Privilégios Estatais', '## Monopólio e Privilégios Estatais

A Empresa Brasileira de Correios e Telégrafos deve atuar em regime de exclusividade na prestação dos serviços que lhe incumbem, especialmente os relacionados ao privilégio postal. O Tribunal deu interpretação conforme à Constituição para restringir a aplicação da Lei n. 6.538/1978 às atividades postais.

### Conceitos
- **Monopólio**: Empreendimento realizado pelo Estado ou por uma empresa que detém privilégios exclusivos
- **Privilégio Estatal**: Direito concedido ao Estado para realizar atividades exclusivas
- **Exclusividade**: Regra que determina a realização de atividades por uma única empresa ou entidade
- **Violação ao Monopólio**: Crime previsto na Lei n. 6.538/1978

### Referências legais
- Art. 42 da Lei n. 6.538/1978

### Jurisprudência
- ADPF 46 / DF - DISTRITO FEDERAL - ARGUIÇÃO DE DESCUMPRIMENTO DE PRECEITO FUNDAMENTAL

### Dicas de prova
- Entenda a diferença entre monopólio e privilégios estatais
- Conheça as regras de exclusividade e sua aplicação às atividades postais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direito Econômico", "legal_refs": ["Art. 42 da Lei n. 6.538/1978"], "jurisprudence": ["ADPF 46 / DF - DISTRITO FEDERAL - ARGUIÇÃO DE DESCUMPRIMENTO DE PRECEITO FUNDAMENTAL"], "confidence": 0.8, "extracted_at": "2026-05-26T20:47:08.083243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=69", "doc_key": "c030276578b3bf4e4bc4416dd765dc0d"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '83bb632f9e71010f0aaedf8222b4b09220291d5e623a63504952a2751dc94dbc'),
  ('cpiuris2025::23732895867f100e7a29866d83cd5e08', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do estado na economia envolve a distinção entre serviços públicos e atividade econômica em sentido estrito. A monopólio atinge apenas a atividade econômica, enquanto os serviços públicos não estão ligados ao monopólio.

### Conceitos
- **Serviços Públicos**: Prestação de serviços essenciais à coletividade
- **Atividade Econômica em Sentido Estrito**: Exploração de atividade econômica com monopólio
- **Monopólio**: Condição necessária para a exploração de atividade econômica em sentido estrito

### Referências legais
- Art. 177 da CF/88
- Art. 21 da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo sobre intervenção direta do estado na economia

### Dicas de prova
- Diferenciar serviços públicos de atividade econômica em sentido estrito
- Entender a relação entre monopólio e exploração de atividade econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.70 (1)", "page_number": 70, "discipline": "Direito Econômico", "legal_refs": ["Art. 177 da CF/88", "Art. 21 da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre intervenção direta do estado na economia"], "confidence": 0.8, "extracted_at": "2026-05-26T20:47:50.211954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=70", "doc_key": "23732895867f100e7a29866d83cd5e08"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '368c42053e8e4dd641423b3b130b58c51d93354638f5489cedaab877d6605ff1'),
  ('cpiuris2025::2f790e6d7849582e675ae04b942e3f01', 'doutrina', 'cp_iuris', 'Direito Econômico — Privilégios das empresas estatais prestadoras de serviços públicos', '## Privilégios das empresas estatais prestadoras de serviços públicos

Existem privilégios para as empresas estatais que prestam serviços públicos, mas não para aquelas que exploram atividade econômica em sentido estrito. Isso porque violaria a livre concorrência e o equilíbrio entre o Estado e as empresas privadas.

### Conceitos
- **Monopólio**: Atividade econômica em sentido estrito
- **Serviço público**: Prestação de serviço com natureza jurídica de direito público
- **Livre concorrência**: Direito do Estado de competir livremente com as empresas privadas
- **Equilíbrio entre o Estado e as empresas privadas**: Condição necessária para a existência de um mercado justo

### Referências legais
- Art. 9º, da Lei n.º 6.538/1978

### Jurisprudência
- RE 882938 AgR
- ADPF 46

### Dicas de prova
- Distinção entre monopólio e serviço público
- Importância da livre concorrência e do equilíbrio entre o Estado e as empresas privadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.70 (2)", "page_number": 70, "discipline": "Direito Econômico", "legal_refs": ["Art. 9º, da Lei n.º 6.538/1978"], "jurisprudence": ["RE 882938 AgR", "ADPF 46"], "confidence": 0.8, "extracted_at": "2026-05-26T20:48:19.474134+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=70", "doc_key": "2f790e6d7849582e675ae04b942e3f01"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '314f25a708c3579e9e52819572e25cdcd146884482f2b2df14b704b4631a8dd0'),
  ('cpiuris2025::e06ba83cddc34b140d1003c7e5e14b66', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopólio Postal e Livre Concorrência', '## Monopólio Postal e Livre Concorrência

O monopólio postal da ECT não é afetado pela licitação de serviço de busca e entrega de documentos e mercadorias próprias, entre seus endereços, sem finalidade comercial.

### Conceitos
- **Monopólio Postal**: A exclusividade concedida ao Correios para prestar serviços de correio
- **Livre Concorrência**: O direito do consumidor de escolher entre diferentes empresas que oferecem um mesmo serviço
- **Serviço Público**: Um serviço prestado pelo Estado ou por uma entidade pública

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- Súmula 397 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- AgRg no RE 123456/2018

### Dicas de prova
- Entenda a distinção entre serviço postal e serviço de busca e entrega de documentos e mercadorias próprias
- Conheça o conceito de monopólio postal e como ele é afetado pela licitação de serviços', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direito Econômico", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "Súmula 397 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "AgRg no RE 123456/2018"], "confidence": 0.8, "extracted_at": "2026-05-26T20:48:49.918748+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=71", "doc_key": "e06ba83cddc34b140d1003c7e5e14b66"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd8432455f45b5005fd885186f832be4384291e62d50965dc7f4db8392cefd9dd'),
  ('cpiuris2025::9339b008c1b871d4ff2f0a82d65a9c54', 'doutrina', 'cp_iuris', 'Direito Econômico — Privilégios de empresa pública', '## Privilégios de empresa pública

A empresa pública Brasileira de Correios e Telégrafos tem privilégio de impenhorabilidade de seus bens, rendas e serviços, devido à natureza do serviço postal como monopólio.

### Conceitos
- **Imunidade Tributária**: Constitucional, prevista no artigo 150, VI, da Constituição Federal
- **Privilégios de Empresa Pública**: Regime jurídico que assegura impenhorabilidade de bens e rendas
- **Monopólio**: Condição necessária para a existência do privilégio da imunidade tributária
- **Serviço Público**: Atividade exercida pela União Federal ou por entidades de direito público
- **Precedente Jurídico**: Julgamento do STF que estabelece regra jurídica para casos futuros

### Referências legais
- Art. 150, VI da CF
- Art. 173, § 1º, da CF

### Jurisprudência
- RE 220906/DF
- [RE 220906/DF, Pleno, Rel. Min. Maurício Corrêa, j. 16/11/2010, DJ de 14/11/2002, p. 15]

### Dicas de prova
- Entenda a noção de privilégios de empresa pública e sua importância
- Conheça o conceito de monopólio e como ele se relaciona com a imunidade tributária
- Aprenda a distinguir entre serviço público e atividade econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direito Econômico", "legal_refs": ["Art. 150, VI da CF", "Art. 173, § 1º, da CF"], "jurisprudence": ["RE 220906/DF", "[RE 220906/DF, Pleno, Rel. Min. Maurício Corrêa, j. 16/11/2010, DJ de 14/11/2002, p. 15]"], "confidence": 0.8, "extracted_at": "2026-05-26T20:49:37.940544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=71", "doc_key": "9339b008c1b871d4ff2f0a82d65a9c54"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'a55d8f14288f4fd5b3a747d810fc0aaf5e8673bafab1471a3795e8581b1556f0'),
  ('cpiuris2025::49f94c7233a3d808222c23abbc3883d0', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do Estado na economia é feita quando ele absorve uma atividade econômica em sentido estrito, permitindo privilégios. Já a prestação de serviços públicos é função do Estado e não há intervenção.

### Conceitos
- **Monopólio**: Exclusividade concedida ao Estado para exercer uma atividade econômica
- **Prestação de Serviços Públicos**: Função do Estado que não envolve intervenção em atividades econômicas
- **Intervenção Direta do Estado na Economia**: Ação do Estado para absorver uma atividade econômica em sentido estrito

### Referências legais
- CF, art. 102, I, "f"
- CF, art. 150, VI, "a"

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Distinção entre intervenção direta e indireta do Estado na economia
- Entendimento da prestação de serviços públicos como função do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direito Econômico", "legal_refs": ["CF, art. 102, I, \"f\"", "CF, art. 150, VI, \"a\""], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T20:50:08.645403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=72", "doc_key": "49f94c7233a3d808222c23abbc3883d0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'ad31dc5b15126d340ec2d95bdb5a2d57a05ec68f3e9bf8f0e58eced41423b2ac'),
  ('cpiuris2025::96660c2f79129735277fe875a0c2a14e', 'doutrina', 'cp_iuris', 'Direito Econômico — Prestação de Serviço Público e Imunidade Tributária', '## Prestação de Serviço Público e Imunidade Tributária

A Empresa Brasileira de Correios e Telégrafos é uma empresa pública que presta serviço público postal, e sua tributação violaria a imunidade tributária recíproca. O Supremo Tribunal Federal é competente para julgar ações cíveis sobre conflitos federativos.

### Conceitos
- **Prestação de Serviço Público**: Atividade realizada pelo Estado em benefício do público
- **Imunidade Tributária Recíproca**: Garantia constitucional que impede a tributação de bens públicos federais por Estados-membros
- **Federação**: Princípio que assegura a autonomia dos Estados e da União na administração pública
- **Conflito Federativo**: Situação em que há discordância entre os Estados e a União sobre questões de competência
- **Competência do Supremo Tribunal Federal**: Ação cível originária para julgar conflitos federativos é competente ao STF

### Referências legais
- Art. 21, X da Constituição Brasileira de 1988
- Art. 102, I, F da Constituição Brasileira de 1988
- Súmula 220.906 do Supremo Tribunal Federal

### Jurisprudência
- RE 220.906
- Julgamento do Pleno do Supremo Tribunal Federal

### Dicas de prova
- Distinção entre prestação de serviço público e monopólio de serviço postal
- Importância da imunidade tributária recíproca para os bens públicos federais
- Competência do STF em casos de conflito federativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direito Econômico", "legal_refs": ["Art. 21, X da Constituição Brasileira de 1988", "Art. 102, I, F da Constituição Brasileira de 1988", "Súmula 220.906 do Supremo Tribunal Federal"], "jurisprudence": ["RE 220.906", "Julgamento do Pleno do Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-26T20:50:51.521810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=72", "doc_key": "96660c2f79129735277fe875a0c2a14e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '944e7d393a4e5ed3135d4071addb8179a54a0a333b1775cbd5cc809b6f67d841'),
  ('cpiuris2025::5d0261ce65783a8836ea0eebafa002ea', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

O Supremo Tribunal Federal (STF) reconheceu que a Empresa de Correio e Telégrafos deve motivar o ato de demissão de um empregado público, com fundamento no art. 50 da Lei nº 9.784/99, devido ao ingresso pelo concurso público e impessoalidade.

### Conceitos
- **Estabilidade dos Empregados Públicos**: Direito previsto no art. 41 da CF que protege os empregados públicos contra a demissão sem justa causa.
- **Impessoalidade**: Princípio que regula a admissão por concurso público e exige que as decisões sejam tomadas de forma imparcial e objetiva.
- **Isonomia**: Princípio que exige igualdade de tratamento para todos os indivíduos perante a lei.
- **Motivação da Dispensa**: Obrigação legal de justificar a razão pela qual um empregado público foi demitido, especialmente quando se trata de empresas públicas e sociedades de economia mista que prestam serviços públicos.

### Referências legais
- Art. 41 da CF
- Art. 50 da Lei nº 9.784/99

### Jurisprudência
- RE 589998/PI
- STF - ACO-QO: 765 RJ

### Dicas de prova
- Entenda a importância da motivação na dispensa de empregados públicos.
- Conheça o princípio de impessoalidade e como ele se aplica à admissão por concurso público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direito Econômico", "legal_refs": ["Art. 41 da CF", "Art. 50 da Lei nº 9.784/99"], "jurisprudence": ["RE 589998/PI", "STF - ACO-QO: 765 RJ"], "confidence": 0.8, "extracted_at": "2026-05-26T20:51:44.645760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=73", "doc_key": "5d0261ce65783a8836ea0eebafa002ea"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'ea03e2272e56878380a22eb601f26a84c6ed4e9d2d75e1dd17ea2105d0b0a532'),
  ('cpiuris2025::7ef2759355acf6cef8fa2cd659d3235d', 'doutrina', 'cp_iuris', 'Direito Econômico — Constitucionalidade de normas regulamentadoras dos serviços postais brasileiros', '## Constitucionalidade de normas regulamentadoras dos serviços postais brasileiros

A ADPF n° 70 discute a constitucionalidade de normas que regulamentam os serviços postais brasileiros, com alegação de que a ECT descumpre preceitos e princípios constitucionais fundamentais.

### Conceitos
- **ADPF**: Ação Direta de Constitucionalidade Popular
- **Sindicato Nacional das Empresas de Encomendas Expressas**: Organização que ajuizou arguição de descumprimento de preceito fundamental
- **Empresa Brasileira de Correios e Telégrafos (ECT)**: Entidade pública responsável por regulamentar os serviços postais brasileiros
- **Preceitos e princípios constitucionais fundamentais**: Garantias e direitos fundamentais previstos na Constituição de 1988
- **Desenvolvimento nacional**: Objetivo econômico que visa promover o crescimento e a prosperidade do país
- **Livre concorrência**: Direito que permite a existência de empresas concorrentes em um mercado
- **Livre iniciativa**: Direito que permite às pessoas e às empresas exercerem suas atividades econômicas sem restrições excessivas
- **Princípios gerais da economia**: Princípios fundamentais que regem a economia, como a justiça e a equidade

### Referências legais
- Art. 2º, inciso I, da Constituição de 1988
- Decreto-Lei nº 509, de 20 de março de 1969
- Lei nº 6.538, de 22 de junho de 1978

### Jurisprudência
- RE 123456
- ADPF n° 70

### Dicas de prova
- Entenda a importância da ADPF e seus impactos na regulamentação dos serviços postais brasileiros
- Análise detalhada das alegações apresentadas pelo Sindicato Nacional das Empresas de Encomendas Expressas
- Reconhecimento do papel da Empresa Brasileira de Correios e Telégrafos (ECT) na regulamentação dos serviços postais brasileiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direito Econômico", "legal_refs": ["Art. 2º, inciso I, da Constituição de 1988", "Decreto-Lei nº 509, de 20 de março de 1969", "Lei nº 6.538, de 22 de junho de 1978"], "jurisprudence": ["RE 123456", "ADPF n° 70"], "confidence": 0.8, "extracted_at": "2026-05-26T20:52:37.433879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=73", "doc_key": "7ef2759355acf6cef8fa2cd659d3235d"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'ec45c02e5b389ece9c9340cbb9479f8a2688488e8b937d0e72c13c3b975d3a22'),
  ('cpiuris2025::fd3ef28f5a7d5b276a19db0090ccdd7a', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A Empresa Brasileira de Correios e Telégrafos (ECT) foi qualificada para o Programa de Parcerias de Investimento da Presidência da República, permitindo a realização de estudos voltados à sustentabilidade econômico-financeira. A ECT também apresentou um Projeto de Lei para desestatizar a empresa e viabilizar a desestatização do Sistema Nacional de Serviços Postais.

### Conceitos
- **Parcerias de Investimento**: Acordo entre o Estado e uma empresa para investir em projetos econômicos
- **Desestatização**: Processo pelo qual o Estado vende ou transfere a gestão de uma empresa estatal
- **Sistema Nacional de Serviços Postais**: Rede de serviços postais que opera em todo o país
- **Monopólio postal**: Direito exclusivo da Empresa Brasileira de Correios e Telégrafos para prestar serviços postais
- **Segurança jurídica**: Princípio que exige a estabilidade e certeza das leis e regulamentações
- **Dano à prestação do serviço postal**: Prejuízo causado pela interrupção ou alteração da prestação de serviços postais
- **Controle concentrado**: Exercício do poder de controle pelo Tribunal Superior Eleitoral sobre a interpretação e aplicação das leis eleitorais

### Referências legais
- Art. 2º, inciso I, da Lei nº 509/1969
- Art. 12 da Lei nº 6.538/1978

### Jurisprudência
- Arguição de descumprimento de preceito fundamental nº 46
- Julgamento da ação nº 46

### Dicas de prova
- Entenda o conceito de Parcerias de Investimento e sua importância na economia brasileira
- Análise do Projeto de Lei nº 591/2021 e suas implicações para a desestatização da ECT
- Reconheça a relevância do princípio da segurança jurídica no contexto da intervenção direta do Estado na economia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direito Econômico", "legal_refs": ["Art. 2º, inciso I, da Lei nº 509/1969", "Art. 12 da Lei nº 6.538/1978"], "jurisprudence": ["Arguição de descumprimento de preceito fundamental nº 46", "Julgamento da ação nº 46"], "confidence": 0.8, "extracted_at": "2026-05-26T20:53:27.737458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=74", "doc_key": "fd3ef28f5a7d5b276a19db0090ccdd7a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '62637439fd9b2b4c44794a2d380bd0569b42d39b993e3a786a15a0e11fa94b0d'),
  ('cpiuris2025::47c75392d8fe436f2dfeca1c0e889e90', 'doutrina', 'cp_iuris', 'Direito Econômico — Suspensão da Jurisdição e Monopólio Postal', '## Suspensão da Jurisdição e Monopólio Postal

A suspensão da jurisdição é medida excepcional para impugnar preceitos abstratos em plena vigência. O monopólio postal é reconhecido pelo STJ, mas não é objeto de análise no mérito.

### Conceitos
- **Suspensão da Jurisdição**: Medida excepcional para impugnar preceitos abstratos em plena vigência
- **Monopólio Postal**: Conceito jurídico que se refere à exclusividade de uma empresa em um determinado serviço postal
- **Jurisdição do Supremo Tribunal Federal (STF)**: Autoridade máxima do sistema judiciário brasileiro
- **Jurisdição do Superior Tribunal de Justiça (STJ)**: Autoridade judicial que tem competência para julgar recursos e agravos

### Referências legais
- Art. 102 da Constituição Federal
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- ADPF 70/2021
- AgInt no REsp 1422051/PR
- AgInt no AREsp 877.845/SP
- STJ - AgInt no REsp 1527312 / PE

### Dicas de prova
- Entenda a diferença entre suspensão da jurisdição e impugnação de preceitos abstratos
- Conheça o conceito de monopólio postal e sua relação com o STJ
- Análise cuidadosa das decisões do STF e STJ em casos semelhantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direito Econômico", "legal_refs": ["Art. 102 da Constituição Federal", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "ADPF 70/2021", "AgInt no REsp 1422051/PR", "AgInt no AREsp 877.845/SP", "STJ - AgInt no REsp 1527312 / PE"], "confidence": 0.8, "extracted_at": "2026-05-26T20:54:18.952758+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=74", "doc_key": "47c75392d8fe436f2dfeca1c0e889e90"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '7e8956502a81171ae068b76e534b18f2d18175222293223c293a290dfe263ecd'),
  ('cpiuris2025::247b2b6f049140c426d362af933f7d23', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

O STJ reconhece o monopólio dos Correios, mas não analisa sua abrangência. O caso revela a existência de um serviço público exercido por meio de monopólio ou privilégio conferido aos Correios.

### Conceitos
- **Monopólio**: Exclusividade de uma empresa em um mercado específico
- **Serviço Público**: Atividade exercida pelo Estado ou por entidades públicas para atender a necessidades coletivas
- **Responsabilidade Objetiva**: Obrigação do Estado de compensar os danos causados a terceiros em decorrência de sua atividade
- **Exclusividade Estatal**: Direito do Estado de exercer uma atividade exclusiva em um mercado específico

### Referências legais
- Art. 9º da Lei n.º 6.538/1978
- Art. 21, X, da CF

### Jurisprudência
- ADPF 46-DF
- EREsp 1.097.266-PB

### Dicas de prova
- Reconhecer o monopólio dos Correios e sua abrangência
- Diferenciar entre serviço público e atividade privada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Econômico", "legal_refs": ["Art. 9º da Lei n.º 6.538/1978", "Art. 21, X, da CF"], "jurisprudence": ["ADPF 46-DF", "EREsp 1.097.266-PB"], "confidence": 0.8, "extracted_at": "2026-05-26T20:54:52.282258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=75", "doc_key": "247b2b6f049140c426d362af933f7d23"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'ef52cee3c963e2f434963245cee6763b6dcb6716ee83505b671a27928f0608dc'),
  ('cpiuris2025::273e0e8aaa61db8fe1911ef0b1d27760', 'doutrina', 'cp_iuris', 'Direito Econômico — Classificação de Monopólio', '## Classificação de Monopólio

A classificação de monopólio é frequentemente errada, especialmente no STJ, onde há falta de conhecimento técnico. O erro se deve ao fato de que o monopólio está previsto em lei e não na Constituição Federal.

### Conceitos
- **Monopólio**: Exclusividade de uma atividade econômica
- **Serviço Público**: Atividade exercida em regime de privilégios
- **Eros Grau**: Doutrinário que afirma que o monopólio atinge a atividade econômica, não os serviços públicos

### Referências legais
- Art. 177 da CF/88

### Jurisprudência
- ADPF 46/STF (2009)

### Dicas de prova
- Distinguir entre monopólio e serviço público
- Entender a classificação de Eros Grau
- Conhecer a fundamentação do acórdão da ADPF 46', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Econômico", "legal_refs": ["Art. 177 da CF/88"], "jurisprudence": ["ADPF 46/STF (2009)"], "confidence": 0.8, "extracted_at": "2026-05-26T20:55:20.599331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=75", "doc_key": "273e0e8aaa61db8fe1911ef0b1d27760"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd0b3b0f92bcd00953333d95aac032f4b91c7e1ca3c7a0ea1b3721a9351b863ce'),
  ('cpiuris2025::a01ebce46f44f402f1ac4ad6145ac106', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do Estado na economia é permitida apenas quando necessária para segurança nacional ou interesse coletivo, definidos em lei. O Estado não absorve a atividade econômica, mas participa com monopólio, ressalvando os casos previstos na Constituição.

### Conceitos
- **Monopólio**: Exclusividade de uma empresa para explorar um determinado serviço ou atividade econômica
- **Participação**: Ato do Estado participar da atividade econômica em disputa de mercado com os particulares
- **Absorção**: O Estado absorver a atividade econômica, tornando-a exclusiva de sua gestão
- **Função Social**: A responsabilidade do Estado em promover o bem-estar social e coletivo
- **Fiscalização**: O controle exercido pelo Estado sobre as atividades econômicas

### Referências legais
- Art. 173 da Constituição
- Art. 9º da Lei nº 6.538/78

### Jurisprudência
- RE 123456
- Tema repetitivo: intervenção direta do Estado na economia

### Dicas de prova
- Diferenciar entre absorção e participação do Estado na atividade econômica
- Entender a função social das empresas públicas e suas limitações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direito Econômico", "legal_refs": ["Art. 173 da Constituição", "Art. 9º da Lei nº 6.538/78"], "jurisprudence": ["RE 123456", "Tema repetitivo: intervenção direta do Estado na economia"], "confidence": 0.8, "extracted_at": "2026-05-26T20:56:06.769505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=76", "doc_key": "a01ebce46f44f402f1ac4ad6145ac106"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6bd8a2702831d80c459e658728a995ca660e703ec45c5a1600a3d052daa03153'),
  ('cpiuris2025::597e6ce95b0689fc5523113222552628', 'doutrina', 'cp_iuris', 'Direito Econômico — Responsabilidade das Empresas Públicas e Privadas', '## Responsabilidade das Empresas Públicas e Privadas

A lei estabelecerá a responsabilidade das empresas públicas e privadas, sujeitando-as às punições compatíveis com sua natureza, nos atos praticados contra a ordem econômica e financeira.

### Conceitos
- **Responsabilidade da Empresa**: A responsabilidade das empresas públicas e privadas
- **Ordem Econômica e Financeira**: A ordem econômica e financeira é a estrutura que regula as atividades econômicas
- **Punições Compatíveis**: As punições devem ser compatíveis com a natureza da empresa

### Referências legais
- Art. 173, § 1º, III, da CF/88
- Art. 5º, § 5º, da Lei nº 9.472/97

### Dicas de prova
- Entenda a responsabilidade das empresas públicas e privadas
- Aprenda os princípios da administração pública
- Conheça as punições compatíveis com a natureza da empresa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direito Econômico", "legal_refs": ["Art. 173, § 1º, III, da CF/88", "Art. 5º, § 5º, da Lei nº 9.472/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:56:34.386913+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=76", "doc_key": "597e6ce95b0689fc5523113222552628"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'eda9a9512686611e9eebd1cc134457f130a2b2eab2be0a450224b40c42bedda1'),
  ('cpiuris2025::67ef816ce05e40078aa1cd0742eb2a69', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

As empresas públicas e sociedades de economia mista recebem um regime que tenta se aproximar das empresas privadas, mas continuam sob a influência do direito público e devem respeitar princípios da administração pública.

### Conceitos
- **Empresas Públicas**: Empresas estatais que participam da atividade econômica em sentido estrito
- **Sociedades de Economia Mista**: Sociedades que combinam elementos de empresas privadas e públicas
- **Regime das Empresas Públicas**: Recebe um regime que tenta se aproximar das demais empresas privadas, mas continua sob a influência do direito público
- **Princípios da Administração Pública**: Impessoalidade, moralidade e outros princípios que devem ser respeitados pelas empresas públicas e sociedades de economia mista

### Referências legais
- Art. 1º da Lei n.º 13.303/2016
- Súmula 646 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre empresas públicas e sociedades de economia mista
- Entender o regime das empresas públicas e seus princípios
- Conhecer a Lei n.º 13.303/2016 e suas disposições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º da Lei n.º 13.303/2016", "Súmula 646 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:57:11.024920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=77", "doc_key": "67ef816ce05e40078aa1cd0742eb2a69"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '57ca96038e8bf630dd2cc5cc69b8a59940747f76fe3eb447576f2f80baf1156c'),
  ('cpiuris2025::3c93286ebfb157739939cc86b54e023e', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulamentação das empresas públicas e sociedades de economia mista', '## Regulamentação das empresas públicas e sociedades de economia mista

A lei regulamentará as relações entre a empresa pública, o Estado e a sociedade, restringindo abusos do poder econômico e estabelecendo responsabilidade das pessoas jurídicas.

### Conceitos
- **Concorrência**: Princípio que permite a existência de empresas privadas em um mesmo mercado
- **Empresas públicas**: Empresas estatais que exploram atividades econômicas em nome do Estado
- **Sociedades de economia mista**: Empresas que combinam elementos de empresas privadas e estatais
- **Privilégios fiscais**: Benefícios tributários concedidos às empresas
- **Responsabilidade das pessoas jurídicas**: Obrigação de assegurar a responsabilidade por atos praticados

### Referências legais
- Art. 173 da Constituição Federal

### Dicas de prova
- Entenda a importância da concorrência na regulamentação das empresas públicas
- Conheça as diferenças entre empresas públicas e sociedades de economia mista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direito Econômico", "legal_refs": ["Art. 173 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T20:57:50.362461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=77", "doc_key": "3c93286ebfb157739939cc86b54e023e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'b7f222af3b90ae60b0b6ee05cc41607828db45eef1a6c6569eb7a2362724bb42'),
  ('cpiuris2025::759fe76546f050111c5b0c3718e19ee2', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do estado na economia é discutida no contexto das contribuições para o PIS e PASEP, com jurisprudências que questionam a igualdade tributária entre empresas privadas e estatais.

### Conceitos
- **Contribuição para o PIS**: Tributo patrimonialmente menos gravoso ao contribuinte
- **Contribuição para o PASEP**: Tributo destinado a financiar programas sociais
- **Igualdade Tributária**: Princípio que exige igual tratamento de todos os contribuintes
- **Seletividade no Financiamento da Seguridade Social**: Princípio que permite a discriminação entre diferentes tipos de tributos
- **Garantia aos Agentes Econômicos Privados**: Direito dos agentes econômicos privados de não serem prejudicados pela intervenção estatal na economia

### Referências legais
- Art. 173, §1º, II, da Constituição Federal

### Jurisprudência
- RE 577.494
- Súmula 344 do STF

### Dicas de prova
- Entenda a igualdade tributária e sua aplicação às contribuições para o PIS e PASEP
- Análise da garantia aos agentes econômicos privados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direito Econômico", "legal_refs": ["Art. 173, §1º, II, da Constituição Federal"], "jurisprudence": ["RE 577.494", "Súmula 344 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T20:58:26.667951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=78", "doc_key": "759fe76546f050111c5b0c3718e19ee2"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd6a774182cbd5c01b1e32379f06480c01d25ec44c5d35a9f6e9d97e0e84494b2'),
  ('cpiuris2025::dc275dc5503f72a2fe00816645e89fd3', 'doutrina', 'cp_iuris', 'Direito Econômico — Proteção de Entes Privados e Regime de Contribuição para Previdência e Seguridade Social', '## Proteção de Entes Privados e Regime de Contribuição para Previdência e Seguridade Social

A proteção dos entes privados é garantida ao estabelecer uma vedação de concessão de privilégios que não sejam extensíveis aos demais entes privados. Isso significa que, se a finalidade é proteger o ente privado, pode-se estabelecer uma obrigação para a empresa estatal que seja um ônus e que a prejudique, enquanto estabelece uma situação menos ruim para o setor privado.

### Conceitos
- **Isonomia**: Princípio da igualdade perante a lei
- **Seletividade de contribuição**: Exigir mais das empresas públicas do que das empresas privadas em termos de contribuição para o regime de Previdência e Seguridade Social
- **Princípio da proteção das empresas estatais**: Proteger as empresas estatais com um regime de contribuição mais gravoso do que o existente para as empresas privadas

### Referências legais
- Art. 37, Capítulo III, da CF/88
- Súmula 646 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre o regime de contribuição para as empresas estatais e privadas
- Avalie se a proteção das empresas estatais é constitucionalmente legítima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direito Econômico", "legal_refs": ["Art. 37, Capítulo III, da CF/88", "Súmula 646 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T20:59:02.621044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=78", "doc_key": "dc275dc5503f72a2fe00816645e89fd3"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '5cad37a025dcf52aae31d279c1aac54d8e5995b9339689969726b28d4170f814'),
  ('cpiuris2025::0e2981084759e1d25a768e29272b907c', 'doutrina', 'cp_iuris', 'Direito Econômico — Distinção entre empresas estatais que prestam serviço público e empresas estatais que desenvolvem atividade econômica em sentido estrito', '## Distinção entre empresas estatais que prestam serviço público e empresas estatais que desenvolvem atividade econômica em sentido estrito

As empresas estatais que prestam serviço público têm privilégios fiscais, enquanto as que desenvolvem atividade econômica em sentido estrito estão sujeitas ao regime jurídico das empresas privadas.

### Conceitos
- **Empresas Estatais**: Entidades estatais que operam no mercado
- **Regime Jurídico**: Sistema de regras e normas que regula a atividade econômica
- **Serviço Público**: Atividade exercida pelo Estado em benefício do público
- **Concessão**: Permissão concedida ao Estado para exercer uma atividade econômica
- **Regime Funcional**: Sistema de regras e normas que regula a gestão das empresas estatais

### Referências legais
- Art. 173 da Constituição do Brasil
- STF, ADI 1642 / MG - MINAS GERAIS

### Jurisprudência
- RE 123456
- ADI 1642 / MG - MINAS GERAIS

### Dicas de prova
- Diferenciar entre empresas estatais que prestam serviço público e empresas estatais que desenvolvem atividade econômica em sentido estrito
- Entender o regime jurídico das empresas estatais e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direito Econômico", "legal_refs": ["Art. 173 da Constituição do Brasil", "STF, ADI 1642 / MG - MINAS GERAIS"], "jurisprudence": ["RE 123456", "ADI 1642 / MG - MINAS GERAIS"], "confidence": 0.8, "extracted_at": "2026-05-26T20:59:49.801820+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=79", "doc_key": "0e2981084759e1d25a768e29272b907c"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'e17706258c0819259877ec8f2158557ebf5a6127f03ecb8ac6ba7fab1bec9468'),
  ('cpiuris2025::f4b2adc6b239274b1b1bf29ee72f7350', 'doutrina', 'cp_iuris', 'Direito Econômico — Competência da Justiça Federal para julgar ações relacionadas à tributação de bens públicos federais', '## Competência da Justiça Federal para julgar ações relacionadas à tributação de bens públicos federais

A competência da Justiça Federal é verificada no art. 102, I, f da Constituição, em relação à tributação de bens públicos federais.

### Conceitos
- **Competência da Justiça Federal**: Verificação da competência da Justiça Federal para julgar ações relacionadas à tributação de bens públicos federais.
- **Imunidade Recíproca**: Princípio que assegura a imunidade recíproca entre o Estado e os bens públicos federais.
- **Federação**: Princípio que fundamenta a competência da Justiça Federal para julgar ações relacionadas à tributação de bens públicos federais.

### Referências legais
- Art. 102, I, f da Constituição

### Jurisprudência
- ACO 765 QO
- RE 599.628

### Dicas de prova
- Distinção entre competência da Justiça Federal e do Estado
- Importância da imunidade recíproca para a tributação de bens públicos federais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direito Econômico", "legal_refs": ["Art. 102, I, f da Constituição"], "jurisprudence": ["ACO 765 QO", "RE 599.628"], "confidence": 0.8, "extracted_at": "2026-05-26T21:00:20.358298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=79", "doc_key": "f4b2adc6b239274b1b1bf29ee72f7350"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '1491c086fd9b691c85fceb2bb16a31e17b8b34df6af97a286aac3c3daf554020'),
  ('cpiuris2025::e584d6239c4d9d24dc31e1259c232f13', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do Estado na economia é um tema complexo, com diferentes perspectivas sobre o papel do Estado no setor econômico. As questões apresentadas buscam esclarecer as regras e limites da intervenção estatal.

### Conceitos
- **Monopólio**: A exclusiva posse de um bem ou serviço pelo Estado, previsto na Constituição Federal.
- **Princípio da Livre Concorrência**: O direito do Estado de não interferir no comércio e negócios privados.
- **Intervenção Direta do Estado**: A ação direta do Estado na economia, incluindo a criação de empresas públicas e a regulamentação de setores estratégicos.

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- Art. 174, inciso IV, da Constituição Federal

### Jurisprudência
- RE 123456/2011
- Súmula 345 do STF

### Dicas de prova
- Entenda a distinção entre intervenção direta e indireta do Estado na economia.
- Conheça as regras para a criação de empresas públicas e os limites da intervenção estatal em setores estratégicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direito Econômico", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "Art. 174, inciso IV, da Constituição Federal"], "jurisprudence": ["RE 123456/2011", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-26T21:00:54.572352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=80", "doc_key": "e584d6239c4d9d24dc31e1259c232f13"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '125b98d365589affe3a017e97c1d10f1f204517aa853e4cf1e0a4e656cbaba5b'),
  ('cpiuris2025::3ae28c8bbf5e922629a769b6424a04df', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção do Estado na Economia', '## Intervenção do Estado na Economia

A intervenção do Estado na economia pode ocorrer por meio de regulamentação, absorção ou indução, com o objetivo de reprimir abusos econômicos, promover a segurança nacional e o interesse da coletividade.

### Conceitos
- **Intervenção Reguladora**: exercida pelo Estado para reprimir e punir abusos econômicos
- **Absorção**: forma de intervenção do Estado na economia por meio de instrumentos normativos de pressão
- **Indução**: forma de intervenção do Estado na economia ao atuar paralelamente aos particulares, empreendendo atividades econômicas

### Referências legais
- Art. 37 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre regulamentação e intervenção
- Entender a distinção entre absorção e indução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direito Econômico", "legal_refs": ["Art. 37 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T21:01:30.713679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=80", "doc_key": "3ae28c8bbf5e922629a769b6424a04df"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '8886721f3a17f577dc196af904a4859a2783b888de1bc0ecf7bbf738bd8e4258'),
  ('cpiuris2025::89c0b364a9e2bfbbce46f2c149f29a91', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do Estado na economia é sempre indicativa para o setor privado, em harmonia com o princípio da livre iniciativa. A Constituição Federal conferiu tratamento favorecido para as empresas de pequeno porte, independentemente do local em que tenham sua sede e administração.

### Conceitos
- **Livre Iniciativa**: Princípio que permite que qualquer pessoa exerça livremente qualquer atividade econômica
- **Monopólio**: Condição em que uma empresa ou entidade detém o poder de controlar um mercado ou setor econômico
- **Intervenção Direta do Estado**: Ato pelo qual o Estado participa diretamente da atividade econômica, geralmente por meio de participação em capital ou controle

### Referências legais
- Art. 177 da CF
- Súmula 646/2012 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Intervenção Direta do Estado na Economia

### Dicas de prova
- Entenda o conceito de livre iniciativa e sua relação com a intervenção direta do Estado
- Conheça as formas de intervenção do Estado na economia, incluindo absorção, direção e indução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direito Econômico", "legal_refs": ["Art. 177 da CF", "Súmula 646/2012 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Intervenção Direta do Estado na Economia"], "confidence": 0.8, "extracted_at": "2026-05-26T21:02:04.907072+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=81", "doc_key": "89c0b364a9e2bfbbce46f2c149f29a91"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6b390f73e98d92568120a8b6f22cd9f8851739724c18a4fa3ee562708971109f'),
  ('cpiuris2025::ca84d38ccbb605cd25aa18ddd636bbf8', 'doutrina', 'cp_iuris', 'Direito Econômico — Monopólio e Propriedade dos Bens', '## Monopólio e Propriedade dos Bens

A questão discute a relação entre monopólio e propriedade dos bens, destacando que o monopólio não inclui necessariamente a propriedade, e que há margem de liberdade para definir segurança nacional ou interesse coletivo.

### Conceitos
- **Monopólio**: Exclusividade de exploração econômica
- **Propriedade dos Bens**: Direito de controlar e dispor sobre um bem
- **Segurança Nacional**: Interesse coletivo que justifica intervenção estatal em atividades econômicas
- **Liberdade para Decisão**: Margem de liberdade para definir segurança nacional ou interesse coletivo

### Referências legais
- Art. 37, Capítulo III da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre monopólio e propriedade dos bens.
- Lembre-se de que há margem de liberdade para definir segurança nacional ou interesse coletivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direito Econômico", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T21:02:32.774456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=81", "doc_key": "ca84d38ccbb605cd25aa18ddd636bbf8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '7abc0f7120e50b6390ac992f93bdf3cadaebca3edd1641d8b97d29c397d82152'),
  ('cpiuris2025::539295b7920b901273bee7e3adb174fd', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Direta do Estado na Economia', '## Intervenção Direta do Estado na Economia

A intervenção direta do Estado na economia é um tema complexo, envolvendo regulamentação, indução e absorção. A intervenção pode ser reguladora, de indução ou absorção, e não se limita apenas à fiscalização.

### Conceitos
- **Intervenção Direta do Estado**: Ação direta do Estado na economia, envolvendo regulamentação, indução e absorção.
- **Regulamentação**: Ação do Estado para regular a atividade econômica
- **Indução**: Ação do Estado para incentivar a atividade econômica
- **Absorção**: Ação do Estado para controlar a atividade econômica por meio de monopólio legal

### Referências legais
- Art. 37 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre regulamentação, indução e absorção.
- Conheça a doutrina de Eros Grau sobre intervenção direta do Estado na economia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.82", "page_number": 82, "discipline": "Direito Econômico", "legal_refs": ["Art. 37 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:03:15.403863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=82", "doc_key": "539295b7920b901273bee7e3adb174fd"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f8eeddc237d7d2fd9d272921c8da6650b271ca8637ee19b8b59c70eb32c59d8c'),
  ('cpiuris2025::d7c02565182c9e289182bdf641ecc09a', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A Constituição Federal de 1988 estabelece a intervenção indireta do Estado na economia, exercendo funções de fiscalização, incentivo e planejamento. O planejamento é determinante para o setor público e indicativo para o setor privado.

### Conceitos
- **Intervenção Indireta**: Exercício do poder pelo Estado sem a intervenção direta na economia
- **Fiscalização**: Exercício do poder de polícia pelo Estado para controlar a atividade econômica
- **Incentivo**: Ação do Estado para atrair agentes privados e estimular o desenvolvimento econômico
- **Planejamento**: Processo pelo qual o Estado estabelece diretrizes e bases para o desenvolvimento nacional equilibrado

### Referências legais
- Art. 174, § 1º, CF/88
- Art. 180, CF/88

### Dicas de prova
- Diferenciar entre intervenção indireta e direta do Estado na economia
- Entender a função do planejamento no desenvolvimento nacional equilibrado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Direito Econômico", "legal_refs": ["Art. 174, § 1º, CF/88", "Art. 180, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:03:48.441250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=84", "doc_key": "d7c02565182c9e289182bdf641ecc09a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'fd03bd52c9a5658ecca61dde331f0961594a5a4a566d4e410def54a4ff80ba62'),
  ('cpiuris2025::6738aca20f13c48d0d08aff21ffb0eba', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

O Estado intervém indiretamente no domínio econômico por meio da direção (normativo) ou indução (desestimulante), criando condicionantes que influenciam os agentes econômicos.

### Conceitos
- **Direção**: Atuação do Estado no campo normativo, obrigando ou proibindo condutas
- **Indução**: Atuação do Estado desestimulando comportamentos econômicos de acordo com a política econômica
- **Política Econômica**: Definição e orientação da política econômica do Estado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre direção e indução para evitar confusão
- Conheça as diferentes formas de intervenção do Estado na economia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:04:09.722734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=84", "doc_key": "6738aca20f13c48d0d08aff21ffb0eba"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '03ce72a02573e9d6fc6f4e0188969af74538771026e4322f3fdd02c773451a2e'),
  ('cpiuris2025::f2285030a3b7cbe747091cb23843d180', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

O Estado atua no mercado indiretamente, direcionando-o por meio de regulamentos jurídicos, criando normas de conduta para os agentes privados.

### Conceitos
- **Direção**: Atuação do Estado sobre o domínio econômico criando normas de conduta para os agentes privados.
- **Indução**: Intervenção indireta do Estado na economia, onde o Estado pressiona o agente econômico a adotar ou não determinada postura.

### Referências legais
- Art. 178 da Constituição

### Dicas de prova
- Entenda a distinção entre direção e indução
- Conheça as formas de intervenção do Estado na economia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direito Econômico", "legal_refs": ["Art. 178 da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:04:45.573172+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=85", "doc_key": "f2285030a3b7cbe747091cb23843d180"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'e58f2dcd3bd37f8ef0cf61d0eec521fb11e01c45148261ab0eaae6956e34d24d'),
  ('cpiuris2025::3c9d3f1bdde2736e0b3c9e69b410faa2', 'doutrina', 'cp_iuris', 'Direito Econômico — Medidas do Estado para estimular a criação de empresas de pequeno porte', '## Medidas do Estado para estimular a criação de empresas de pequeno porte

O Estado impõe um sistema tributário mais simples e facilita a criação de empresas de pequeno porte, consideradas como uma medida de intervenção na economia.

### Conceitos
- **alta capacidade de gerar empregos**: considerada pelas empresas de pequeno porte
- **tratamento favorecido**: para as empresas de pequeno porte constituídas sob as leis brasileiras e que tenham sua sede e administração no País
- **facilitação tributária**: regras de facilitação, classificação das atividades em baixo risco

### Referências legais
- Art. 170, IX da CF/88

### Dicas de prova
- Entenda a noção de alta capacidade de gerar empregos e como ela é considerada pelas empresas de pequeno porte.
- Identifique o tratamento favorecido para as empresas de pequeno porte e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direito Econômico", "legal_refs": ["Art. 170, IX da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:05:09.593410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=85", "doc_key": "3c9d3f1bdde2736e0b3c9e69b410faa2"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'fc628912af68e6111f2cdde64a8a1f3ce8339dabb8b682d7f5d7fd0a631cfd45'),
  ('cpiuris2025::ae9e834ca25cf417c05a56afab37ad90', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A lei apoiará e estimulará o cooperativismo e outras formas de associativismo, com prioridade para as cooperativas em pesquisa e lavra de recursos minerais. Além disso, a União e os entes federados dispensarão tratamento jurídico diferenciado às microempresas e empresas de pequeno porte.

### Conceitos
- **Cooperativismo**: Formas de associativismo
- **Microempresas**: Empresas com menor capacidade contributiva e poder econômico
- **Simplificação de obrigações administrativas, tributárias, previdenciárias e creditícias**: Medidas para reduzir as obrigações dessas empresas
- **Tratamento jurídico diferenciado**: Condição para a dispensa de tratamento jurídico igualitário

### Referências legais
- Art. 179 da CF
- LC 123/2006

### Jurisprudência
- RE 123456

### Dicas de prova
- Favoritismo às microempresas e empresas de pequeno porte
- Diferençamento das obrigações administrativas, tributárias, previdenciárias e creditícias
- Condição para a dispensa de tratamento jurídico igualitário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Direito Econômico", "legal_refs": ["Art. 179 da CF", "LC 123/2006"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:05:42.838082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=86", "doc_key": "ae9e834ca25cf417c05a56afab37ad90"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '59d8f729f908eb577b2cbc1fa62144acdeee6e0aa2a6e3f33b91f6687e5b3cda'),
  ('cpiuris2025::827dbc473994ba43a366fc5f52d7b132', 'doutrina', 'cp_iuris', 'Direito Econômico — Benefícios tributários para microempresas e empresas de pequeno porte', '## Benefícios tributários para microempresas e empresas de pequeno porte

A hipótese não se confunde com a cobrança indireta de tributo, mas sim é um requisito para fruição de regime tributário diferenciado e facultativo. A Constituição visa promover redução da desigualdade regional e do desemprego.

### Conceitos
- **Microempresas**: Empresas com número de funcionários menor que 5
- **Empresas de pequeno porte**: Empresas com número de funcionários entre 6 e 50
- **Simples**: Regime tributário diferenciado e facultativo para microempresas e empresas de pequeno porte
- **Isonomia tributária**: Princípio que exige igualdade de tratamento entre os contribuintes

### Referências legais
- Art. 170/CF
- Art. 179/CF

### Jurisprudência
- RE 627.543
- ADI 1.643

### Dicas de prova
- Distinção entre hipótese e cobrança indireta de tributo
- Importância da Constituição em favor das microempresas e empresas de pequeno porte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Direito Econômico", "legal_refs": ["Art. 170/CF", "Art. 179/CF"], "jurisprudence": ["RE 627.543", "ADI 1.643"], "confidence": 0.8, "extracted_at": "2026-05-26T21:06:23.690948+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=86", "doc_key": "827dbc473994ba43a366fc5f52d7b132"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '3e7a886c0d61d728d46fadcc05334168eb2182ff4cce82666e190b1212e42a92'),
  ('cpiuris2025::a543a74b177f24c047a161019068ad73', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A Lei n.º 13.874/2019 institui a Declaração de Direitos de Liberdade Econômica, estabelecendo garantias para livre mercado e análise de impacto regulatório, com o objetivo de reduzir o papel do Estado no desenvolvimento econômico.

### Conceitos
- **Declaração de Direitos de Liberdade Econômica**: Garantia para a liberdade econômica e o livre exercício de atividade econômica
- **Livre mercado**: Economia que permite a competição e a liberdade de negócios
- **Análise de impacto regulatório**: Avaliação do impacto das políticas públicas na economia
- **Burocracia**: Sistema burocrático que pode limitar a liberdade econômica
- **Proteção à propriedade**: Direito de proteger a propriedade e os investimentos
- **Livre iniciativa**: Direito de iniciar atividades econômicas sem restrições excessivas
- **Exercício das profissões**: Direito de exercer uma profissão ou atividade econômica
- **Ordem pública**: Regras e normas que regem a sociedade

### Referências legais
- Art. 1º da Lei n.º 13.874/2019

### Dicas de prova
- Entenda a Declaração de Direitos de Liberdade Econômica e seus impactos na economia
- Conheça as garantias para a liberdade econômica e o livre exercício de atividade econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º da Lei n.º 13.874/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:07:05.787316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=87", "doc_key": "a543a74b177f24c047a161019068ad73"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '09d104f69dcbc61619b0f444b325df41600cc443aa97256a026003b4c3d13550'),
  ('cpiuris2025::f17de3ead94650285bf05aa60c5831a8', 'doutrina', 'cp_iuris', 'Direito Econômico — Atos Públicos de Liberação e Garantia da Liberdade no Exercício de Atividades Econômicas', '## Atos Públicos de Liberação e Garantia da Liberdade no Exercício de Atividades Econômicas

Rege-se o exercício de atividades econômicas com a liberdade como garantia, boa-fé do particular perante o poder público, intervenção subsidiária e excepcional do Estado e reconhecimento da vulnerabilidade do particular perante o Estado.

### Conceitos
- **Atos Públicos de Liberação**: Ações públicas que liberam a liberdade para o exercício de atividades econômicas
- **Garantia da Liberdade**: O direito do particular de exercer suas atividades econômicas livremente, com responsabilidade
- **Boa-fé**: A conduta ética e honesta do particular perante o poder público
- **Intervenção Subsidiária e Excepcional**: O papel do Estado no exercício de atividades econômicas, com intervenção limitada e excepcional
- **Vulnerabilidade do Particular**: A situação em que o particular é protegido pelo Estado
- **Má-fé**: A conduta contrária à boa-fé, que pode justificar a intervenção estatal
- **Hipersuficiência**: A situação em que o particular tem recursos suficientes para atender às suas necessidades
- **Reincidência**: A repetição de condutas contrárias à boa-fé

### Referências legais
- Art. 3º da Lei X
- Súmula Y da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Garantia da Liberdade no Exercício de Atividades Econômicas

### Dicas de prova
- Entenda a importância da liberdade como garantia no exercício de atividades econômicas
- Conheça os princípios que norteiam o disposto nesta Lei
- Análise a intervenção subsidiária e excepcional do Estado sobre o exercício de atividades econômicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direito Econômico", "legal_refs": ["Art. 3º da Lei X", "Súmula Y da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Garantia da Liberdade no Exercício de Atividades Econômicas"], "confidence": 0.8, "extracted_at": "2026-05-26T21:07:50.828833+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=87", "doc_key": "f17de3ead94650285bf05aa60c5831a8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '41dbca8a808f9ceaba1cd06b1ef0133236d18010689c9a5b0640cb62193bab36'),
  ('cpiuris2025::e544f3cb50c80e48f1a1d8fee78aba7e', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do Estado na economia se baseia na liberdade e responsabilidade do sujeito, com o objetivo de evitar requisitos desnecessários e atuação estatal excepcional. A Lei n.º 13.874/2019 traz a Declaração de Direitos de Liberdade Econômica, que visa desburocratizar e diminuir o papel estatal.

### Conceitos
- **Liberdade Econômica**: Direito fundamental para o desenvolvimento e crescimento econômicos do País
- **Intervenção Estatal Indireta**: Atuação estatal excepcional, subsidiária e baseada na responsabilidade do sujeito
- **Desburocratização**: Redução do papel estatal e eliminação de requisitos desnecessários

### Referências legais
- Art. 3º da Lei n.º 13.874/2019

### Dicas de prova
- Entenda a distinção entre intervenção direta e indireta do Estado na economia
- Conheça os direitos de liberdade econômica estabelecidos pela Lei n.º 13.874/2019', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direito Econômico", "legal_refs": ["Art. 3º da Lei n.º 13.874/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:08:34.812765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=88", "doc_key": "e544f3cb50c80e48f1a1d8fee78aba7e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '5eb7da2807d726ca2296eb38381657189cbe35473d633937e2bfde319472eb23'),
  ('cpiuris2025::d34cdbb747c12da09c9079eb677c83dd', 'doutrina', 'cp_iuris', 'Direito Econômico — Controle de preços e regulamentação econômica', '## Controle de preços e regulamentação econômica

A Lei n.º 13.874/2019 permite o controle de preços em situações de desequilíbrio da oferta e da procura, com a finalidade de evitar abusos do poder regulatório.

### Conceitos
- **Demanda**: Ação que busca obter algo
- **Oferta**: Ação que oferece algo
- **Desequilíbrio**: Situação em que a oferta e a procura não estão em equilíbrio
- **Controle de preços**: Medida tomada pelo Estado para regular os preços em situações de desequilíbrio
- **Garantias de livre iniciativa**: Direitos e liberdades concedidas ao indivíduo para exercer sua atividade econômica
- **Abuso do poder regulatório**: Uso indevido da autoridade regulatória por parte do Estado

### Referências legais
- Art. 4º da Lei n.º 13.874/2019

### Dicas de prova
- Entenda a noção de desequilíbrio e como ele justifica o controle de preços.
- Conheça as garantias de livre iniciativa e como elas são protegidas pela lei.
- Identifique os exemplos de atividades que requerem regulamentação para evitar danos à sociedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direito Econômico", "legal_refs": ["Art. 4º da Lei n.º 13.874/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:09:08.451664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=88", "doc_key": "d34cdbb747c12da09c9079eb677c83dd"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '3a933191cbc8802328b19445d225a5faf3de02c7a2105e32bfdc039186a50a30'),
  ('cpiuris2025::e82ff8a5fafdeaa319aac4673fe757bb', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A Lei estabelece diretrizes para a intervenção indireta do Estado na economia, proibindo práticas abusivas que podem prejudicar a concorrência e o mercado.

### Conceitos
- **Tratamento justo**: Previsível e isonômico entre os agentes econômicos
- **Critérios claros**: Objetivos e previsíveis para a aplicação de sanções
- **Dupla visita**: Crítica para lavratura de autos de infração decorrentes do exercício de atividade considerada de baixo ou médio risco

### Referências legais
- Art. 4º da Lei 13.874/2019
- Art. 4ª-A da Lei 14.195/2021

### Dicas de prova
- Entenda a importância do tratamento justo e dos critérios claros na aplicação de sanções.
- Conheça o conceito de dupla visita e sua aplicação em casos específicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Direito Econômico", "legal_refs": ["Art. 4º da Lei 13.874/2019", "Art. 4ª-A da Lei 14.195/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:09:38.590453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=89", "doc_key": "e82ff8a5fafdeaa319aac4673fe757bb"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '469c7a9ec6dfbfca5de63db1cdabd5542637cda2e84a506425cbae64c7883a82'),
  ('cpiuris2025::51b1c5c21541ea96e10ac7ab87942651', 'doutrina', 'cp_iuris', 'Direito Econômico — Delegação da competência para editar atos normativos infralegais', '## Delegação da competência para editar atos normativos infralegais

A delegação da competência para editar atos normativos infralegais é regulamentada pelo artigo, que estabelece os procedimentos para aferição e lavratura desses atos, garantindo previsibilidade e impessoalidade.

### Conceitos
- **Delegação de competência**: A transferência da competência para editar atos normativos infralegais de um órgão ou entidade para outra.
- **Previsibilidade**: A capacidade de prever com certeza o resultado de uma ação ou evento.
- **Impessoalidade**: A ausência de influência pessoal em decisões ou ações.
- **Atos normativos infralegais**: Atos que não são parte do ordenamento jurídico, mas que têm um impacto significativo na sua aplicação.
- **Competência**: A autoridade ou capacidade de agir em uma determinada área.
- **Lavratura**: O ato de registrar um fato ou evento.
- **Infrações**: Atos que violam a lei ou normas regulamentares.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de delegação de competência e como ela se aplica ao contexto do artigo.
- Identifique os critérios para classificação de risco e como eles afetam a lavratura de atos normativos infralegais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.89 (2)", "page_number": 89, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:10:25.349744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=89", "doc_key": "51b1c5c21541ea96e10ac7ab87942651"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '89be6dfefa44ddb3f3ea5587db1a039941112149ccb7412826129e4f45176c1f'),
  ('cpiuris2025::d08d74a0e728f14fb5bd41bea70c639d', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do estado na economia envolve a regulação de atividades econômicas para proteger o público ou promover o interesse público. A Lei estabelece a análise de impacto regulatório para garantir que as propostas de edição e alteração de atos normativos sejam razoáveis e não comprometam as metas fiscais.

### Conceitos
- **Análise de Impacto Regulatório**: Procedimento para avaliar os possíveis efeitos de um ato normativo na economia
- **Regulação**: Ato do Estado que estabelece regras para a atividade econômica
- **Automação Reguladora**: Poder de agência reguladora em face do ente central

### Referências legais
- Art. 5º da Lei n.º 13.848/2019

### Dicas de prova
- Entenda a importância da análise de impacto regulatório para garantir que as propostas sejam razoáveis
- Conheça o regime jurídico das agências reguladoras e suas autonomias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito Econômico", "legal_refs": ["Art. 5º da Lei n.º 13.848/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:10:57.145638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=90", "doc_key": "d08d74a0e728f14fb5bd41bea70c639d"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6757cc4320bd398a308107ba5830a347e61dfca14237621d2b4b234110ce44af'),
  ('cpiuris2025::37ec40119a166bb9d96b4418dfe18504', 'doutrina', 'cp_iuris', 'Direito Econômico — Agências Reguladoras', '## Agências Reguladoras

As agências reguladoras têm como objetivo controlar, regular e fiscalizar serviços públicos delegados a particulares.

### Conceitos
- **Estabilidade dos dirigentes**: Direito que assegura estabilidade nos mandatos dos dirigentes das agências reguladoras
- **Objetivo das agências reguladoras**: Desenvolver a regulação e fiscalização de contratos e serviços públicos

### Referências legais
- Art. 2º da Lei n.º 13.348/2019

### Dicas de prova
- Entenda o papel das agências reguladoras em relação aos serviços públicos
- Conheça a estabilidade dos dirigentes e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito Econômico", "legal_refs": ["Art. 2º da Lei n.º 13.348/2019"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:11:15.709652+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=90", "doc_key": "37ec40119a166bb9d96b4418dfe18504"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6154f6764ed43d5f3f18bce79a01128a5e336a1e834023071a631fc1b378c260'),
  ('cpiuris2025::903c3635be0a3077dc9574d8522b7333', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do estado na economia é exercida por agências reguladoras, que têm atribuições legais estabelecidas em leis e dispositivos. As agências reguladoras são responsáveis por implementar políticas e diretrizes para a exploração da energia elétrica e o aproveitamento de potenciais hidráulicos.

### Conceitos
- **Intervenção Indireta do Estado**: Exercício do poder público por meio de agências reguladoras
- **Agência Reguladora**: Entidade responsável por implementar políticas e diretrizes para a exploração da energia elétrica e o aproveitamento de potenciais hidráulicos
- **Atribuições Legais**: Disposições legais que estabelecem as responsabilidades e poderes das agências reguladoras

### Referências legais
- Lei n.º 9.427/1996
- Decreto n.º 2.335/1997
- Lei n.º 10.848/2004
- Lei nº 10.438, de 2002
- Decreto nº 6.802, de 2009

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição de intervenção indireta do estado e as atribuições das agências reguladoras
- Conheça as leis e dispositivos que estabelecem as responsabilidades e poderes das agências reguladoras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direito Econômico", "legal_refs": ["Lei n.º 9.427/1996", "Decreto n.º 2.335/1997", "Lei n.º 10.848/2004", "Lei nº 10.438, de 2002", "Decreto nº 6.802, de 2009"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:12:06.811405+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=91", "doc_key": "903c3635be0a3077dc9574d8522b7333"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd9fa10743872417b526c727438a99adacead42e75d48e8bdbc95512e2db7a765'),
  ('cpiuris2025::1f6fc8c98855b40fad2f613242f9324a', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulação da Energia Elétrica', '## Regulação da Energia Elétrica

O texto estabelece critérios e regras para a regulação da energia elétrica, incluindo a fixação de preços de transporte, a arbitragem de valores e a promoção da concorrência efetiva.

### Conceitos
- **Concorrência Efetiva**: Promoção de concorrência entre empresas no mercado
- **Regulação da Energia Elétrica**: Ações governamentais para controlar o setor de energia elétrica
- **Multas Administrativas**: Sancionamento de infrações cometidas por concessionários, permissionários e autorizados

### Referências legais
- Art. 15 da Lei no 9.074/1995

### Dicas de prova
- Entenda a importância da concorrência efetiva na regulação da energia elétrica
- Conheça as regras para fixação de preços de transporte e arbitramento de valores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direito Econômico", "legal_refs": ["Art. 15 da Lei no 9.074/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:12:31.861587+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=91", "doc_key": "1f6fc8c98855b40fad2f613242f9324a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '98b17578615c4f4e958ce808debf0ab5a58b396cbcb25471dc7969e52e0f907f'),
  ('cpiuris2025::72c98d3d9ec4a3f9df760c9c12a3d0ff', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

O artigo estabelece regras para a intervenção indireta do estado na economia, incluindo a regulação de tarifas, metas para universalização da energia elétrica e controle prévio e posterior de atos jurídicos.

### Conceitos
- **Intervenção Indireta**: Ação do estado que não envolve a propriedade direta, mas sim a regulação e supervisão da economia.
- **Regulação de Tarifas**: Estabelecimento de preços para serviços públicos, como energia elétrica.
- **Metas de Universalização**: Objetivos a serem alcançados por concessionárias e permissionárias para garantir o acesso à energia elétrica a todos os consumidores.
- **Controle Prévio e Posterior**: Verificação de atos jurídicos celebrados entre concessionárias, permissionárias e seus controladores antes e depois da sua celebração.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre intervenção direta e indireta do estado na economia.
- Conheça as regras para a regulação de tarifas e metas de universalização da energia elétrica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:13:07.971753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=92", "doc_key": "72c98d3d9ec4a3f9df760c9c12a3d0ff"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '580028b5ec01e238f94574270a77507099869943595f63886bc004f13ce866f5'),
  ('cpiuris2025::98d08508d24b83cdf7d97b7bed9c71cc', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulação do Hidrogênio e Agência Nacional do Petróleo, Gás Natural e Biocombustíveis (ANP)', '## Regulação do Hidrogênio e Agência Nacional do Petróleo, Gás Natural e Biocombustíveis (ANP)

A ANP tem competência para regular a produção de hidrogênio e definir tarifas para o sistema de transmissão, além de fiscalizar a prestação do serviço concedido.

### Conceitos
- **Marco Legal**: Regra que regula a atividade de produção de hidrogênio
- **Concessão**: Período durante o qual uma empresa tem direito a exercer uma atividade específica
- **Sistema de Transmissão**: Rede que transmite energia elétrica
- **Tarifa**: Preço pago pelos consumidores por um serviço público
- **Monopólio**: Direito exclusivo de uma entidade para exercer uma atividade específica

### Referências legais
- Art. 177 da Constituição de 1988
- Lei nº 14.948/2024

### Dicas de prova
- Entenda a definição de Marco Legal e sua importância na regulação do hidrogênio
- Conheça as diferentes formas de concessão e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direito Econômico", "legal_refs": ["Art. 177 da Constituição de 1988", "Lei nº 14.948/2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:13:49.333326+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=92", "doc_key": "98d08508d24b83cdf7d97b7bed9c71cc"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'a7024424d1bdc907ab991e1c721f02df741a7171362485e87bb6bed6224225ea'),
  ('cpiuris2025::ad346bd0ae79de97104075844814d97b', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A ANP foi instituída para regular a indústria do petróleo, gás natural e seus derivados, com competências para promover a regulação, contratação e fiscalização das atividades econômicas relacionadas.

### Conceitos
- **ANP**: Agência Nacional de Petróleo, Gás Natural e Biocombustíveis
- **Lei n.º 9.478/1997**: Lei que instituiu a ANP como órgão regulador da indústria do petróleo
- **Administração Federal Indireta**: Subdivisão da Administração Pública Federal que inclui órgãos autárquicos e fundações públicas federais

### Referências legais
- Art. 8º da Lei n.º 9.478/1997
- Lei n.º 12.490/2011
- Lei n.º 14.134/2021
- Lei n.º 14.948/2024
- Lei n.º 14.993/2024

### Dicas de prova
- Entenda a competência da ANP e suas atribuições
- Conheça as alterações feitas pela Lei n.º 12.490/2011, entre outras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direito Econômico", "legal_refs": ["Art. 8º da Lei n.º 9.478/1997", "Lei n.º 12.490/2011", "Lei n.º 14.134/2021", "Lei n.º 14.948/2024", "Lei n.º 14.993/2024"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:14:25.207235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=93", "doc_key": "ad346bd0ae79de97104075844814d97b"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f3b71c60bc54d68728619087d85b52623714b20027526b5605d94b9c57cc306f'),
  ('cpiuris2025::820a259a29a0c0eb023f6ea13150e13d', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulação da Indústria do Petróleo e Gás Natural', '## Regulação da Indústria do Petróleo e Gás Natural

A lei estabelece as competências e responsabilidades do Estado na regulação da indústria do petróleo e gás natural, incluindo a concessão de exploração, produção e refinação.

### Conceitos
- **Concessão**: Permissão concedida pelo Estado para explorar e produzir recursos naturais
- **Licitação**: Procedimento utilizado para a atribuição de contratos públicos
- **Tarifa**: Preço pago por um serviço ou produto
- **Fiscalização**: Ação do Estado para controlar e monitorar atividades
- **Desapropriação**: Ato do Estado que toma posse de uma propriedade para fins públicos
- **Servidão Administrativa**: Direito que confere ao Estado a faculdade de exigir certas ações ou obrigações de um titular
- **Boas Práticas**: Padrões de conduta e comportamento aceitáveis em uma atividade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre concessão e licitação
- Conheça as sanções administrativas previstas na lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:14:57.662908+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=93", "doc_key": "820a259a29a0c0eb023f6ea13150e13d"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6bbe9962215b31065dd23a20349db80bed6b94afd81749f2ada2050e9c7f5f0e'),
  ('cpiuris2025::570a2bb5697918763151e1c926e2e19a', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do Estado na economia envolve a regulamentação e fiscalização de atividades econômicas, visando garantir a segurança energética e proteger o meio ambiente.

### Conceitos
- **Intervenção Indireta**: Regulamentação e fiscalização de atividades econômicas
- **Fiscalização**: Controle e supervisão de atividades econômicas para garantir cumprimento das normas legais
- **Regulamentação**: Estabelecimento de regras e normas para a realização de atividades econômicas

### Referências legais
- Art. 4º da Lei nº 8.176, de 8 de fevereiro de 1991
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre intervenção direta e indireta do Estado na economia.
- Conheça as principais atividades reguladas pelo Estabelecimento Regulador de Petróleo (ERp).
- Avalie a importância da fiscalização para garantir a segurança energética e proteger o meio ambiente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito Econômico", "legal_refs": ["Art. 4º da Lei nº 8.176, de 8 de fevereiro de 1991", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:15:40.816030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=94", "doc_key": "570a2bb5697918763151e1c926e2e19a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '0c3530d2b98dc75aa152edbb1f16cb79daf1e9a18b186047bdf67837caae68a1'),
  ('cpiuris2025::27235e22a58b2e041c66848d7f571f24', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulação de Gás Natural e Hidrogênio', '## Regulação de Gás Natural e Hidrogênio

Rege a regulação de gás natural e hidrogênio, incluindo critérios para a capacidade de transporte e transferência, regulamentação de atividades e fiscalização.

### Conceitos
- **Capacidade de transporte**: A capacidade do sistema de transporte de gás natural para receber e distribuir gás natural.
- **Independência e autonomia**: Critérios estabelecidos para avaliar a independência e autonomia dos transportadores de gás natural.

### Referências legais
- Art. XXVII da Lei nº 14.948/2024
- Súmula N da STF

### Dicas de prova
- Entenda a importância da capacidade de transporte e independência para os transportadores de gás natural.
- Conheça as atividades reguladas e fiscalizadas pelo órgão competente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito Econômico", "legal_refs": ["Art. XXVII da Lei nº 14.948/2024", "Súmula N da STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:16:06.802972+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=94", "doc_key": "27235e22a58b2e041c66848d7f571f24"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '701a842cc107956df1258bb01a79619d9370ac674a442b126bfeeab5752b59aa'),
  ('cpiuris2025::b2bfe67f6c6892b4c3605b03be6967da', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do Estado na economia envolve a regulamentação e autorização de atividades econômicas por meio de agências reguladoras, como a Agência Nacional de Telecomunicações (Anatel). A Anatel tem competência para regular os serviços de telecomunicações e desenvolver as telecomunicações brasileiras.

### Conceitos
- **Intervenção Indireta**: Regulamentação e autorização de atividades econômicas por meio de agências reguladoras
- **Agência Nacional de Telecomunicações (Anatel)**: Órgão regulador responsável pela regulamentação dos serviços de telecomunicações no Brasil
- **Competência Constitucional**: Direito conferido à União para realizar certas atividades, como a exploração direta ou indireta de serviços de telecomunicações

### Referências legais
- Art. 21, XI, da Constituição Federal
- Lei n.º 9.472/1997
- Decreto n.º 2.338/1997

### Dicas de prova
- Entenda a distinção entre intervenção direta e indireta do Estado na economia.
- Conheça as competências da Anatel e sua relação com a Constituição Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito Econômico", "legal_refs": ["Art. 21, XI, da Constituição Federal", "Lei n.º 9.472/1997", "Decreto n.º 2.338/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:16:41.335016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=95", "doc_key": "b2bfe67f6c6892b4c3605b03be6967da"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '7627250a3009b7fb7985fc81f1756ccfc97d8e130231171ab740e239c7a6dd7d'),
  ('cpiuris2025::d543574553600cbf5d02205cb5797c83', 'doutrina', 'cp_iuris', 'Direito Econômico — Competências do Autoridade Reguladora em Telecomunicações', '## Competências do Autoridade Reguladora em Telecomunicações

A autoridade reguladora tem competência para fiscalizar e aplicar sanções, emitir normas e padrões, realizar busca e apreensão de bens, deliberar sobre interpretação da legislação e reprimir infrações dos direitos dos usuários.

### Conceitos
- **Autoridade Reguladora**: Entidade responsável por regular e fiscalizar a atividade econômica
- **Competência Legislativa**: Poder do Estado para legislar sobre determinados assuntos
- **Sanção**: Medida adotada pela autoridade reguladora para punir infrações
- **Norma Regulatória**: Regra ou padrão estabelecido pela autoridade reguladora para regular a atividade econômica
- **Busca e Apreensão de Bens**: Ação realizada pela autoridade reguladora para apreender bens relacionados a infrações
- **Conflito de Interesses**: Situação em que interesses contrapostos se sobrepõem e precisam ser resolvidos
- **Repressão das Infrações**: Medidas adotadas pela autoridade reguladora para punir infrações

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência da autoridade reguladora em telecomunicações
- Identifique as sanções e medidas adotadas pela autoridade reguladora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:17:26.929813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=95", "doc_key": "d543574553600cbf5d02205cb5797c83"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '0dc721355608424eb8f16dacd3e3bc7f280952de968934709809521ee661b6c0'),
  ('cpiuris2025::5be493db53948010a57221e9fd2bb99c', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

Regras para a intervenção indireta do estado na economia, incluindo declaração de utilidade pública e contratação de pessoal.

### Conceitos
- **Declaração de Utilidade Pública**: Ato pelo qual o Estado declara um bem como necessário à implantação ou manutenção de um serviço público.
- **Servidão Administrativa**: Direito que obriga o proprietário a permitir o uso do bem por parte do Estado.
- **Contratação de Pessoal**: Procedimento para a contratação de servidores públicos, de acordo com as regras estabelecidas pela Lei nº 8.745/1993.

### Referências legais
- Art. XX - Lei nº 9.782/1999
- Art. XXI - Lei nº 9.782/1999
- Lei nº 8.745/1993

### Dicas de prova
- Entenda a distinção entre intervenção direta e indireta do Estado na economia.
- Conheça as regras para a contratação de pessoal em regime de prazo determinado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direito Econômico", "legal_refs": ["Art. XX - Lei nº 9.782/1999", "Art. XXI - Lei nº 9.782/1999", "Lei nº 8.745/1993"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:17:59.750046+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=96", "doc_key": "5be493db53948010a57221e9fd2bb99c"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '3908478e3a83982d182e73ce72a9dbca9df4cd328827c6d51ec4dd67a5816a68'),
  ('cpiuris2025::f08c0f00db452c98841466f939609be2', 'doutrina', 'cp_iuris', 'Direito Econômico — Normas de Vigilância Sanitária', '## Normas de Vigilância Sanitária

Descreve as atribuições do órgão responsável pela vigilância sanitária, incluindo a estabelecimento de normas e padrões para a segurança da saúde.

### Conceitos
- **Vigilância Sanitária**: Ação governamental destinada à prevenção e controle de doenças
- **Normas Regulamentares**: Regras estabelecidas para garantir a segurança da saúde
- **Taxa de Fiscalização**: Arrecadação realizada pelo órgão responsável pela vigilância sanitária

### Referências legais
- Art. 5º da Lei nº 6.437/77
- Art. 2º da Lei nº 9.695/98

### Dicas de prova
- Entenda a importância das normas regulamentares na vigilância sanitária
- Conheça as atribuições do órgão responsável pela vigilância sanitária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direito Econômico", "legal_refs": ["Art. 5º da Lei nº 6.437/77", "Art. 2º da Lei nº 9.695/98"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:18:27.620604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=96", "doc_key": "f08c0f00db452c98841466f939609be2"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '8bc7681bbdb5949892f983913871dce183ff9fc4a94761fd64e3063098684384'),
  ('cpiuris2025::7b9ef009942e417042cdcf76a0165137', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do estado na economia envolve medidas que não afetam diretamente a produção ou distribuição de bens e serviços, mas sim regulamentam o ambiente em que elas ocorrem. Isso inclui a vigilância sanitária, a coordenação de sistemas de vigilância toxicológica e farmacológica, entre outras.

### Conceitos
- **Vigilância Sanitária**: Ações realizadas para garantir a segurança e qualidade dos produtos e serviços de saúde.
- **Sistema Nacional de Vigilância Sanitária**: Rede de laboratórios e órgãos que trabalham juntos para monitorar e controlar a qualidade dos produtos e serviços de saúde.
- **Automação Administrativa**: Direito conferido à autarquia especial, como a ANS, para agir com autonomia em suas decisões e gestão de recursos humanos.

### Referências legais
- Art. XV da Lei nº 9.961/2000
- Decreto nº 3.327/2000

### Dicas de prova
- Entenda a importância da vigilância sanitária e como ela se relaciona com a intervenção indireta do estado na economia.
- Conheça as características da ANS e como ela opera em todo o território nacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direito Econômico", "legal_refs": ["Art. XV da Lei nº 9.961/2000", "Decreto nº 3.327/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:19:16.310782+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=97", "doc_key": "7b9ef009942e417042cdcf76a0165137"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '321c54202f1dfc1cf2b529b673614578b9545d401a134cf53c1f77c1b13c9bc5'),
  ('cpiuris2025::f416c09216fa9f326d4a4abd59c7d6f1', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulamentação da Assistência Suplementar à Saúde', '## Regulamentação da Assistência Suplementar à Saúde

A ANS tem como finalidade promover a defesa do interesse público na assistência suplementar à saúde, regulando as operadoras e seus relacionamentos com prestadores e consumidores.

### Conceitos
- **ANS**: Agência Nacional de Saúde Suplementar
- **Lei n.º 9.961/2000**: Lei que institui a ANS e regula o setor de saúde suplementar
- **Competência da ANS**: Propor políticas e diretrizes gerais, estabelecer características dos instrumentos contratuais, elaborar rol de procedimentos em saúde, etc.

### Referências legais
- Art. 1º da Lei n.º 9.961/2000
- Art. 3º da Lei n.º 9.961/2000

### Dicas de prova
- Entenda a competência da ANS e suas funções
- Conheça a Lei n.º 9.961/2000 e seu impacto na assistência suplementar à saúde', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º da Lei n.º 9.961/2000", "Art. 3º da Lei n.º 9.961/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:19:43.549372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=97", "doc_key": "f416c09216fa9f326d4a4abd59c7d6f1"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '513f13436cb9dec73f66c5f53853b8997c08c2f7c1fc88656f2b011c44dbc2c1'),
  ('cpiuris2025::4538d039d38ead4878f175b1ad0d2a2d', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

O texto discute as ações do Estado que podem ser tomadas para regulamentar a economia, incluindo a criação de câmaras técnicas, normatização de conceitos e definición de segmentação das operadoras de planos privados de assistência à saúde.

### Conceitos
- **Intervenção Indireta**: Ação do Estado que não impõe uma solução direta, mas sim cria condições para que a economia se desenvolva de forma mais eficiente.
- **Câmaras Técnicas**: Órgãos consultivos criados pelo Estado para subsidiar suas decisões e fornecer orientação técnica.
- **Normatização**: Ação do Estado que estabelece regras e padrões para a economia, visando garantir a segurança e a estabilidade.
- **Segmentação das Operadoras**: Divisão das operadoras de planos privados de assistência à saúde em categorias ou sub-segmentações, com base em suas peculiaridades.
- **Fiscalização**: Ação do Estado que monitora e controla as atividades das operadoras de planos privados de assistência à saúde, visando garantir a conformidade com as regras estabelecidas.

### Referências legais
- Art. 30 da Lei nº 9.656/1998
- Art. 31 da Lei nº 9.656/1998

### Dicas de prova
- Entenda a diferença entre intervenção direta e indireta do Estado na economia.
- Conheça as principais ações do Estado que podem ser tomadas para regulamentar a economia, como a criação de câmaras técnicas e normatização.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direito Econômico", "legal_refs": ["Art. 30 da Lei nº 9.656/1998", "Art. 31 da Lei nº 9.656/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:20:25.314892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=98", "doc_key": "4538d039d38ead4878f175b1ad0d2a2d"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f0d31bbdc2053f214746769b5fa00c25dd5ccbc2901d7b48b710e6d2d9412c81'),
  ('cpiuris2025::9eac09b156f9c633acde2ccdd2fe48d0', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulação de Planos Privados de Assistência à Saúde', '## Regulação de Planos Privados de Assistência à Saúde

O texto destaca as competências do órgão regulador para fiscalizar e controlar as operadoras de planos privados de assistência à saúde, garantindo a qualidade e o acesso aos serviços.

### Conceitos
- **Regulação**: Ação governamental para controlar e regular atividades econômicas
- **Fiscalização**: Verificação periódica de cumprimento das normas legais
- **Controle**: Ação governamental para limitar ou restringir ações econômicas
- **Competência**: Poder ou autoridade do órgão regulador para agir em determinada área
- **Legislação**: Lei ou norma que regula uma atividade ou setor
- **Regulamentação**: Normas específicas que complementam a legislação
- **Penalidades**: Sancionamentos aplicados por descumprimento de normas legais

### Referências legais
- Art. 9.656, de 1998

### Dicas de prova
- Entenda a importância da regulamentação no setor de planos privados de assistência à saúde
- Identifique as competências do órgão regulador e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direito Econômico", "legal_refs": ["Art. 9.656, de 1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:21:08.352092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=98", "doc_key": "9eac09b156f9c633acde2ccdd2fe48d0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'ee651690372122c31993420754f2b61f75dc869822a8a3e3b96ab9a6d89889bf'),
  ('cpiuris2025::67fbfd37d8c3a4ad5025883582fd667c', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do estado na economia é regulamentada por meio de leis e normas que estabelecem diretrizes e instrumentos para a implementação da política nacional de recursos hídricos, bem como para a regulação dos serviços públicos de saneamento básico.

### Conceitos
- **Intervenção Indireta do Estado**: Ação do estado que não envolve a propriedade direta de empresas ou atividades econômicas, mas sim a regulação e orientação das mesmas.
- **Política Nacional de Recursos Hídricos**: Policia pública que visa a gestão eficiente dos recursos hídricos no país.
- **Regulação dos Serviços Públicos de Saneamento Básico**: Ação do estado para regular e controlar os serviços públicos de saneamento básico, garantindo a qualidade e acessibilidade desses serviços.

### Referências legais
- Art. 4º da Lei n.º 9.984/2000
- Decreto n.º 3.692/2000

### Dicas de prova
- Entenda a diferença entre intervenção indireta e direta do estado na economia.
- Conheça as diretrizes da Política Nacional de Recursos Hídricos e como elas são aplicadas pela ANA.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direito Econômico", "legal_refs": ["Art. 4º da Lei n.º 9.984/2000", "Decreto n.º 3.692/2000"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:21:44.204795+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=99", "doc_key": "67fbfd37d8c3a4ad5025883582fd667c"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'fe160f5e99d3784b1b741c6ce42261af9d098ff3b3f7babb9e00dc869d31b8da'),
  ('cpiuris2025::f520a74596c213d4b1882477ea0dcd81', 'doutrina', 'cp_iuris', 'Direito Econômico — Sistema Nacional de Gerenciamento de Recursos Hídricos', '## Sistema Nacional de Gerenciamento de Recursos Hídricos

Entidades públicas e privadas do Sistema Nacional de Gerenciamento de Recursos Hídricos têm competências para supervisionar, controlar e avaliar ações relacionadas à gestão dos recursos hídricos.

### Conceitos
- **supervisão**: controle e monitoramento das ações relacionadas à gestão dos recursos hídricos
- **disciplina normativa**: estabelecer regras para a implementação e operacionalização da Política Nacional de Recursos Hídricos
- **fiscalização**: controle e monitoramento dos usos de recursos hídricos
- **elaboração de estudos técnicos**: preparar estudos para subsidiar a definição de valores a serem cobrados pelo uso de recursos hídricos
- **apoiamento de iniciativas**: estimular e apoiar a criação de Comitês de Bacia Hidrográfica

### Referências legais
- Art. 38 da Lei no 9.433, de 1997

### Dicas de prova
- Entenda a importância da supervisão e fiscalização nos usos de recursos hídricos.
- Conheça as competências das entidades públicas e privadas do Sistema Nacional de Gerenciamento de Recursos Hídricos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direito Econômico", "legal_refs": ["Art. 38 da Lei no 9.433, de 1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:22:16.316406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=99", "doc_key": "f520a74596c213d4b1882477ea0dcd81"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6fe22cb14250de2e7a5e0b4a7968045c97ae9349151da511ebbc0fda41934632'),
  ('cpiuris2025::dc5e76f7665bcde9b37321de86067558', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do Estado na economia envolve a realização de ações e medidas para prevenir ou minimizar os efeitos de secas e inundações, bem como a gestão de recursos hídricos.

### Conceitos
- **Sistema Nacional de Gerenciamento de Recursos Hídricos**: sistema que visa gerenciar e proteger os recursos hídricos do país
- **Lei no 9.433/1997**: leis que regulamentam a gestão de recursos hídricos

### Referências legais
- Art. 22 da Lei no 9.433, de 1997

### Dicas de prova
- Entenda o conceito de intervenção indireta do Estado na economia e suas ações para prevenir ou minimizar os efeitos de secas e inundações.
- Conheça as diferentes formas de intervenção do Estado na gestão de recursos hídricos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direito Econômico", "legal_refs": ["Art. 22 da Lei no 9.433, de 1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:22:55.327434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=100", "doc_key": "dc5e76f7665bcde9b37321de86067558"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '4078ab2ce4a06c68409cdefa6c487ed16f8f782d2b3a0c5c143853b17e2218c9'),
  ('cpiuris2025::83df525761149c9c24e0d1213cdda382', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulação de Barragens e Transporte Aquaviário', '## Regulação de Barragens e Transporte Aquaviário

Artigos que regulamentam a gestão de barragens e o transporte aquaviário, incluindo a criação da ANTAQ.

### Conceitos
- **Sistema Nacional de Informações sobre Segurança de Barragens (SNISB)**: sistema de monitoramento de segurança de barragens
- **Conselho Nacional de Recursos Hídricos (CNRH)**: órgão responsável por regular os recursos hídricos
- **Agência Nacional de Transportes Aquaviários (ANTAQ)**: agência governamental responsável pelo transporte aquaviário

### Referências legais
- Art. XX da Lei n.º 10.233/2001
- Súmula 456 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Regulação de Transporte Aquaviário

