  ('cpiuris2025::7a5c327544e363abd3b2589aef6a5053', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A Lei estabelece as atribuições do Estado para intervenir indiretamente na economia, incluindo a regulamentação de serviços de transporte aquaviário e a gestão de infraestrutura aquaviária.

### Conceitos
- **Intervenção Indireta**: Ação do Estado que não envolve a propriedade direta, mas sim a regulação e supervisão da economia.
- **Regulamentação**: Processo pelo qual o Estado estabelece regras e normas para a prática de uma atividade econômica.
- **Gestão de Infraestrutura**: Responsabilidade do Estado em gerenciar e manter infraestruturas essenciais para a economia, como portos e rodovias.
- **Competição**: Condição que impulsiona a inovação e a eficiência na economia.
- **Isonomia**: Acesso igualitário a serviços e oportunidades econômicas.
- **Direitos dos Usuários**: Direitos garantidos aos usuários de serviços de transporte aquaviário.
- **Competição entre Operadores**: Condição que promove a inovação e a eficiência na economia.
- **Normas e Regulamentos**: Regras estabelecidas pelo Estado para regular a prática de uma atividade econômica.

### Referências legais
- Art. 13 e 14 da Lei

### Dicas de prova
- Entenda a noção de intervenção indireta do Estado na economia.
- Conheça as atribuições do Estado para regulamentar serviços de transporte aquaviário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direito Econômico", "legal_refs": ["Art. 13 e 14 da Lei"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:24:03.630970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=101", "doc_key": "7a5c327544e363abd3b2589aef6a5053"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '8a56c93c0322e724dc96ae19615b4ff99b51755fcfeeaebbc12eed149ca4b5e0'),
  ('cpiuris2025::8d7e73a33f71166a99e45e5cc2433219', 'doutrina', 'cp_iuris', 'Direito Econômico — Poderes e obrigações do concessionário de portos', '## Poderes e obrigações do concessionário de portos

Descreve as atribuições e responsabilidades do concessionário de portos, incluindo a manutenção e reposição de bens e equipamentos reversíveis à União.

### Conceitos
- **Concessão de Porto**: Acordo pelo qual o Estado concede um prazo determinado para que uma empresa realize serviços em um porto.
- **Poder Concedente**: O Poder concedente é a entidade que concede a concessão do porto, responsável por definir as diretrizes e condições da concessão.
- **Lei de Portos**: Lei que regula a concessão e o arrendamento de portos, bem como as atividades relacionadas à navegação aquaviária.
- **Contrato de Concessão**: Acordo entre o concessionário e o Poder concedente que estabelece as condições da concessão do porto.
- **Manutenção Reversível**: Serviço obrigatório realizado pelo concessionário para manter os bens e equipamentos em condições adequadas, com a possibilidade de devolver à União após o término do contrato.
- **Responsabilidade Concessória**: Obrigação do concessionário de cumprir as cláusulas e condições dos contratos de concessão de porto, incluindo a manutenção e reposição dos bens e equipamentos reversíveis à União.
- **Autorização de Instalação Portuária**: Permissão concedida pela autoridade competente para que uma empresa instale atividades em um porto.
- **Lei nº 9.432/1997**: Lei que regula a navegação aquaviária e o afretamento de embarcações estrangeiras.

### Referências legais
- Art. 5o da Lei na qual foi convertida a Medida Provisória nº 595, de 6 de dezembro de 2012

### Dicas de prova
- Entenda o conceito de concessão de portos e as suas implicações.
- Conheça as diretrizes do Poder concedente e as cláusulas e condições dos contratos de concessão de porto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direito Econômico", "legal_refs": ["Art. 5o da Lei na qual foi convertida a Medida Provisória nº 595, de 6 de dezembro de 2012"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:25:03.177081+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=101", "doc_key": "8d7e73a33f71166a99e45e5cc2433219"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '18f603b78af8d90de82b5a8fbec790b79bed2365a2a6fc01a58285a7224d7668'),
  ('cpiuris2025::b616061d6566bccba12713de2b7429a0', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

O texto discute as competências da ANTT em relação à intervenção indireta do Estado na economia, incluindo a promoção de pesquisas e estudos sobre tráfego e demanda de serviços de transporte, bem como a definição de tarifas e preços.

