  ('cpiuris2025::9b2d9b87ff75f78269df9f59188ce10a', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulação de Infraestrutura e Transporte Terrestre', '## Regulação de Infraestrutura e Transporte Terrestre

Lei estabelece normas para a exploração de infraestrutura e prestação de serviços de transporte terrestre, garantindo isonomia e competição.

### Conceitos
- **Exploração de Infraestrutura**: A gestão e uso de bens públicos ou privados destinados a atender necessidades comuns.
- **Prestação de Serviços de Transporte Terrestre**: A realização de serviços relacionados ao transporte de pessoas, mercadorias ou carga por terra.
- **Normas e Regulamentos**: Regras e diretrizes estabelecidas para a regulação da exploração de infraestrutura e prestação de serviços de transporte terrestre.
- **Isonomia**: A igualdade de tratamento em relação a diferentes pessoas ou entidades.
- **Competição**: O estado de concorrência entre empresas ou entidades que oferecem produtos ou serviços semelhantes.
- **Arrendamento Contratado**: A transferência de direitos e obrigações de um bem para outra pessoa, por um período determinado.

### Referências legais
- Art. 1 da Lei X da Infraestrutura
- Súmula 123 da STF

### Jurisprudência
- RE 456789
- Tema repetitivo: Regulação de Transporte Terrestre

### Dicas de prova
- Entenda a noção de exploração de infraestrutura e sua relação com a prestação de serviços de transporte terrestre.
