  ('cpiuris2025::54f9be98708be69aa295c9c4cc1f981b', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A Ancine tem competências para fomentar a indústria cinematográfica e videofonográfica nacional, fiscalizar a legislação referente à atividade cinematográfica e proteger o direito autoral sobre obras audiovisuais nacionais e estrangeiras.

### Conceitos
- **Ancine**: Entidade governamental responsável pela promoção da indústria cinematográfica e videofonográfica nacional.
- **Competências**: Listas de atividades que a Ancine tem autoridade para realizar ou regulamentar.
- **Fomento**: Apoio ao desenvolvimento da indústria cinematográfica e videofonográfica nacional.
- **Direito Autoral**: Direito que protege as obras criativas, como filmes e música.
- **Legislação**: Leis e regulamentos que regem a atividade cinematográfica e videofonográfica.
- **Pirataria**: Apoio ilegal às obras audiovisuais.
- **Sanções**: Medidas legais tomadas contra aqueles que violam as leis de direito autoral.

### Referências legais
- Art. 7º da Medida Provisória n.º 2.228-1/2001

### Dicas de prova
- Entenda a importância da Ancine na promoção da indústria cinematográfica e videofonográfica nacional.
- Conheça as competências da Ancine e como elas se relacionam com o direito autoral e a legislação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Direito Econômico", "legal_refs": ["Art. 7º da Medida Provisória n.º 2.228-1/2001"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:28:04.779764+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=104", "doc_key": "54f9be98708be69aa295c9c4cc1f981b"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '298174a2b24c1e9a141b8db459f084206b0ce615d443b5b89639a13c52c894e7'),
  ('cpiuris2025::9ed14cd4e69a6683b30a0a356ba78a41', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulamentação da Comunicação Audiovisual', '## Regulamentação da Comunicação Audiovisual

Medida Provisória estabelece regras para a produção, distribuição e exibição de obras cinematográficas e videofonográficas, bem como para o fomento à produção de audiovisual nos Estados membros do Mercosul.

### Conceitos
- **Comunicação Audiovisual**: produção, distribuição e exibição de obras cinematográficas e videofonográficas
- **Mercosul**: organização econômica regional composta por Argentina, Brasil, Paraguai e Uruguai
- **Acesso Condicionado**: regra que exige a disponibilização de obras em diferentes formatos

### Referências legais
- Art. X da Lei Y

