  ('cpiuris2025::38d89f9acaf3ae473ac90de96baa7871', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do estado na economia envolve o compromisso de ajustamento de conduta às exigências legais, promova interação com administrações do cinema e audiovisual, estabeleça critérios para garantir princípio da reciprocidade em relação à produção e exploração de obras audiovisuais brasileiras em territórios estrangeiros.

### Conceitos
- **Intervenção Indireta**: Ação do estado que não envolve a tomada direta de controles, mas sim o compromisso de ajustamento de conduta às exigências legais.
- **Competência Pública**: O poder do Estado para agir em nome do interesse público.
- **Reciprocidade**: A obrigação de um estado de tratar igualmente com outro estado que o trata bem, em termos de produção e exploração de obras audiovisuais.

### Referências legais
- Art. 5o, § 6o da Lei n.º 7.347/1985

### Dicas de prova
- Entenda a diferença entre intervenção direta e indireta do estado na economia.
- Conheça as competências da ANAC e como elas se relacionam com o interesse público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direito Econômico", "legal_refs": ["Art. 5o, § 6o da Lei n.º 7.347/1985"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:29:16.757219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=105", "doc_key": "38d89f9acaf3ae473ac90de96baa7871"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f388912027c3bf612ef7e173f5e4028a6bb074813f7793e58dc94b9b4a30d152'),
  ('cpiuris2025::7da858738542b0121710b782fd0ed593', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulação da Aviação Civil', '## Regulação da Aviação Civil

O texto discute as responsabilidades do Estado brasileiro na regulação e fiscalização de atividades aéreas, incluindo certificação de produtos, operação de serviços aéreos estrangeiros e segurança em área aeroportuária.

### Conceitos
- **Aviação Civil**: ramo do direito que regula as atividades relacionadas à aviação
- **Regulação**: ação de estabelecer regras e normas para a realização de uma atividade
- **Fiscalização**: ação de controlar e monitorar o cumprimento das regras e normas
- **Certificação**: procedimento que verifica se um produto ou serviço atende aos padrões estabelecidos
- **Operação de Serviços Aéreos**: realização de serviços aéreos, como transporte de passageiros e carga
- **Segurança em Área Aeroportuária**: medidas para proteger os tripulantes, passageiros e aeronaves

