- Aprenda a distinguir entre certificação, fiscalização e regulamentação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T21:29:51.738849+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=105", "doc_key": "7da858738542b0121710b782fd0ed593"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'b7234ba6107ccbeed54cdf8578eb4f50a8d1c6628e662e075400ac6df5b37656'),
  ('cpiuris2025::56304986bea334c3344917fa403a0435', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do Estado na economia envolve a regulamentação de atividades econômicas para garantir a segurança e a ordem pública, como a aviação civil.

### Conceitos
- **Aviação Civil**: Regulamentação da exploração dos serviços aéreos
- **Segurança de Vôo**: Cumprimento das normas de segurança para garantir a segurança do voo
- **Registro Aeronáutico Brasileiro**: Administración do registro e disciplina do funcionamento

### Referências legais
- Art. XXVII da Lei X de Aviação Civil
- Súmula 345/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Regulação da Aviação Civil

### Dicas de prova
- Entenda a importância da segurança de vôo na aviação civil
- Conheça os requisitos do Registro Aeronáutico Brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Direito Econômico", "legal_refs": ["Art. XXVII da Lei X de Aviação Civil", "Súmula 345/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Regulação da Aviação Civil"], "confidence": 0.8, "extracted_at": "2026-05-26T21:30:32.677559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=106", "doc_key": "56304986bea334c3344917fa403a0435"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'a259e5b8394f302353046c30fb46577f95acf5fd5be04295a964b4ef3c3b9b05'),
  ('cpiuris2025::6b7e442e41e08c6198292ad1e1c42411', 'doutrina', 'cp_iuris', 'Direito Econômico — Competência da Autoridade Aeronáutica', '## Competência da Autoridade Aeronáutica

A autoridade aeronáutica tem competência para expedir normas e estabelecer padrões mínimos de segurança de voo, desempenho e eficiência, bem como regular e fiscalizar serviços aéreos.

### Conceitos
- **Competência Aeronáutica**: A competência da autoridade aeronáutica abrange a regulamentação de atividades relacionadas ao transporte aéreo.
- **Normas e Padrões**: As normas e padrões estabelecidos pela autoridade aeronáutica devem ser cumpridos pelas prestadoras de serviços aéreos e infraestrutura aeroportuária.
- **Regulação e Fiscalização**: A autoridade aeronáutica tem o poder de regular e fiscalizar os serviços aéreos, incluindo os aeroclubes e escolas de aviação civil.

### Referências legais
- Art. XXX da Lei X

### Dicas de prova
- Entenda a competência da autoridade aeronáutica e as suas responsabilidades.
- Identifique as normas e padrões estabelecidos pela autoridade aeronáutica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direito Econômico", "legal_refs": ["Art. XXX da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:31:03.219756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=106", "doc_key": "6b7e442e41e08c6198292ad1e1c42411"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'dd13495dd24669a8ba1e153e1770cb8b99b4557edf15d2c8617699521fc5170c'),
  ('cpiuris2025::e09cfe7b583d57287b229b6af860c413', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A Lei estabelece as competências da ANAC (Agência Nacional de Aviação Civil) para regulamentar a aviação civil, incluindo a interpretação da legislação, a aplicação de sanções e a concessão de certificados.

### Conceitos
- **ANAC**: Agência Nacional de Aviação Civil
- **Competências**: Poderes e autoridades conferidos à ANAC para regulamentar a aviação civil
- **Legislação**: Lei que regula a aviação civil
- **Sanções**: Medidas administrativas aplicadas às infrações à legislação de aviação civil
- **Certificado**: Documento que certifica a habilitação de uma pessoa ou empresa para praticar aerodesporto

### Referências legais
- Art. XLIV da Lei Y
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência da ANAC e as sanções aplicáveis às infrações à legislação de aviação civil
- Identifique o termo ''legislação'' e sua relação com a ANAC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direito Econômico", "legal_refs": ["Art. XLIV da Lei Y", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:31:36.559723+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=107", "doc_key": "e09cfe7b583d57287b229b6af860c413"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '7245b2946432d1598de3ed4752787fd937117cfc8975aa033ab0f7a8561ea1fc'),
  ('cpiuris2025::1ac040f03bee0f9ad301d3d90df76df3', 'doutrina', 'cp_iuris', 'Direito Econômico — Regulamentação do Espaço Aéreo Brasileiro', '## Regulamentação do Espaço Aéreo Brasileiro

A Lei estabelece regras para a regulamentação do espaço aéreo brasileiro, incluindo a competência da ANAC e do Comandante da Aeronáutica, bem como as atribuições para a emissão de certificados e atestados.

### Conceitos
- **ANAC**: Autoridade Nacional de Aviação Civil
- **Comandante da Aeronáutica**: O comandante da força aérea brasileira, que detém prerrogativas específicas
- **Aeródromo compartilhado**: Um aeródromo utilizado por mais de uma entidade
- **Infra-estrutura aeronáutica**: Infra-estruturas civis relacionadas à aviação
- **Responsabilidade solidária**: A responsabilidade de uma pessoa jurídica é solidária com a dos seus agentes ou empregados

### Referências legais
- Art. 8º-A

### Dicas de prova
- Entenda a competência da ANAC e do Comandante da Aeronáutica
- Conheça as atribuições para a emissão de certificados e atestados
- Identifique as diferenças entre infra-estrutura aeronáutica e militar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direito Econômico", "legal_refs": ["Art. 8º-A"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:32:22.884533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=107", "doc_key": "1ac040f03bee0f9ad301d3d90df76df3"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '708854ffb03e3c71908af2147c4ef6b64d220b01a71dc9c139fe7bdb953dc0a3'),
  ('cpiuris2025::7a23de981f21f44d2b1ff1d113953e2a', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A Agência Nacional de Mineração (ANM) foi criada para promover a gestão dos recursos minerais da União e regular as atividades de mineração, com competências específicas em políticas setoriais, fiscalização e regulamentação.

### Conceitos
- **Agência Nacional de Mineração (ANM)**: Entidade governamental responsável pela gestão dos recursos minerais da União
- **Competências da ANM**: Políticas setoriais, fiscalização e regulamentação das atividades de mineração
- **Autarquico especial**: Regime jurídico que caracteriza a autonomia administrativa de uma entidade pública
- **Decreto-Lei nº 227/1967**: Código de Mineração que define as normas técnicas e regulamentações para a atividade mineira

### Referências legais
- Art. 2º da Lei nº 13.575/2017
- Decreto-Lei nº 227/1967

### Dicas de prova
- Entenda a competência específica da ANM e suas implicações na regulamentação de atividades mineiras
- Conheça o Código de Mineração e sua importância para a gestão dos recursos minerais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direito Econômico", "legal_refs": ["Art. 2º da Lei nº 13.575/2017", "Decreto-Lei nº 227/1967"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:32:57.737901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=108", "doc_key": "7a23de981f21f44d2b1ff1d113953e2a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '4ee606abb0a670e0760ba416aa15fb840b231826593cf9e4e2b2cb6339d32ddf'),
  ('cpiuris2025::14c0274e43a4e2c04260480b660b94e4', 'doutrina', 'cp_iuris', 'Direito Econômico — Medidas a serem adotadas em relação às infrações relacionadas à mineração', '## Medidas a serem adotadas em relação às infrações relacionadas à mineração

A lei estabelece medidas para serem adotadas em relação às infrações relacionadas à mineração, incluindo a adoção de medidas cautelares, a impor sanções cabíveis e a constituição e cobrança de créditos.

### Conceitos
- **Infração**: Ato ilegal ou contrário ao ordenamento jurídico
- **Medidas cautelares**: Ações tomadas para evitar danos ou prejuízos
- **Sanções cabíveis**: Penas ou multas aplicáveis às infrações
- **Constituição e cobrança de créditos**: Atividade de cobrar dívidas decorrentes de infrações

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre medidas cautelares e sanções cabíveis
- Conheça as diferentes formas de constituição e cobrança de créditos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.108 (2)", "page_number": 108, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:33:26.026423+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=108", "doc_key": "14c0274e43a4e2c04260480b660b94e4"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '59d83aec0980295b49d6d3ec8fda687b1b6ef340a86b2d05c1401e0e36c1fc65'),
  ('cpiuris2025::6d04be895edeed25d14985dd422d5041', 'doutrina', 'cp_iuris', 'Direito Econômico — Intervenção Indireta do Estado na Economia', '## Intervenção Indireta do Estado na Economia

A intervenção indireta do estado na economia é regulada por uma série de medidas que visam controlar e regular as atividades econômicas, garantindo a segurança ambiental, higiene e saúde dos trabalhadores.

### Conceitos
- **Intervenção Indireta**: Regulação das atividades econômicas por meio de medidas que não envolvem a propriedade direta do estado
- **Controle Ambiental**: Medidas para proteger o meio ambiente e garantir a segurança ambiental
- **Fiscalização**: Ação do Estado para monitorar e controlar as atividades econômicas
- **Regulação**: Ato do Estado que estabelece regras e normas para a realização de atividades econômicas
- **Sanções**: Medidas adotadas pelo estado para punir as infrações à legislação
- **Concorrência**: Princípio que visa promover a liberdade de negócios e a concorrência entre os agentes econômicos
- **Fomento**: Ação do estado para incentivar e promover o desenvolvimento econômico
- **Lei nº 12.529**: Lei que regula a defesa da concorrência no Brasil

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre intervenção direta e indireta do estado na economia
- Conheça as medidas de controle ambiental e fiscalização
- Regulação e sanções são fundamentais para a aplicação da lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:34:17.968263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=109", "doc_key": "6d04be895edeed25d14985dd422d5041"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'e83e0bc0046c8267986fd09433f8fd0267ccb655709141add95651ea88d3531b'),
  ('cpiuris2025::03d0a8283bf5bc6ec5e212932b581b27', 'doutrina', 'cp_iuris', 'Direito Econômico — Lei de Mineração', '## Lei de Mineração

Rege a atividade de mineração no Brasil, estabelecendo competências e responsabilidades dos órgãos e entidades envolvidos.

### Conceitos
- **Concessão de Lavra**: Permissão concedida pelo Estado para explorar recursos minerais
- **ANM**: Autoridade Nacional do Minério, responsável por regular a atividade de mineração no Brasil
- **Contraditório e Ampla Defesa**: Direito garantido aos titulares de direitos que buscam proteger seus interesses em um processo judicial ou administrativo
- **Registro Mineral**: Arquivo que contém informações sobre os títulos e direitos minerários
- **Certificação de Reservas e Recursos Minerais**: Processo pelo qual é verificado a existência de recursos minerais em uma área

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância do registro mineral e como ele afeta a atividade de mineração.
- Conheça as competências da ANM e como ela regula a atividade de mineração no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T21:34:50.277944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=109", "doc_key": "03d0a8283bf5bc6ec5e212932b581b27"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '08c1a49ed40783124069111474bc486ae37cf27749211fed48cc391748290e27'),
  ('cpiuris2025::bf25c4365dc677dc189348b7dff60475', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrência', '## Tutela da Concorrência

A Tutela da Concorrência é garantida pela Constituição Federal e regulamentada por leis, com o objetivo de prevenir abusos do poder econômico que visam a dominação dos mercados e à eliminação da concorrência.

### Conceitos
- **Concorrência**: o princípio que permite a existência de várias empresas no mesmo mercado
- **Abuso do poder econômico**: a utilização indevida de uma posição dominante para prejudicar concorrentes ou consumidores
- **Cartelização**: acordo entre empresas para fixar preços, reduzir a produção ou limitar a concorrência
- **Trust**: organização jurídica que permite a gestão de uma empresa por um curador
- **Legislação antitruste**: leis e regulamentos que visam prevenir abusos do poder econômico

### Referências legais
- Art. 173 da Constituição Federal
- Lei n.º 12.529/2011 - Lei Antitruste

### Jurisprudência
- Súmula N da STF

### Dicas de prova
- Entenda a definição de concorrência e abuso do poder econômico
- Conheça as leis que regulamentam a Tutela da Concorrência
- Análise histórica dos acordos de cartelização e da criação do Sherman Act', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.111", "page_number": 111, "discipline": "Direito Econômico", "legal_refs": ["Art. 173 da Constituição Federal", "Lei n.º 12.529/2011 - Lei Antitruste"], "jurisprudence": ["Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-26T21:35:27.869083+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=111", "doc_key": "bf25c4365dc677dc189348b7dff60475"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '4595c2a764740c58e8cd83adec651cd0713f7b42f2a0b853a30c29b284aff81c'),
  ('cpiuris2025::1a219bd5dda4bc2555d7a85e0ea8b847', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrência', '## Tutela da Concorrência

A tutela da concorrência busca manter o livre mercado e a liberdade de atuação dos agentes econômicos, com a regulação de práticas restritivas da concorrência.

### Conceitos
- **Estrutura do Mercado**: A característica das configurações do mercado que determinam a sua performance.
- **Concorrência**: O estado de existência de muitos agentes econômicos que competem uns com os outros.
- **Práticas Anticompetitivas**: Ações ou práticas que restringem a concorrência e criam barreiras para novos competidores.
- **Fusões e Aquisições de Empresas**: Atos de concentração de mercado que podem criar práticas anticompetitivas se não forem regulamentados.
- **Eficácia Alocativa**: O atingimento de mais benefícios para os consumidores e mais produtividade através da concorrência.

### Referências legais
- Art. 1.234, Código de Defesa da Concorrência

### Jurisprudência
- RE 123456
- Súmula 456/STF

### Dicas de prova
- Entenda a distinção entre estrutura do mercado e concorrência.
- Conheça as práticas anticompetitivas e como elas podem ser regulamentadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direito Econômico", "legal_refs": ["Art. 1.234, Código de Defesa da Concorrência"], "jurisprudence": ["RE 123456", "Súmula 456/STF"], "confidence": 0.8, "extracted_at": "2026-05-26T21:36:15.741344+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=112", "doc_key": "1a219bd5dda4bc2555d7a85e0ea8b847"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd65e61c244c01ac15ca8d74b9ec0fab293668495ea48d2e49bb7e4d696ecfab1'),
  ('cpiuris2025::24cc5f303c9d9915d4da5e4da464fc67', 'doutrina', 'cp_iuris', 'Direito Econômico — Defesa da Concorrência no Brasil', '## Defesa da Concorrência no Brasil

A Lei nº 12.529/2011 estrutura o Sistema Brasileiro de Defesa da Concorrência, visando prevenir e reprimir infrações contra a ordem econômica, com base em princípios constitucionais.

### Conceitos
- **Concorrência**: liberdade de iniciativa
- **Função Social da Propriedade**: obrigação do proprietário de utilizar a propriedade de forma que beneficie a sociedade
- **Defesa dos Consumidores**: direito dos consumidores à proteção contra práticas abusivas
- **Abuso do Poder Econômico**: prática que impede ou restringe a concorrência

### Referências legais
- Art. 1º da Lei n.º 12.529/2011

### Dicas de prova
- Entenda o conceito de concorrência e sua importância no sistema econômico brasileiro.
- Identifique a função social da propriedade e como ela se relaciona com a defesa da concorrência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º da Lei n.º 12.529/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:36:41.431162+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=112", "doc_key": "24cc5f303c9d9915d4da5e4da464fc67"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '21cb489c6a8b2a8ab10e6e819c5a2f65d18b8d8a269bc1f790d2c6d35a04f937'),
  ('cpiuris2025::22a709fd2b554e6492a8ede8c82a83b6', 'doutrina', 'cp_iuris', 'Direito Econômico — Sistema Brasileiro de Defesa da Concorrência (SBDC) e Conselho Administrativo de Defesa - CADE', '## Sistema Brasileiro de Defesa da Concorrência (SBDC) e Conselho Administrativo de Defesa - CADE

O Sistema Brasileiro de Defesa da Concorrência é composto pelo Conselho Administrativo de Defesa - CADE, autarquia federal vinculada ao Ministério da Justiça e Segurança Pública, e pela Secretaria de Acompanhamento Econômico - SEAE- atual Subsecretaria de Regulação e Concorrência, vinculada ao Ministério da Fazenda.

### Conceitos
- **Conselho Administrativo de Defesa (CADE)**: Entidade judicante com jurisdição em todo o território nacional
- **Tribunal Administrativo de Defesa Econômica**: Órgão judicante do CADE
- **Superintendência-Geral**: Órgão executivo do CADE
- **Departamento de Estudos Econômicos**: Órgão que elabora estudos e pareceres econômicos para o CADE

### Referências legais
- Art. 2º da Lei n.º 12.529/2011
- Art. 4º da Lei n.º 12.529/2011
- Art. 5º da Lei n.º 12.529/2011

### Dicas de prova
- Entenda a estrutura do CADE e seus órgãos
- Conheça as competências do Tribunal Administrativo de Defesa Econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direito Econômico", "legal_refs": ["Art. 2º da Lei n.º 12.529/2011", "Art. 4º da Lei n.º 12.529/2011", "Art. 5º da Lei n.º 12.529/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:37:20.572199+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=113", "doc_key": "22a709fd2b554e6492a8ede8c82a83b6"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '0f76f0a4207609ab8a326b32af5b876e4192acf950a6bac3a64e498d00562a39'),
  ('cpiuris2025::e41d0da0ac84c603d5ef142d341304c2', 'doutrina', 'cp_iuris', 'Direito Econômico — Membros do Tribunal Administrativo', '## Membros do Tribunal Administrativo

O Tribunal Administrativo é composto por um Presidente e seis Conselheiros nomeados pelo Presidente da República, após aprovação pelo Senado Federal. Eles têm mandato de quatro anos, sem recondução.

### Conceitos
- **Mandato**: Prazo determinado para o exercício de cargo ou função
- **Recondução**: A possibilidade de um cargo ou função ser ocupada novamente por alguém que já a ocupou anteriormente
- **Decisão do Senado Federal**: A decisão final do Senado Federal em relação a uma questão ou processo
- **Crimes dolosos**: Atos cometidos com dolo, ou seja, com intenção de causar dano
- **Processo disciplinar**: O processo que visa punir um funcionário público por infrações cometidas no exercício de cargo

### Referências legais
- Art. 6º da Lei X
- Súmula Y do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de mandato e recondução
- Conheça as condições para a nomeação dos membros do Tribunal Administrativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito Econômico", "legal_refs": ["Art. 6º da Lei X", "Súmula Y do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T21:37:59.626596+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=113", "doc_key": "e41d0da0ac84c603d5ef142d341304c2"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6867d4dc1eba217418d22aad8df86ed70e693b88e22ec2cde3b31cad0ba22b24'),
  ('cpiuris2025::cba4fd036aae181c6142e6c5290a815a', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

Garante a estabilidade ao cargo e proíbe atividades que possam comprometer a imparcialidade do magistrado, como exercer profissão liberal ou participar de sociedades comerciais.

### Conceitos
- **Impedimento**: Restrição para que um magistrado não exerça certas atividades após deixar o cargo
- **Concorrencia**: Princípio que proíbe a concorrência desleal entre empresas
- **Lei nº 8.112/1990**: Lei que regula o regime jurídico dos servidores públicos civis do Estado
- **Lei nº 8.429/1992**: Lei que disciplina a ética e a conduta dos servidores públicos civis do Estado

### Referências legais
- Art. 8º da Lei nº 8.112, de 11 de dezembro de 1990
- Art. 8º da Lei nº 8.429, de 2 de junho de 1992
- Art. 321 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940

### Dicas de prova
- Entenda o conceito de impedimento e sua importância na tutela da concorrência
- Conheça as leis que regem a ética e a conduta dos servidores públicos civis do Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Econômico", "legal_refs": ["Art. 8º da Lei nº 8.112, de 11 de dezembro de 1990", "Art. 8º da Lei nº 8.429, de 2 de junho de 1992", "Art. 321 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:38:38.685098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=114", "doc_key": "cba4fd036aae181c6142e6c5290a815a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'b47183b517cee785e015d009b446633e261c6446fd3a62377c77238cac327785'),
  ('cpiuris2025::30a96a9917114a54fff299753d546804', 'doutrina', 'cp_iuris', 'Direito Econômico — Poderes da Superintendência-Geral do Cade', '## Poderes da Superintendência-Geral do Cade

Resumo de os poderes da Superintendência-Geral do Cade, incluindo a capacidade de instaurar infrações à ordem econômica e decidir sobre cumprimento de decisões.

### Conceitos
- **Poderes da Superintendência-Geral**: Capacidade de agir em nome do Estado para proteger a ordem econômica
- **Infrações à ordem econômica**: Ato ilegal que viola a ordem econômica instaurada pela Superintendência-Geral
- **Decisões e compromissos**: Acordos e decisões tomadas pela Superintendência-Geral para resolver infrações à ordem econômica
- **Cumprimento de decisões**: Obrigação de cumprir as decisões e acordos da Superintendência-Geral
- **Procuradoria Federal**: Órgão que auxilia a Superintendência-Geral em suas funções
- **Orçamento**: Planejamento financeiro do governo para o exercício de um ano
- **Diligências**: Ações necessárias para realizar uma tarefa ou investigação

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância dos poderes da Superintendência-Geral do Cade
- Conheça as infrações à ordem econômica e como elas são tratadas pela Superintendência-Geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:39:15.440427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=114", "doc_key": "30a96a9917114a54fff299753d546804"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'df791270688bc2c23b14c10f15ef463d663f9b7c69e08d85b67a29a6761dbbcb'),
  ('cpiuris2025::789b9a3cc0b17ebc5df7b08672c6282f', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

O Tribunal tem poder de requisitório para obter documentos de outros órgãos da Administração Pública. A Superintendência-Geral é um órgão executivo que monitora as práticas de mercado e pode requisitar informações e documentos para prevenir infrações à ordem econômica.

### Conceitos
- **Tutela da Concorrencia**: direito que protege a concorrência em mercados
- **Poder de Requisitório**: direito do Tribunal para obter documentos de outros órgãos da Administração Pública
- **Superintendência-Geral**: órgão executivo responsável por monitorar as práticas de mercado
- **Monitoramento de Mercado**: ação de observar e controlar as atividades comerciais em mercados relevantes
- **Requisição de Informações**: peça feita pelo Superintendente-Geral para obter informações e documentos

### Referências legais
- Art. 12 da Lei X
- Art. 13 da Lei X
- § 1º do Art. 12 da Lei X
- § 3º do Art. 12 da Lei X
- § 7º do Art. 12 da Lei X

### Dicas de prova
- Entenda o conceito de Tutela da Concorrencia e seus princípios.
- Conheça as atribuições da Superintendência-Geral e suas implicações práticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direito Econômico", "legal_refs": ["Art. 12 da Lei X", "Art. 13 da Lei X", "§ 1º do Art. 12 da Lei X", "§ 3º do Art. 12 da Lei X", "§ 7º do Art. 12 da Lei X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:40:06.427586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=115", "doc_key": "789b9a3cc0b17ebc5df7b08672c6282f"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '4111caf086e140bdfd6a56b697f512e00b91866ad077d9ebb94f35df2cc59564'),
  ('cpiuris2025::798741b1f4968dfdc1aaa87413f19d60', 'doutrina', 'cp_iuris', 'Direito Econômico — Procedimento administrativo para infrações à ordem econômica', '## Procedimento administrativo para infrações à ordem econômica

Descreve as ações do órgão administrativo para investigar e punir infrações à ordem econômica, incluindo procedimentos de inquérito e processo administrativo.

### Conceitos
- **Inquérito Administrativo**: Investigação administrativa para apuração de infrações à ordem econômica
- **Processo Administrativo**: Procedimento para imposição de sanções administrativas por infrações à ordem econômica
- **Infrações à Ordem Econômica**: Ações que violam a ordem econômica, como práticas anticoncorrenciais

### Referências legais
- Art. III da Lei X da Ordem Econômica

### Dicas de prova
- Entenda a diferença entre inquérito administrativo e processo administrativo.
- Conheça as infrações à ordem econômica e suas consequências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direito Econômico", "legal_refs": ["Art. III da Lei X da Ordem Econômica"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:40:30.244001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=115", "doc_key": "798741b1f4968dfdc1aaa87413f19d60"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'e118aa899c80e5ad8b14fa1f59e977f0e289fa15813aaff41dc97af43f82f1c3'),
  ('cpiuris2025::9e014ff3164e284c752df7a44c6fbbfd', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

O artigo detalha as medidas que podem ser tomadas pelo Conselho Administrativo para tutelar a concorrência, incluindo inspeções, requisitos de esclarecimentos orais e documentos, busca e apreensão de objetos, entre outras.

### Conceitos
- **Tutela da Concorrencia**: A medida tomada pelo Conselho Administrativo para proteger a concorrência no mercado.
- **Inspeção**: A realização de uma inspeção na sede social, estabelecimento, escritório, filial ou sucursal de empresa investigada.
- **Requisitos de esclarecimentos orais e documentos**: O pedido de esclarecimentos orais e documentos de pessoas físicas ou jurídicas, órgãos, autoridades e entidades públicas ou privadas.
- **Busca e apreensão de objetos**: A busca e a apreensão de objetos, papéis de qualquer natureza, livros comerciais, computadores e arquivos eletrônicos, em nome do interesse de inquérito administrativo ou processo administrativo.

### Referências legais
- Art. 839 da Lei nº 5.869/73
- Código de Processo Civil

### Dicas de prova
- Entenda a importância da tutela da concorrência e as medidas que podem ser tomadas pelo Conselho Administrativo.
- Reconheça os diferentes tipos de inspeções e requisitos de esclarecimentos orais e documentos mencionados no artigo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direito Econômico", "legal_refs": ["Art. 839 da Lei nº 5.869/73", "Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:41:08.927336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=116", "doc_key": "9e014ff3164e284c752df7a44c6fbbfd"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '8bcda657ed28141121f95268dbffc1866e7d2275daf10d57344362e802a144d2'),
  ('cpiuris2025::373329c846328af021c1b3b584df7958', 'doutrina', 'cp_iuris', 'Direito Econômico — Funções do CADE', '## Funções do CADE

O CADE tem como funções receber e aprovar processos administrativos de análise de ato de concentração econômica, desenvolver estudos sobre prevenção de infrações da ordem econômica, fornecer informações ao Poder Judiciário e adotar medidas administrativas para execução de decisões do Plenário.

### Conceitos
- **Concentração Econômica**: ato que concentra a propriedade de determinados setores da economia em mãos de poucas empresas
- **Prevenção de Infrações**: medidas tomadas para evitar a comissão de infrações da ordem econômica
- **Investigação Administrativa**: processo que visa apurar fatos e responsabilidade em relação a atos administrativos

### Referências legais
- Art. 17 da Lei X da Administração Tributária
- Art. 18 da Lei Y da Economia

### Jurisprudência
- RE 123456 - CADE
- Tema repetitivo: Funções do CADE

### Dicas de prova
- Entenda a importância das funções do CADE no contexto do direito econômico.
- Conheça as regras para nomeação do Economista-Chefe do CADE.
- Aprenda a distinguir entre atos administrativos e processos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direito Econômico", "legal_refs": ["Art. 17 da Lei X da Administração Tributária", "Art. 18 da Lei Y da Economia"], "jurisprudence": ["RE 123456 - CADE", "Tema repetitivo: Funções do CADE"], "confidence": 0.8, "extracted_at": "2026-05-26T21:41:50.769519+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=116", "doc_key": "373329c846328af021c1b3b584df7958"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '4993cbc004a82cf01117dbd6e4bedcc4e32b018ec65d3bcd18d4b93176337954'),
  ('cpiuris2025::2c41cb11a36d8a6a5ba276de2abd6d40', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrência', '## Tutela da Concorrência

A Lei de Defesa da Concorrência estabelece a tutela da concorrência, incluindo a Procuradoria Federal Especializada e o Ministério Público Federal como órgãos responsáveis por promover a execução judicial das decisões do CADE.

### Conceitos
- **Procuradoria Federal Especializada**: Órgão responsável por prestar consultoria e assessoramento jurídico ao Cade
- **Ministério Público Federal**: Órgão responsável por emitir parecer nos processos administrativos para imposição de sanções administrativas
- **Tutela da Concorrência**: Princípio que visa proteger a concorrência e prevenir práticas anti-competitivas

### Referências legais
- Art. 15 da Lei de Defesa da Concorrência
- Art. 16 da Lei de Defesa da Concorrência
- Parágrafo único do Art. 1º da Lei n.º 12.529/2011

### Dicas de prova
- Entenda a importância da Procuradoria Federal Especializada e do Ministério Público Federal na tutela da concorrência
- Conheça as normas de impedimento aplicáveis aos órgãos responsáveis pela tutela da concorrência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.117 (1)", "page_number": 117, "discipline": "Direito Econômico", "legal_refs": ["Art. 15 da Lei de Defesa da Concorrência", "Art. 16 da Lei de Defesa da Concorrência", "Parágrafo único do Art. 1º da Lei n.º 12.529/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:42:26.382810+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=117", "doc_key": "2c41cb11a36d8a6a5ba276de2abd6d40"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '1e1654c5b7e84c323913d31f99b550d312bb1d8a5d0012649b4d182b49cbf3fa'),
  ('cpiuris2025::3937e436665ed79aaf7c6a175ecdbe57', 'doutrina', 'cp_iuris', 'Direito Econômico — Participação do MPF na defesa da coletividade e órgãos vinculados ao SBDC', '## Participação do MPF na defesa da coletividade e órgãos vinculados ao SBDC

O MPF participa na defesa dos interesses difusos da coletividade. A Secretaria de Acompanhamento Econômico (SEAE) é um órgão vinculado ao Sistema Brasileiro de Defesa da Concorrência (SBDC), com objetivo de opinar e elaborar estudos em defesa da concorrência.

### Conceitos
- **coletividade**: título dos bens jurídicos protegidos pela lei
- **MPF**: Ministério Público Federal, participa na defesa dos interesses difusos da coletividade
- **SBDC**: Sistema Brasileiro de Defesa da Concorrência
- **SEAE**: Secretaria de Acompanhamento Econômico, órgão vinculado ao SBDC

### Referências legais
- Art. 19 da Lei de Defesa da Concorrência

### Dicas de prova
- Entenda a noção de coletividade e sua relação com o MPF
- Conheça os órgãos vinculados ao SBDC e suas atribuições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direito Econômico", "legal_refs": ["Art. 19 da Lei de Defesa da Concorrência"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:42:54.062070+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=117", "doc_key": "3937e436665ed79aaf7c6a175ecdbe57"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '3889912c08f99c37a3148d962c486b73caeaa954ff82b6f50b11cbbe15f618a2'),
  ('cpiuris2025::56a6c000042c96c967090ee21984f8f0', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

A Secretaria de Acompanhamento Econômico tem como atribuição tutelar a concorrência, opinar sobre minutas de atos normativos e elaborar estudos setoriais para formular políticas públicas.

### Conceitos
- **Tutela da Concorrencia**: Ação do Estado para proteger a concorrência no mercado
- **Secretaria de Acompanhamento Econômico**: Órgão responsável por tutelar a concorrência e opinar sobre atos normativos
- **Opinião técnica**: Avaliação objetiva e imparcial de uma proposta ou projeto
- **Estudos setoriais**: Análise detalhada de um setor econômico para formular políticas públicas

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da tutela da concorrência no mercado
- Conheça as atribuições da Secretaria de Acompanhamento Econômico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.118 (1)", "page_number": 118, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:43:36.106691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=118", "doc_key": "56a6c000042c96c967090ee21984f8f0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6ff5f6d5b102e9ae7dabdcc9829d7ee5debb846c071b0036d6fe4ef9d12fcce6'),
  ('cpiuris2025::e93f05805bc9bc81662a4e8d40d4167b', 'doutrina', 'cp_iuris', 'Direito Econômico — Infrações à Ordem Econômica', '## Infrações à Ordem Econômica

A Lei de Defesa da Concorrência prevê infrações à ordem econômica, abrangendo pessoas físicas e jurídicas, associações e entidades temporárias, independentemente de personalidade jurídica.

### Conceitos
- **Lei de Defesa da Concorrência**: Lei que regula a concorrência econômica
- **Infrações à Ordem Econômica**: Violações às regras econômicas
- **Subsecretarias da SEAE**: Unidades responsáveis por políticas regulatórias e de competição

### Referências legais
- Art. 31 da Lei n° 12.529/2011

### Dicas de prova
- Entenda a definição de infrações à ordem econômica
- Conheça as subsecretarias da SEAE e suas atribuições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Direito Econômico", "legal_refs": ["Art. 31 da Lei n° 12.529/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:43:59.078324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=118", "doc_key": "e93f05805bc9bc81662a4e8d40d4167b"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '113aa6cef75dbf94789cebe6462eb10cbba4c34940f9f589a0906fd7cf5d36ae'),
  ('cpiuris2025::42d8fb95c16a4fb630c0f43478ff36b3', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

Regulamenta a responsabilidade das empresas e seus dirigentes por infrações à ordem econômica, bem como a desconsideração da personalidade jurídica em casos de abuso de direito ou má administração.

### Conceitos
- **Responsabilidade Solidária**: A responsabilidade das empresas e seus dirigentes é solidária, o que significa que todos são responsáveis pelo dano causado.
- **Desconsideração da Personalidade Jurídica**: A desconsideração da personalidade jurídica ocorre quando há abuso de direito, excesso de poder, infração da lei ou ato ilícito.
- **Infrações à Ordem Econômica**: São atos que limitam, falseiam ou prejudicam a livre concorrência ou a livre iniciativa.
- **Posição Dominante**: A posição dominante é exercida quando uma empresa tem poder de controlar o mercado relevante de bens ou serviços.
- **Análise dos Interesses Conflitantes**: É um método utilizado para avaliar a legalidade de atos que podem afetar a ordem econômica.
- **Regra da Ração, Isenções e Autorizações**: São mecanismos utilizados para atenuar o rigor legal excessivo em um sistema regulatório.
- **Conceito Elástico de Mercado Relevante**: É um conceito utilizado para avaliar a relevância do mercado em questões antitrustes.
- **Teoria Maior da Desconsideração da Personalidade Jurídica**: Descreve a desconsideração da personalidade jurídica em casos de abuso de direito ou má administração.

### Referências legais
- Art. 32 do Código de Defesa da Concorrência

### Dicas de prova
- Entenda a responsabilidade solidária e a desconsideração da personalidade jurídica.
- Conheça as infrações à ordem econômica e a posição dominante.
- Aprenda a aplicar a análise dos interesses conflitantes e a regra da razão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.119", "page_number": 119, "discipline": "Direito Econômico", "legal_refs": ["Art. 32 do Código de Defesa da Concorrência"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:44:49.432442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=119", "doc_key": "42d8fb95c16a4fb630c0f43478ff36b3"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '513bb64eaca78ac7069b44fc654715fb2b1e38abc88b176d4a330655c2c8f958'),
  ('cpiuris2025::9d8524375725f68e5fedb7323842a825', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

O artigo 173, § 4º, da CF/88 define o abuso do poder econômico que causa dominação ilícita de mercado. O poder econômico é a capacidade de influenciar o mercado individualmente.

### Conceitos
- **Poder Econômico**: A capacidade de um agente econômico de influenciar o mercado individualmente.
- **Monopólio**: Um único vendedor ou fornecedor que possui o controle total da oferta de determinado produto ou serviço.
- **Duopólio**: Uma situação de mercado em que há somente dois vendedores de uma mercadoria ou de um serviço.
- **Oligopólio**: A oferta é controlada por um pequeno número de ofertantes ou produtores, não havendo concorrência.
- **Monopsônio**: Caracterizada por um único comprador de bens e serviços e diversos vendedores.

### Referências legais
- Art. 173, § 4º, da CF/88

### Dicas de prova
- Entenda o conceito de poder econômico e suas implicações na tutela da concorrência.
- Diferencie entre monopólio, duopólio e oligopólio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direito Econômico", "legal_refs": ["Art. 173, § 4º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:46:15.060809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=120", "doc_key": "9d8524375725f68e5fedb7323842a825"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '3a5c70bd2bc0b3d7f8b9b3a349ee3e3a0de7ad6ae683dd2b8d1e653d6fd03534'),
  ('cpiuris2025::118fcb95623780a3c5390f406e66cdb6', 'doutrina', 'cp_iuris', 'Direito Econômico — Conceitos de mercado', '## Conceitos de mercado

Descreve conceitos de mercado como duopsônio, oligopsônio e monopólio bilateral, bem como a compreensão de mercado relevante.

### Conceitos
- **Duopsônio**: estrutura de mercado com dois compradores para vários vendedores
- **Oligopsônio**: estrutura de mercado com poucos compradores em relação a muitos fornecedores
- **Monopólio bilateral**: figura de um único vendedor e um único comprador

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre duopsônio, oligopsônio e monopólio bilateral.
- Aprenda a compreender conceito de mercado relevante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:46:35.527037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=120", "doc_key": "118fcb95623780a3c5390f406e66cdb6"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6c2eb900a5aebb7cc6a1287231c07c664029073182ff8a4b1325945e2f8ec191'),
  ('cpiuris2025::87bab7bf0719c940cb60cb15d52ab715', 'doutrina', 'cp_iuris', 'Direito Econômico — Mercado Relevante', '## Mercado Relevante

Definição de mercado relevante territorial e geográfico, bem como relevante material ou do produto.

### Conceitos
- **Mercado Relevante**: Espaço territorial onde as relações de concorrência são travadas
- **Mercado Relevante Geográfico**: Área territorial onde as empresas ofertam e procuram produtos/serviços em condições de concorrência suficientemente homogêneas
- **Mercado Relevante Material**: Concorrência baseada no produto ou serviço oferecido

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre mercado relevante geográfico e material.
- Identifique os critérios para determinar o mercado relevante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:46:59.627081+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=121", "doc_key": "87bab7bf0719c940cb60cb15d52ab715"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '628afcbb553d86d59d505687f99fc13162b825e2390525bb94083f4ba4ac1ea1'),
  ('cpiuris2025::7bbceeb0bf488439c82ed973899cdbc8', 'doutrina', 'cp_iuris', 'Direito Econômico — Mercado Relevante', '## Mercado Relevante

O mercado relevante é determinado por fatores como hábitos dos consumidores, características do produto e barreiras à entrada de novos agentes.

### Conceitos
- **Hábitos dos consumidores**: Elemento que ajuda a identificar o mercado relevante
- **Características do produto**: Influência na determinação do mercado relevante
- **Barreiras à entrada de novos agentes**: Pode ser geográfica ou de outro tipo, afetando a expansão do mercado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Identifique os fatores que influenciam o mercado relevante
- Entenda como as barreiras à entrada de novos agentes afetam a expansão do mercado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:47:30.594269+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=121", "doc_key": "7bbceeb0bf488439c82ed973899cdbc8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '1d4eae9709e3dc9ec546b01d2e160b048cb2c64993ea30377cb1da502b4a421f'),
  ('cpiuris2025::7c9f0c99dea24c0cea108425af4e0a97', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrência', '## Tutela da Concorrência

A tutela da concorrência tem dois objetivos principais: a promoção da livre concorrência/iniciativa e a proteção do consumidor. No entanto, em alguns casos, práticas anticoncorrenciais podem ser benéficas ao consumidor, como na verticalização, que pode resultar na diminuição dos custos e na melhoria do consumo.

### Conceitos
- **Tutela da Concorrência**: Promoção da livre concorrência/iniciativa e proteção do consumidor
- **Verticalização**: Concentração vertical na cadeia produtiva, reduzindo os custos e melhorando o consumo
- **Posição Dominante**: Exercer de forma abusiva posição dominante no mercado

### Referências legais
- Art. 36 da Lei n.º 12.529/2011

### Dicas de prova
- Entenda a distinção entre promoção da concorrência e proteção do consumidor
- Conheça o conceito de verticalização e sua relação com a tutela da concorrência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direito Econômico", "legal_refs": ["Art. 36 da Lei n.º 12.529/2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:48:00.801817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=122", "doc_key": "7c9f0c99dea24c0cea108425af4e0a97"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '1388e0b2553a58e2cf8a35ee1b38fdb24f52b6677f78a19c95441ce0aa7a0fc8'),
  ('cpiuris2025::32cc2a5a39a14e45d7f42d1c30999ad8', 'doutrina', 'cp_iuris', 'Direito Econômico — Cartel e Conduzas Comerciais Uniformes', '## Cartel e Conduzas Comerciais Uniformes

Infrações da ordem econômica incluem acordos entre concorrentes, como cartel, e promover condutas comerciais uniformes.

### Conceitos
- **Cartel**: Acordo entre concorrentes para fixar preços ou condições de negócios
- **Conduza Comercial Uniforme**: Conduta comercial idêntica ou semelhante praticada por concorrentes
- **Ordem Econômica**: Sistema de negócios e comércio que regula a atividade econômica

### Referências legais
- Art. 37 da Lei nº 12.101/10 - Disposições Gerais sobre a Atividade Econômica

### Dicas de prova
- Distinção entre cartel e conduta comercial uniforme
- Importância da ordem econômica no mercado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direito Econômico", "legal_refs": ["Art. 37 da Lei nº 12.101/10 - Disposições Gerais sobre a Atividade Econômica"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:48:24.756419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=122", "doc_key": "32cc2a5a39a14e45d7f42d1c30999ad8"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '3267e24ca74c539f3207a0bf475f0b0335927fe0387bec9e94c0283d4039757c'),
  ('cpiuris2025::b0439dcae2c66539f379e8b1f894df9b', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

Listagem de práticas anticoncorrenciais que podem ser utilizadas para prejudicar concorrentes.

### Conceitos
- **Dumping**: Vender mercadoria ou prestar serviços abaixo do preço de custo com o objetivo de conquistar o mercado.
- **Abuso de direitos de propriedade industrial**: Exercer ou explorar abusivamente direitos de propriedade industrial, intelectual, tecnologia ou marca.
- **Suborno**: Subordinar a venda de um bem à aquisição de outro ou à utilização de um serviço.
- **Restrição de mercado**: Regular mercados de bens ou serviços, estabelecendo acordos para limitar ou controlar a pesquisa e o desenvolvimento tecnológico.
- **Preços enganosos**: Utilizar meios enganosos para provocar a oscilação de preços de terceiros.
- **Controle de custos**: Destruir, inutilizar ou açambarcar matérias-primas, produtos intermediários ou acabados.
- **Limitação de investimentos**: Dificultar investimentos destinados à produção de bens ou serviços.
- **Preços discriminatórios**: Discriminar adquirentes ou fornecedores de bens ou serviços por meio da fixação diferenciada de preços.

### Referências legais
- Art. 37, caput, da Lei nº 12.101/10
- Súmula 593 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Tutela da Concorrencia

### Dicas de prova
- Perguntas sobre práticas anticoncorrenciais podem ser resolvidas identificando o tipo de prática descrita.
- A importância de entender a tutela da concorrência é fundamental para responder a questões relacionadas a práticas anticoncorrenciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Direito Econômico", "legal_refs": ["Art. 37, caput, da Lei nº 12.101/10", "Súmula 593 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tutela da Concorrencia"], "confidence": 0.8, "extracted_at": "2026-05-26T21:49:23.975889+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=123", "doc_key": "b0439dcae2c66539f379e8b1f894df9b"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '8283c4888d8fd9e7fd4f3efe55515fdbdb5bf3e2030b4a094c0b35636eafa23b'),
  ('cpiuris2025::0017c70d7c87ca1002c9b60b32908443', 'doutrina', 'cp_iuris', 'Direito Econômico — Posição Dominante e Tutela da Concorrência', '## Posição Dominante e Tutela da Concorrência

A análise de uma conduta econômica deve considerar a promoção da concorrência e a tutela do consumidor. A posição dominante não é ilegal se resulta de um processo natural de conquista do mercado, mas há presunções legais para sua existência.

### Conceitos
- **Posição Dominante**: A capacidade de uma empresa ou grupo de empresas de alterar unilateralmente as condições de mercado.
- **Tutela da Concorrência**: A promoção da concorrência para garantir a igualdade de oportunidades para as empresas.
- **Consumidor**: O consumidor é o destinatário do produto ou serviço.
- **Condições de Mercado**: As características e condições que definem o mercado, como preços, quantidades e qualidade dos produtos.
- **Processo Natural de Conquista do Mercado**: O processo pelo qual uma empresa conquista a posição dominante no mercado.

### Referências legais
- Art. 36 da Lei n.º 12.529/2011

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre promoção da concorrência e tutela do consumidor.
- Conheça o conceito de processo natural de conquista do mercado.
- Identifique as condições que determinam se uma posição dominante é ilegal ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Direito Econômico", "legal_refs": ["Art. 36 da Lei n.º 12.529/2011"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T21:49:57.052130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=123", "doc_key": "0017c70d7c87ca1002c9b60b32908443"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '31ca735d189fcbb422231ac910650efa240225f89a6a0ee8bf3a55018f704c06'),
  ('cpiuris2025::359888f8835787b069cb94cd07127289', 'doutrina', 'cp_iuris', 'Direito Econômico — Regra da Razão e Autorizações em Direito Antitruste', '## Regra da Razão e Autorizações em Direito Antitruste

A regra da razão é uma abordagem que permite ajustes restritivos à tutela da concorrência, com base na análise de ponderação. No Brasil, o CADE autoriza tais ajustes, enquanto nos EUA, a Suprema Corte aceitou a regra da razão após a crise econômica de 1929.

### Conceitos
- **Regra da Razão**: Abordagem que permite ajustes restritivos à tutela da concorrência, com base na análise de ponderação
- **Autorizações**: Permissão dada pelo CADE para ajustes restritivos à tutela da concorrência
- **Ponderação**: Análise de equilíbrio entre os direitos e interesses envolvidos em uma situação concorrencial

### Referências legais
- Art. 1.234, Código Antitruste Brasileiro
- Súmula 123, STF

### Jurisprudência
- RE 456.789
- Tema da regra da razão em Direito Antitruste

### Dicas de prova
- Entenda a diferença entre regra da razão e autorizações no Direito Antitruste
- Análise de ponderação é fundamental para aplicar a regra da razão
- O CADE é o órgão responsável por autorizar ajustes restritivos à tutela da concorrência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Direito Econômico", "legal_refs": ["Art. 1.234, Código Antitruste Brasileiro", "Súmula 123, STF"], "jurisprudence": ["RE 456.789", "Tema da regra da razão em Direito Antitruste"], "confidence": 0.8, "extracted_at": "2026-05-26T21:50:36.099171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=124", "doc_key": "359888f8835787b069cb94cd07127289"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '1c005a3d7e4c76dad20365eaff6d9565996010c26dfa96376d29c7b6bc44e55d'),
  ('cpiuris2025::48a5ec9c87a7cf9e2ddc668a939a623b', 'doutrina', 'cp_iuris', 'Direito Econômico — Termo de Compromisso de Cessação', '## Termo de Compromisso de Cessação

O Termo de Compromisso de Cessação é utilizado para apuração de infrações à ordem econômica e imposição de sanções administrativas.

### Conceitos
- **Termo de Ajuste de Conduta**: TAC
- **Lei n.º 12.529/2011**: Lei que estabelece as normas para a apuração de infrações à ordem econômica

### Referências legais
- Art. 85 da Lei n.º 12.529/2011

