- **Contribuição Pecuniária**: Pagamento feito ao Fundo de Defesa de Direitos Difusos

### Referências legais
- Art. 85 da Lei de Defesa da Concorrência
- Art. 86 e 87 da Lei n.º 12.529/2011

### Jurisprudência
- RE 123456
- ...

