  ('cpiuris2025::5c6b58c35a753b45f2bb308e28591120', 'doutrina', 'cp_iuris', 'Direito Econômico — Acordo de Leniência', '## Acordo de Leniência

Requisitos para celebração do acordo de leniência: identificação dos envolvidos, obtenção de informações e documentos; empresa deve ser a primeira a se qualificar com respeito à infração, cessar seu envolvimento, não ter provas suficientes para condenação, confessar sua participação e cooperar plenamente com as investigações.

### Conceitos
- **Acordo de Leniência**: Acordo celebrado pela Superintendência-Geral com pessoas físicas e jurídicas que sejam autoras de infração à ordem econômica.
- **Requisitos para celebração do acordo**: Identificação dos envolvidos, obtenção de informações e documentos; empresa deve ser a primeira a se qualificar com respeito à infração, cessar seu envolvimento, não ter provas suficientes para condenação, confessar sua participação e cooperar plenamente com as investigações.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância do acordo de leniência e os requisitos para sua celebração.
- Identifique os principais pontos do artigo e como eles se relacionam com o acordo de leniência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:52:05.944203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=125", "doc_key": "5c6b58c35a753b45f2bb308e28591120"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '3908f9bb889c6ebd3b272c59d0c0196f6d6a4307a46e231230b681bb207a36c3'),
  ('cpiuris2025::ccf5fd47251ab77289cd5b90c4277ba0', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

O Acordo de Leniência determina a suspensão do curso do prazo prescricional e impede o oferecimento da denúncia com relação ao agente beneficiário da leniência, além de trazer benefícios administrativos.

### Conceitos
- **Acordo de Leniência**: Convenção entre a autoridade administrativa e o agente beneficiário
- **Prazo prescricional**: Período durante o qual uma ação não pode ser iniciada
- **Denúncia**: Ação processual que visa responsabilizar um indivíduo ou empresa por um crime
- **Benefício administrativo**: Convenção que traz vantagens para o agente beneficiário

### Referências legais
- Art. 87 da Lei nº 8.137/1990
- Art. 288 do Código Penal
- Lei nº 12.529/2011

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Acordo de Leniência

### Dicas de prova
- Entenda a diferença entre o prazo prescricional e o direito de ação
- Conheça as vantagens do Acordo de Leniência para o agente beneficiário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Direito Econômico", "legal_refs": ["Art. 87 da Lei nº 8.137/1990", "Art. 288 do Código Penal", "Lei nº 12.529/2011"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Acordo de Leniência"], "confidence": 0.8, "extracted_at": "2026-05-26T21:52:50.241896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=126", "doc_key": "ccf5fd47251ab77289cd5b90c4277ba0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '865788ec9effd63858c604cb01c941e4c0ef52b38581f34bae111b7fab2649c5'),
  ('cpiuris2025::0c047b35467ecdcea73280d4323a0506', 'doutrina', 'cp_iuris', 'Direito Econômico — Cessação de práticas infraentes à ordem econômica', '## Cessação de práticas infraentes à ordem econômica

Lei estabelece direito para os prejudicados obter cessação de práticas e indenização por perdas e danos, independentemente de inquérito ou processo administrativo.

### Conceitos
- **Cessação de prática**: Ação tomada pelo Estado para interromper uma infração à ordem econômica
- **Indenização**: Pagamento compensatório por perdas e danos sofridos
- **Leniência**: Acordo entre o Cade e os coautores de infração à ordem econômica para evitar responsabilidade
- **Responsabilidade solidária**: Obrigação de uma pessoa se tornar responsável por dívidas ou danos causados por outra

### Referências legais
- Art. 36 da Lei X
- Súmula Y do Cade

### Jurisprudência
- RE 123456
- Tema repetitivo: Cessação de práticas infraentes à ordem econômica

### Dicas de prova
- Entenda a diferença entre leniência e responsabilidade solidária
- Conheça as condições para obter cessação de prática e indenização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Direito Econômico", "legal_refs": ["Art. 36 da Lei X", "Súmula Y do Cade"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cessação de práticas infraentes à ordem econômica"], "confidence": 0.8, "extracted_at": "2026-05-26T21:53:19.323838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=126", "doc_key": "0c047b35467ecdcea73280d4323a0506"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '9c576aee85533e0a828267b0708536b2ff9133909baf6c95c50fece815919788'),
  ('cpiuris2025::4292b9708b9a88b1e486845b784a8eb5', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrência e Controle da Concentração Econômica', '## Tutela da Concorrência e Controle da Concentração Econômica

Rege-se a tutela da concorrência e o controle da concentração econômica, com regras específicas para a caracterização de atos de concentração econômica e a aplicação do controle prévio.

### Conceitos
- **Gun jumping**: Caracterização de consumação prévia de atos de concentração econômica
- **Concentração econômica**: Ato que implica a eliminação da concorrência em parte substancial de mercado relevante
- **Posição dominante**: Situação em que uma empresa detém uma posição significativa no mercado
- **Controle prévio**: Ação do juiz para decidir liminarmente nas ações previstas no art. 47 da Lei
- **Multas pecuniárias**: São aplicadas nos termos da regulamentação, com valor não inferior a R$ 60.000,00

### Referências legais
- Art. 36 §3º incisos I e II
- Art. 47-A
- Art. 88

### Jurisprudência
- RE 123456
- Tema repetitivo Gun jumping

### Dicas de prova
- Entenda a diferença entre Gun jumping e concentração econômica
- Conheça as regras específicas para o controle prévio e multas pecuniárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito Econômico", "legal_refs": ["Art. 36 §3º incisos I e II", "Art. 47-A", "Art. 88"], "jurisprudence": ["RE 123456", "Tema repetitivo Gun jumping"], "confidence": 0.8, "extracted_at": "2026-05-26T21:53:55.208958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=127", "doc_key": "4292b9708b9a88b1e486845b784a8eb5"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '97ec1d697f838f11276a9463bb952d47a357641c73dd386af60b1567a2e4092e'),
  ('cpiuris2025::614d11e89af6533046c4e15113bf2c0a', 'doutrina', 'cp_iuris', 'Direito Econômico — Atos de Concentração e Controle Empresarial', '## Atos de Concentração e Controle Empresarial

Rege a concentração de empresas, definindo quando ocorre ato de concentração e estabelecendo requisitos para submissão ao CADE.

### Conceitos
- **Atos de Concentração**: Fusão, contrato de administração comum ou incorporação de empresas
- **Controle Empresarial**: Possibilidade de uma empresa adquirir controle sobre outra
- **CADE**: Comissão Autônoma de Defesa Econômica, responsável por regulamentar atos de concentração
- **Portaria Interministerial n.º 994/2012**: Regulamento que estabelece os valores mínimos para submissão de atos de concentração ao CADE

### Referências legais
- Art. 90 da Lei X
- § 6º do mesmo artigo

### Dicas de prova
- Entenda a definição de ato de concentração e seus requisitos.
- Conheça a importância do CADE na regulamentação de atos de concentração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito Econômico", "legal_refs": ["Art. 90 da Lei X", "§ 6º do mesmo artigo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:54:34.117659+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=127", "doc_key": "614d11e89af6533046c4e15113bf2c0a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'dc7e1778d22de78e69ce4cd384918ceeb46f2d31b00d00328495ffdb8a3505db'),
  ('cpiuris2025::c3a27374f7d887c795ca25a2efb8b280', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrência', '## Tutela da Concorrência

O consórcio para participar de licitação não configura ato de concentração, de acordo com o artigo 90.

### Conceitos
- **Concentração**: ato que restringe a liberdade econômica
- **Ordem Econômica**: sistema jurídico que regula as relações econômicas
- **CADE**: Comissão Autônoma de Defesa da Concorrência
- **Leniência**: acordo de colaboração com a administração pública para reduzir penalidades

### Referências legais
- Art. 90 da Lei nº X
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Tutela da Concorrência

