- Entenda a diferença entre concentração e consórcio
- Conheça as penalidades aplicáveis às infrações à ordem econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Direito Econômico", "legal_refs": ["Art. 90 da Lei nº X", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tutela da Concorrência"], "confidence": 0.8, "extracted_at": "2026-05-26T21:55:02.041586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=128", "doc_key": "c3a27374f7d887c795ca25a2efb8b280"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '6bf13967cfb5a77ca324d23d7ef031b1738b71533c66e7a59aedf521622bc846'),
  ('cpiuris2025::f2845413f8b1f0900a7959d83cc92c09', 'doutrina', 'cp_iuris', 'Direito Econômico — Acordo de Leniência no CADE', '## Acordo de Leniência no CADE

O CADE pode celebrar acordo de leniência com pessoas físicas e jurídicas que colaborem nas investigações, resultando na identificação de outros envolvidos e obtenção de informações sobre a infração.

### Conceitos
- **Acordo de Leniência**: Convenção entre o CADE e pessoas físicas ou jurídicas que colaboram nas investigações em troca de redução de penalidade.
- **Investigação**: Ação realizada pelo CADE para identificar infrações à ordem econômica.
- **Colaboração efetiva**: Participação ativa e significativa das pessoas físicas ou jurídicas na investigação.

### Referências legais
- Art. 2 da Lei nº 12.651/2012

### Dicas de prova
- Entenda a diferença entre as opções e escolha a que melhor se adequa ao acordo de leniência.
- Lembre-se de que a colaboração efetiva é fundamental para a celebração do acordo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direito Econômico", "legal_refs": ["Art. 2 da Lei nº 12.651/2012"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:55:29.011918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=128", "doc_key": "f2845413f8b1f0900a7959d83cc92c09"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '0dabddc82f104609615a54397ed6c292bc07c54f361ba08590898a2fb8960c8e'),
  ('cpiuris2025::60d60b10eaca8b82a67d02f4faf0e2df', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

A questão discute as regras e princípios que regem a tutela da concorrência, incluindo o acordo de leniência, a competência do CADE e a tipificação das infrações contra a ordem econômica.

### Conceitos
- **acordo de leniência**: Acordo entre a autoridade administrativa e a pessoa jurídica colaboradora que pode resultar em redução da pena, mas não em extinção da punibilidade.
- **competência do CADE**: O CADE é o órgão judicante responsável por julgar questões relacionadas à defesa da concorrência e a infrações contra a ordem econômica.
- **tipificação das infrações**: A tipificação das infrações contra a ordem econômica pressupõe a valoração de seus efeitos e impactos na ordem econômica.

### Referências legais
- Art. 1.º da Lei n.º 12.529/2011

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre redução de pena e extinção da punibilidade.
- Conheça a competência do CADE e sua importância na defesa da concorrência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.129", "page_number": 129, "discipline": "Direito Econômico", "legal_refs": ["Art. 1.º da Lei n.º 12.529/2011"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T21:56:14.836019+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=129", "doc_key": "60d60b10eaca8b82a67d02f4faf0e2df"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '21c95494e1549b75a0b3be0a257e7c175bed73e573c5942309f5c54cb1799e10'),
  ('cpiuris2025::3ce1fff36afb99c89fda658188a5cad4', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

A questão discute a tutela da concorrência, abordando a Lei nº 12.529/11 e o acordo de leniência.

### Conceitos
- **Acordo de Leniência**: Convenção entre o Ministério Público Federal e a empresa que cometeu infração, visando reduzir a penalidade aplicável.
- **Tutela da Concorrencia**: Meio jurídico pelo qual se protege a concorrência no mercado.
- **Lei nº 12.529/11**: Lei que disciplina a tutela da concorrência e o acordo de leniência.

### Referências legais
- Art. 86 da Lei nº 12.529/11

### Dicas de prova
- Pergunte se a redução da penalidade é proporcional à infração cometida.
- Entenda o conceito de mercado relevante e como ele se relaciona com a tutela da concorrência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.130", "page_number": 130, "discipline": "Direito Econômico", "legal_refs": ["Art. 86 da Lei nº 12.529/11"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:56:44.484298+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=130", "doc_key": "3ce1fff36afb99c89fda658188a5cad4"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '2de5d536f18ee2f51a79ed2d61d53aec82a577ea6e03c4a9fd88f5afa7f9ed00'),
  ('cpiuris2025::75e2652dbc5021304840903a651ee762', 'doutrina', 'cp_iuris', 'Direito Econômico — Tutela da Concorrencia', '## Tutela da Concorrencia

A regra da razão não é análise de proporcionalidade abstrata, mas sim em concreto, para avaliar se uma fusão de empresas viola a ordem econômica.

### Conceitos
- **Regra da Razão**: Análise de proporcionalidade no caso concreto
- **Proporcionalidade**: Análise de se uma ação está em consonância com o bem-estar geral
- **Fusão de Empresas**: Aquisição de controle significativo de duas ou mais empresas
- **Mercado Relevante**: Setor econômico que é objeto da tutela da concorrência

### Referências legais
- Art. 93 da Lei 12.101/10
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre análise de proporcionalidade abstrata e em concreto
- Conheça o conceito de mercado relevante e sua importância na tutela da concorrência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.131", "page_number": 131, "discipline": "Direito Econômico", "legal_refs": ["Art. 93 da Lei 12.101/10", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T21:57:10.838606+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=131", "doc_key": "75e2652dbc5021304840903a651ee762"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '861dd6a9d579731f3c3f2f398f6875ee3b4837ad826459df6c1f21f815074e2d'),
  ('cpiuris2025::9a85bcbdb1b0ead69f53287bf05ad27e', 'doutrina', 'cp_iuris', 'Direito Econômico — Formação da Ordem Econômica Internacional', '## Formação da Ordem Econômica Internacional

A Ordem Econômica Internacional se baseia no sistema capitalista, que surgiu após a derrocada do Estado Absolutista e foi influenciado pela Revolução Francesa. A Segunda Guerra Mundial marcou um ponto de inflexão na formação da Ordem Econômica Internacional, com os EUA emergindo como principal potência econômica.

### Conceitos
- **Sistema Capitalista**: Economia baseada na propriedade privada e no lucro
- **Revolução Francesa**: Movimento que derrubou o Estado Absolutista e estabeleceu a monarquia constitucional
- **Estado de Direito**: Sistema jurídico que regula as relações entre os cidadãos e o Estado
- **Constitucionalismo Liberal**: Filosofia política que defende a proteção dos direitos individuais e a limitação do poder estatal
- **Segunda Guerra Mundial**: Conflito global que ocorreu entre 1939 e 1945 e marcou um ponto de inflexão na formação da Ordem Econômica Internacional
- **Organização das Nações Unidas (ONU)**: Organização internacional fundada em 1945 com o objetivo de promover a cooperação e a paz entre os países
- **Acordos de Bretton Woods**: Acordos internacionais celebrados em 1944 que estabeleceram o sistema monetário internacional atual

### Referências legais
- Art. 5 da Constituição Brasileira de 1988
- Súmula 455 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Ordem Econômica Internacional

### Dicas de prova
- Entenda a relação entre o sistema capitalista e a formação da Ordem Econômica Internacional
- Conheça os principais marcos históricos que influenciaram a formação da OEI
- Análise crítica dos acordos de Bretton Woods e sua importância para o sistema monetário internacional atual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito Econômico", "legal_refs": ["Art. 5 da Constituição Brasileira de 1988", "Súmula 455 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Ordem Econômica Internacional"], "confidence": 0.8, "extracted_at": "2026-05-26T21:58:16.627876+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=132", "doc_key": "9a85bcbdb1b0ead69f53287bf05ad27e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'b3983aaaac95a499c2abd03adf67c48f6ab1480a7149053af59d419dc9285846'),
  ('cpiuris2025::c6f54f4070353ba5200acbeedeb2c431', 'doutrina', 'cp_iuris', 'Direito Econômico — Sistema de Cooperação Internacional', '## Sistema de Cooperação Internacional

Policymakers defendem a criação de um sistema internacional institucionalizado para garantir a liquidez e evitar crises nas contas externas.

### Conceitos
- **Cooperação Internacional**: Ação conjunta entre países para alcançar objetivos comuns
- **Sistema de Trocas e Pagamentos**: Rede de transações econômicas entre países
- **Liquidez do Sistema Internacional**: Capacidade do sistema internacional para atender às necessidades de pagamento dos países associados

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância da cooperação internacional na economia
- Conheça os desafios enfrentados pelas Nações Unidas em 1944', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:58:39.094293+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=132", "doc_key": "c6f54f4070353ba5200acbeedeb2c431"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '653ac8b815161109412b7cbcf1bc20225d4cea6f6004ebd5b9a2151cb61e9a29'),
  ('cpiuris2025::200b3857fc510733a28897bce08521b5', 'doutrina', 'cp_iuris', 'Direito Econômico — Organização das Nações Unidas (ONU) e Direito Internacional Econômico', '## Organização das Nações Unidas (ONU) e Direito Internacional Econômico

A ONU foi criada em 1945 para promover a paz e a segurança internacionais, além de desenvolver relações amistosas entre as nações.

### Conceitos
- **Organização das Nações Unidas (ONU)**: Entidade internacional criada em 1945 para promover a paz e a segurança internacionais
- **Direito Internacional Econômico**: Ramo do direito que se preocupa com as relações econômicas entre os estados e as organizações internacionais
- **Paz e segurança internacionais**: Objetivos da ONU, visando evitar ameaças à paz e reprimir atos de agressão
- **Relações amistosas entre as nações**: Princípio que fundamenta a atividade da ONU, baseado no respeito ao princípio de justiça e direito internacional

### Referências legais
- Art. 1° da Carta da ONU

### Dicas de prova
- Entenda a importância da ONU no contexto do Direito Internacional Econômico
- Conheça os objetivos da ONU e como eles se relacionam com o Direito Econômico Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito Econômico", "legal_refs": ["Art. 1° da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:59:14.077922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=133", "doc_key": "200b3857fc510733a28897bce08521b5"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '34c82596e1b25b37925b50433ea55b71594ed83560a06490e2d5045e1b4208ec'),
  ('cpiuris2025::742d700057695da3dd0bc3c4a897330b', 'doutrina', 'cp_iuris', 'Direito Econômico — Objetivos da ONU e composição dos órgãos', '## Objetivos da ONU e composição dos órgãos

A Organização das Nações Unidas (ONU) tem como objetivos promover a paz universal, resolver problemas internacionais de caráter econômico, social, cultural ou humanitário, e proteger os direitos humanos. A ONU é composta por seis órgãos: Assembleia Geral, Conselho de Segurança, Conselho Econômico e Social.

### Conceitos
- **Objetivos da ONU**: Promover a paz universal e proteger os direitos humanos
- **Composição dos órgãos da ONU**: Assembleia Geral, Conselho de Segurança, Conselho Econômico e Social
- **Paz universal**: Estabelecer a paz e a segurança em todo o mundo
- **Direitos humanos**: Proteger e promover os direitos fundamentais de todos os indivíduos
- **Cooperação internacional**: Trabalhar juntos com outros países para resolver problemas globais

### Referências legais
- Art. 7° da Carta da ONU

### Dicas de prova
- Entenda a importância dos objetivos da ONU e como eles se relacionam com os direitos humanos
- Conheça a composição dos órgãos da ONU e seus papéis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito Econômico", "legal_refs": ["Art. 7° da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T21:59:55.527358+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=133", "doc_key": "742d700057695da3dd0bc3c4a897330b"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'fc683fdaf389e15a65c111603e9a2a13bc0dd69c126054bf26a3b271060ae4f5'),
  ('cpiuris2025::06da41b11f11789f4203b8ad3e91bf82', 'doutrina', 'cp_iuris', 'Direito Econômico — Assembleia Geral da ONU', '## Assembleia Geral da ONU

A Assembleia Geral é um órgão principal da ONU, com funções e atribuições definidas na Carta da ONU. Tem o poder de discutir questões internacionais e fazer recomendações aos Membros das Nações Unidas ou ao Conselho de Segurança.

### Conceitos
- **Assembleia Geral**: órgão principal da ONU
- **Carta da ONU**: instrumento fundador da ONU
- **Membros das Nações Unidas**: países membros da ONU
- **Código de Viena sobre o Direito do Mar**: convenção internacional que regula o direito do mar

### Referências legais
- Art. 10 da Carta da ONU
- Art. 11 da Carta da ONU

### Dicas de prova
- Entenda a importância da Assembleia Geral na ONU e suas funções principais.
- Conheça as limitações da Assembleia Geral em relação ao Conselho de Segurança.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direito Econômico", "legal_refs": ["Art. 10 da Carta da ONU", "Art. 11 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:00:25.687866+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=134", "doc_key": "06da41b11f11789f4203b8ad3e91bf82"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'ea36cf703f5aa877a2e7daef724dfdbc067e03482a2b5d72af95a5ec5f3b8855'),
  ('cpiuris2025::533f31d956e7a23aea92a18a86d3d818', 'doutrina', 'cp_iuris', 'Direito Econômico — Funções da Assembléia Geral', '## Funções da Assembléia Geral

A Assembléia Geral não faz recomendações sobre controvérsias, exceto se o Conselho de Segurança a solicitar. Ela promove cooperação internacional em vários campos e faz recomendações para a solução pacífica de situações prejudiciais ao bem-estar geral.

### Conceitos
- **Assembléia Geral**: órgão da ONU responsável por promover cooperação internacional e fazer recomendações
- **Conselho de Segurança**: órgão da ONU que toma decisões sobre questões de segurança internacionais
- **Cooperação internacional**: ação conjunta entre países para alcançar objetivos comuns
- **Recomendação**: sugestão feita por uma entidade para que outra tome uma determinação

### Referências legais
- Artigo 12 da Carta das Nações Unidas
- Artigo 13 da Carta das Nações Unidas
- Artigo 14 da Carta das Nações Unidas

### Dicas de prova
- Entenda a importância da cooperação internacional e as funções da Assembléia Geral
- Conheça os principais artigos da Carta das Nações Unidas relacionados à Assembléia Geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direito Econômico", "legal_refs": ["Artigo 12 da Carta das Nações Unidas", "Artigo 13 da Carta das Nações Unidas", "Artigo 14 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:01:01.325008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=134", "doc_key": "533f31d956e7a23aea92a18a86d3d818"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'd4d42beffe633f72cda7d8550c005025355934bf2e66afa7e494bac248965cc9'),
  ('cpiuris2025::bd093dab7e8abdc0efc051cc1ed748d0', 'doutrina', 'cp_iuris', 'Direito Econômico — Conselho de Segurança e Organização das Nações Unidas', '## Conselho de Segurança e Organização das Nações Unidas

O Conselho de Segurança é composto por 15 membros, com 5 membros permanentes e 10 membros rotativos eleitos pela Assembleia Geral. A Assembléia Geral tem funções específicas em relação ao sistema internacional de tutela e aprovação de acordos de tutela.

### Conceitos
- **Conselho de Segurança**: Órgão da ONU responsável pela manutenção da paz e segurança internacionais
- **Assembléia Geral**: Órgão da ONU responsável pela aprovação de acordos de tutela e orçamento da organização
- **Membros permanentes do Conselho de Segurança**: China, Rússia, Reino Unido, França e Estados Unidos
- **Membros não permanentes do Conselho de Segurança**: Eleitos pela Assembléia Geral para um período de dois anos
- **Funções da Assembléia Geral**: Aprovação de acordos de tutela, orçamento e ajustes financeiros

### Referências legais
- Artigo 16 da Carta das Nações Unidas
- Artigo 17 da Carta das Nações Unidas
- Artigo 23 da Carta das Nações Unidas

### Dicas de prova
- Entenda a composição do Conselho de Segurança e as funções da Assembléia Geral
- Conheça os membros permanentes e não permanentes do Conselho de Segurança
- Aprovação de acordos de tutela é uma função específica da Assembléia Geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Direito Econômico", "legal_refs": ["Artigo 16 da Carta das Nações Unidas", "Artigo 17 da Carta das Nações Unidas", "Artigo 23 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:01:54.729662+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=135", "doc_key": "bd093dab7e8abdc0efc051cc1ed748d0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '0961dbb8903d7c1cd43d4b2d146152cd195a5f3f4202097cdd195912344b30b6'),
  ('cpiuris2025::3e3ce210dbaf7a7ad3cf8b63a233104f', 'doutrina', 'cp_iuris', 'Direito Econômico — Conselho de Segurança das Nações Unidas', '## Conselho de Segurança das Nações Unidas

O Conselho de Segurança tem a principal responsabilidade na manutenção da paz e da segurança internacionais, agindo em nome dos Membros das Nações Unidas.

### Conceitos
- **Conselho de Segurança**: órgão das Nações Unidas responsável pela manutenção da paz e da segurança internacionais
- **Responsabilidade**: obrigação de agir em nome dos Membros das Nações Unidas
- **Atribuições**: funções específicas do Conselho de Segurança para o cumprimento de suas responsabilidades
- **Assembléia Geral**: órgão das Nações Unidas que considera os relatórios do Conselho de Segurança
- **Decisões**: acordos tomados pelo Conselho de Segurança que devem ser executados pelos Membros das Nações Unidas
- **Paz e segurança internacionais**: objetivo principal do Conselho de Segurança

### Referências legais
- Artigo 24 da Carta das Nações Unidas
- Artigo 25 da Carta das Nações Unidas
- Artigo 26 da Carta das Nações Unidas

### Dicas de prova
- Entenda a responsabilidade do Conselho de Segurança e suas atribuições.
- Conheça as decisões do Conselho de Segurança e sua importância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Direito Econômico", "legal_refs": ["Artigo 24 da Carta das Nações Unidas", "Artigo 25 da Carta das Nações Unidas", "Artigo 26 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:02:32.729209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=135", "doc_key": "3e3ce210dbaf7a7ad3cf8b63a233104f"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'e8c3eb9b38994d4ee3a8689bba4612436fb7aa73438dd58900edb1ac8d2e4887'),
  ('cpiuris2025::96845c90a5a8894c4b16b55ca956accd', 'doutrina', 'cp_iuris', 'Direito Econômico — Organizações Internacionais e Fundos de Desenvolvimento', '## Organizações Internacionais e Fundos de Desenvolvimento

Resumo sobre as organizações internacionais e fundos de desenvolvimento da ONU, incluindo UNICEF, PMA/ONU, PNUD, PNUMA, ONU-HÁBITAT e UNFPA.

### Conceitos
- **Desenvolvimento Sustentável**: Objetivo de reduzir a pobreza, as desigualdades e promover o crescimento econômico sustentável.
- **Cooperação Monetária Internacional**: Ação da ONU para promover a cooperação entre os países em termos de monetário e comércio internacional.

### Referências legais
- Acordo de Bretton Woods
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância das organizações internacionais na promoção do desenvolvimento sustentável e cooperação monetária internacional.
- Conheça as diferentes agências da ONU e seus objetivos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Direito Econômico", "legal_refs": ["Acordo de Bretton Woods", "Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:03:00.907618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=136", "doc_key": "96845c90a5a8894c4b16b55ca956accd"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '2b79267b01439edd8ba271b68bedc2a64ef64c1e267e498fe03f9a19144e21b5'),
  ('cpiuris2025::03ecbf3609f6ca8b6d087b36fa30d12c', 'doutrina', 'cp_iuris', 'Direito Econômico — Banco Mundial e Fundo Monetário Internacional (FMI)', '## Banco Mundial e Fundo Monetário Internacional (FMI)

O Banco Mundial é resultado dos acordos de Bretton-Woods, com instituições como BIRD, AID e IFC. O FMI exige políticas públicas de acordo com as regras do Fundo e inspeção regulares sobre empréstimos.

### Conceitos
- **Banco Mundial**: instituição financeira resultante dos acordos de Bretton-Woods
- **FMI**: Fundo Monetário Internacional, que exige políticas públicas e inspeção regulares sobre empréstimos
- **BIRD**: Banco Internacional de Reconstrução e Desenvolvimento, uma das instituições do Banco Mundial
- **AID**: Associação Internacional de Desenvolvimento, outra instituição do Banco Mundial
- **IFC**: Corporação Financeira Internacional, última das instituições do Banco Mundial

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a relação entre o Banco Mundial e o FMI
- Conheça as instituições que compõem o Banco Mundial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:03:40.633889+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=136", "doc_key": "03ecbf3609f6ca8b6d087b36fa30d12c"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '2851165e9af18b0490686e36341c7efa843139cd5375220d56bf79f1a5994ecc'),
  ('cpiuris2025::d3c1c17693d34968e837cb26ecb99214', 'doutrina', 'cp_iuris', 'Direito Econômico — Acordo Geral de Tarifas e Comércio (GATT) e Organização Mundial de Comércio (OMC)', '## Acordo Geral de Tarifas e Comércio (GATT) e Organização Mundial de Comércio (OMC)

O acordo GATT foi celebrado em 1947 e visa normatizar e combater práticas desleais de comércio exterior. A OMC é resultado da Rodada Uruguai do GATT, com objetivo de promover o livre-comércio.

### Conceitos
- **Acordo Geral de Tarifas e Comércio (GATT)**: acordo internacional que visa normatizar e combater práticas desleais de comércio exterior
- **Organização Mundial de Comércio (OMC)**: organização internacional resultante da Rodada Uruguai do GATT, com objetivo de promover o livre-comércio
- **Rodada Uruguai**: rodada de negociações comerciais multilaterais que levou à criação da OMC
- **Tratado de Assunção**: instrumento internacional que fundou o Mercosul em 1991
- **Mercosul**: bloco econômico fundado em 1991, composto por países da América do Sul

### Referências legais
- Decreto n.º 1.355 de 30 de dezembro de 1994

### Dicas de prova
- Entenda a diferença entre o acordo GATT e a OMC
- Conheça os principais objetivos da OMC, como promover o livre-comércio
- Identifique a Rodada Uruguai como um marco importante na criação da OMC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.137 (1)", "page_number": 137, "discipline": "Direito Econômico", "legal_refs": ["Decreto n.º 1.355 de 30 de dezembro de 1994"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:04:21.155017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=137", "doc_key": "d3c1c17693d34968e837cb26ecb99214"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '30c1c288db368ace9e9134593dd6dc39f37d092d68b8dabdacc53933feca6dc0'),
  ('cpiuris2025::4e91346da6083c3aaf85125b19f59f2e', 'doutrina', 'cp_iuris', 'Direito Econômico — Mercosul e União Aduaneira', '## Mercosul e União Aduaneira

O Mercosul é uma união aduaneira entre os governos da Argentina, Brasil, Paraguai e Uruguai, com objetivos de criar um mercado comum e livre comércio.

### Conceitos
- **Mercosul**: união aduaneira entre os países membros
- **União Aduaneira**: regras que permitem a livre circulação dos fatores de produção

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre União Aduaneira plena e imperfeita.
- Conheça os objetivos do Mercosul e como ele se relaciona com o Direito Internacional Público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.137 (2)", "page_number": 137, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:04:40.567735+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=137", "doc_key": "4e91346da6083c3aaf85125b19f59f2e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '0c983a414e607702c76ae8c0af062d5597896a75a217d2715eb6097809e21f85'),
  ('cpiuris2025::c6eb5173f82d2fc138f6d397373f4d4a', 'doutrina', 'cp_iuris', 'Direito Econômico — Órgãos do Mercosul', '## Órgãos do Mercosul

Os órgãos do Mercosul são definidos pelo Protocolo de Ouro Preto, incluindo o Conselho do Mercado Comum (CMC), Grupo Mercado Comum (GMC) e a Comissão do Comércio do Mercosul.

### Conceitos
- **Órgãos do Mercosul**: Entidades que compõem o sistema institucional do Mercosul
- **Conselho do Mercado Comum (CMC)**: Órgão superior do Mercosul, responsável por conduzir a política de integração e tomada de decisões
- **Grupo Mercado Comum (GMC)**: Órgão executivo do Mercosul, responsável por implementar as decisões do CMC

### Referências legais
- Art. 1º do Protocolo de Ouro Preto
- Estrutura Institucional do MERCOSUL

### Dicas de prova
- Entenda a estrutura institucional do Mercosul e as funções dos seus órgãos
- Conheça os principais conceitos relacionados ao CMC e GMC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.138 (1)", "page_number": 138, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º do Protocolo de Ouro Preto", "Estrutura Institucional do MERCOSUL"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:05:23.245866+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=138", "doc_key": "c6eb5173f82d2fc138f6d397373f4d4a"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '7aed6e4fb3474d84061c3cbc0df53859cab8c56fdbda2c41f1177066e12a6edb'),
  ('cpiuris2025::9b2685f02dcd03dc349943ea15877b23', 'doutrina', 'cp_iuris', 'Direito Econômico — Mercosul e Grupo Mercado Comum', '## Mercosul e Grupo Mercado Comum

O GMC é o órgão responsável por resolver controvérsias no âmbito do Mercosul, com base em resoluções obrigatórias para os Estados Partes.

### Conceitos
- **GMC**: Grupo Mercado Comum
- **Mercosul**: Organização regional de economia da América do Sul
- **Resolução obrigatória**: Decisão do GMC que é vinculante para os Estados Partes
- **Capítulo V: Intervenção do Grupo Mercado Comum**: Seção do CMC que regula a intervenção do GMC em controvérsias

### Referências legais
- Art. 6 da Lei nº 9.472/97
- Súmula 456/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Intervenção do GMC em controvérsias

### Dicas de prova
- Entenda a estrutura e os critérios gerais que orientam a criação de órgãos do Mercosul
- Conheça o procedimento opcional ante o GMC e as condições para iniciar o procedimento arbitral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.138 (2)", "page_number": 138, "discipline": "Direito Econômico", "legal_refs": ["Art. 6 da Lei nº 9.472/97", "Súmula 456/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Intervenção do GMC em controvérsias"], "confidence": 0.8, "extracted_at": "2026-05-26T22:05:51.853546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=138", "doc_key": "9b2685f02dcd03dc349943ea15877b23"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '5c169c8bbb94973a9a07996f62fd49c33d8dbf0880416fdc72367976d39d6a0f'),
  ('cpiuris2025::34ac7cdf3c8414393209dbd64f5848c5', 'doutrina', 'cp_iuris', 'Direito Econômico — Atribuições do Grupo Mercado Comum (GMC) e sua intervenção em controvérsias comerciais', '## Atribuições do Grupo Mercado Comum (GMC) e sua intervenção em controvérsias comerciais

O GMC avaliará a situação de uma controvérsia comercial, permitindo às partes apresentarem suas posições e requerendo assessoramento de especialistas. O GMC também pode ser consultado por outros Estados que não estão envolvidos na controvérsia, desde que haja justificativa.

### Conceitos
- **Grupo Mercado Comum (GMC)**: Órgão responsável por avaliar e resolver controvérsias comerciais entre os Estados membros do Mercosul
- **Controvérsia comercial**: Disputa ou divergência entre os Estados membros do Mercosul sobre questões comerciais
- **Assessoramento de especialistas**: Recomendação de especialistas para ajudar a resolver a controvérsia comercial
- **Prazo para Intervenção do GMC**: Trinta dias após a reunião em que a controvérsia foi submetida à consideração do GMC

### Referências legais
- Artigo 7, do Protocolo de Aplicação das Decisões da CMEP
- Artigo 8, do mesmo Protocolo

### Dicas de prova
- Entenda a importância do GMC na resolução de controvérsias comerciais entre os Estados membros do Mercosul.
- Conheça o prazo limite para a intervenção do GMC em uma controvérsia comercial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direito Econômico", "legal_refs": ["Artigo 7, do Protocolo de Aplicação das Decisões da CMEP", "Artigo 8, do mesmo Protocolo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:06:29.667861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=139", "doc_key": "34ac7cdf3c8414393209dbd64f5848c5"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '436adcd0ed7b480f0afd42a6a5f63306aa4a2f7b42d7a029c54f8723ba0213cb'),
  ('cpiuris2025::687afaef12e9f631d1f550cffe4edfa0', 'doutrina', 'cp_iuris', 'Direito Econômico — Parlamento do Mercosul (Parlasul)', '## Parlamento do Mercosul (Parlasul)

O Parlasul tem a incumbência de emitir pareceres, apresentar projetos e anteprojetos de normas, dar declarações sobre assuntos públicos e elaborar relatórios sobre temas específicos.

### Conceitos
- **Parlasul**: órgão legislativo do Mercosul
- **Comitês Técnicos**: órgãos que assistem a Comissão de Comércio do MERCOSUL
- **Diretrizes**: documentos obrigatórios para os Estados Partes

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a estrutura e funções do Parlasul
- Conheça as diferenças entre projetos e anteprojetos de normas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:07:03.142436+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=139", "doc_key": "687afaef12e9f631d1f550cffe4edfa0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '63ef1f15d59db1231c4664008515c6605300fc3496d41e7e0162e00f8e8585e3'),
  ('cpiuris2025::773cdddcf8ff52002e99431258c0c720', 'doutrina', 'cp_iuris', 'Direito Econômico — Foro Consultivo Econômico-social (FCES)', '## Foro Consultivo Econômico-social (FCES)

O FCES é um órgão que representa os setores econômicos sociais e tem como função consultiva emitir recomendações ao Grupo Mercado Comum.

### Conceitos
- **Foro Consultivo Econômico-social**: Órgão de representação dos setores econômicos sociais
- **Recomendação**: Manifestação do FCES sobre questões econômicas e sociais
- **Mercado Comum**: Espaço econômico comunitário criado pelo Mercosul
- **Integração Regional**: Processo de cooperação entre países para promover a unidade econômica e social
- **Política Econômica**: Poderes do Estado em relação à economia
- **Sociedade Civil**: Entidades não governamentais que atuam no âmbito econômico e social
- **Investigação**: Ação de coletar informações para fins de análise e avaliação
- **Norma**: Regras ou padrões estabelecidos por uma autoridade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a função do FCES e suas relações com o Mercado Comum
- Conheça as principais funções do FCES e como elas se relacionam com a integração regional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T22:07:39.241795+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=140", "doc_key": "773cdddcf8ff52002e99431258c0c720"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'f4122ab9aa39ae8b90dd0cd341e49c7bc47b2c99ecf3fa0ca66dbc311f8112e8'),
  ('cpiuris2025::50a9ff7f7e35ed2c6848831d5d97031f', 'doutrina', 'cp_iuris', 'Direito Econômico — Tribunal Permanente de Revisão (TPR) do Mercosul', '## Tribunal Permanente de Revisão (TPR) do Mercosul

O TPR é composto por cinco árbitros, com cada Estado Parte designando um árbitro e seu suplente por dois anos, renovável por dois períodos consecutivos. O quinto árbitro é escolhido por unanimidade dos Estados Partes e tem nacionalidade de algum dos Estados Partes.

### Conceitos
- **Árbitro**: Membro do TPR
- **Composição do TPR**: Cinco árbitros, incluindo um quinto árbitro não renovável
- **Designação de árbitros**: Faz-se por acordo dos Estados Partes ou por sorteio da Secretaria Administrativa do Mercosul
- **Renovabilidade**: Árbitros podem ser renunciados por dois períodos consecutivos
- **Suplente de árbitro**: Árbitro designado para substituir um árbitro não disponível

### Referências legais
- Art. 18 do Protocolo de Olivos

### Dicas de prova
- Entenda a composição e a designação dos árbitros do TPR
- Conheça as regras de renovabilidade e suplência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direito Econômico", "legal_refs": ["Art. 18 do Protocolo de Olivos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:08:10.272015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=140", "doc_key": "50a9ff7f7e35ed2c6848831d5d97031f"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'c9644a697b80c4dd2ddb785dbccf26b69d0a80d61f8b01bf830be3c03356be40'),
  ('cpiuris2025::f2301c8c4bd1970fe6d264f9133ad718', 'doutrina', 'cp_iuris', 'Direito Econômico — Tribunal Permanente de Revisão e seu funcionamento', '## Tribunal Permanente de Revisão e seu funcionamento

O Tribunal Permanente de Revisão é composto por 5 árbitros, sendo 2 nacionais de cada Estado Parte na controvérsia. O terceiro árbitro é designado mediante sorteio entre os árbitros restantes que não sejam nacionais dos Estados partes na controvérsia.

### Conceitos
- **Árbitro**: Membro do Tribunal Permanente de Revisão
- **Tribunal Permanente de Revisão**: Entidade responsável por resolver controvérsias entre Estados Partes da MERCOSUL
- **MERCOSUL**: Organização regional de economia da América do Sul
- **Árbitro designado**: Árbitro escolhido para atuar no Tribunal Permanente de Revisão
- **Presidência do Tribunal**: Função exercida pelo terceiro árbitro designado
- **Sorteio**: Método utilizado para designar o terceiro árbitro
- **Controvérsia**: Disputa entre Estados Partes da MERCOSUL
- **Recurso de Revisão**: Procedimento utilizado para revisar a decisão do Tribunal Permanente de Revisão

### Referências legais
- Art. 19 da Lei X da MERCOSUL
- Art. 20 da Lei X da MERCOSUL
- Art. 21 da Lei X da MERCOSUL

### Dicas de prova
- Entenda a composição do Tribunal Permanente de Revisão e o papel dos árbitros
- Conheça o processo de designação do terceiro árbitro e a importância do sorteio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direito Econômico", "legal_refs": ["Art. 19 da Lei X da MERCOSUL", "Art. 20 da Lei X da MERCOSUL", "Art. 21 da Lei X da MERCOSUL"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:09:07.789804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=141", "doc_key": "f2301c8c4bd1970fe6d264f9133ad718"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '23de4942b69243d48751243eb02366ecef803e21d016e297e03654dcff4cfdeb'),
  ('cpiuris2025::63934f673294f397eefc0b7780ec6dfa', 'doutrina', 'cp_iuris', 'Direito Econômico — Pronunciamento e Acesso ao Tribunal Permanente de Revisão', '## Pronunciamento e Acesso ao Tribunal Permanente de Revisão

O Tribunal Permanente de Revisão pode confirmar, modificar ou revogar a fundamentação jurídica e as decisões do Tribunal Arbitral Ad Hoc. As partes podem acordar submeter-se diretamente ao Tribunal Permanente de Revisão, que terá competências semelhantes a um Tribunal Arbitral Ad Hoc.

### Conceitos
- **Tribunal Permanente de Revisão**: Entidade responsável por confirmar, modificar ou revogar a fundamentação jurídica e as decisões do Tribunal Arbitral Ad Hoc.
- **Tribunal Arbitral Ad Hoc**: Entidade que procura ser substituída pelo Tribunal Permanente de Revisão

### Referências legais
- Art. 22
- Art. 23

### Dicas de prova
- Entenda a diferença entre o Tribunal Arbitral Ad Hoc e o Tribunal Permanente de Revisão
- Conheça as competências do Tribunal Permanente de Revisão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direito Econômico", "legal_refs": ["Art. 22", "Art. 23"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:09:34.879043+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=141", "doc_key": "63934f673294f397eefc0b7780ec6dfa"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '610156b3cbfe2fb387cb24b6a2694d3a0d049db9068f06b249082d9e9fe9947b'),
  ('cpiuris2025::30e2517b9f74ca80e681f6e4e544ea1e', 'doutrina', 'cp_iuris', 'Direito Econômico — Controvérsias entre Estados Partes', '## Controvérsias entre Estados Partes

Rege as controvérsias entre os Estados Partes sobre a interpretação, aplicação ou não cumprimento de tratados e acordos relacionados ao MERCOSUL.

### Conceitos
- **Âmbito de Aplicação**: Define o escopo das controvérsias que podem ser submetidas aos procedimentos estabelecidos no presente Protocolo.
- **Mecanismos de Solução de Controvérsias**: Inclui os mecanismos para resolver divergências entre Estados Partes sobre aspectos técnicos regulados em instrumentos de políticas comerciais comuns.
- **Opiniões Consultivas**: Regula a solicitação de opiniões consultivas ao Tribunal Permanente de Revisão, definindo seu alcance e procedimentos.

### Referências legais
- Art. 1 do Protocolo de Ouro Preto

### Dicas de prova
- Entenda a definição de Âmbito de Aplicação e como ele afeta as controvérsias entre os Estados Partes.
- Conheça os mecanismos de solução de controvérsias estabelecidos no Protocolo, incluindo opiniões consultivas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Direito Econômico", "legal_refs": ["Art. 1 do Protocolo de Ouro Preto"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:10:07.666682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=142", "doc_key": "30e2517b9f74ca80e681f6e4e544ea1e"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'fece603d550b64f0ec0471963615e12ca9b0a5f9dda3ef1107260376aff1a440'),
  ('cpiuris2025::1898a9220f2620d217d8bde901cd5335', 'doutrina', 'cp_iuris', 'Direito Econômico — Limitações das Negociações Diretas em Controvérsias Comerciais', '## Limitações das Negociações Diretas em Controvérsias Comerciais

As negociações diretas em controvérsias comerciais têm prazo máximo de 15 dias após a comunicação da decisão de iniciar a controvérsia.

### Conceitos
- **Princípio da Good Faith**: O princípio da boa fé é fundamental para as negociações comerciais, exigindo que as partes sejam honestas e transparentes em suas declarações e ações.
- **Controvérsias Comerciais**: São disputas entre Estados ou empresas sobre questões relacionadas ao comércio exterior

### Referências legais
- Art. 8 do Mercosul

### Dicas de prova
- Entenda a importância do prazo máximo de 15 dias para as negociações diretas em controvérsias comerciais.
- Conheça o conceito de infrações ao comércio exterior e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Direito Econômico", "legal_refs": ["Art. 8 do Mercosul"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:10:42.813277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=142", "doc_key": "1898a9220f2620d217d8bde901cd5335"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'c324b94cd7db411f4dd6e41b5d2539dada895ad522fd048462360626f7c00733'),
  ('cpiuris2025::eb4c74fbc592f303c05a7f7d9fa6f247', 'doutrina', 'cp_iuris', 'Direito Econômico — Práticas de Infração ao Comércio Exterior', '## Práticas de Infração ao Comércio Exterior

As infrações ao comércio exterior podem ser cometidas por agentes privados ou Estados Soberanos, e incluem práticas como dumping, que se caracteriza pela exportação de mercadoria a preços inferiores aos valores comercializados em seu mercado de origem.

### Conceitos
- **Dumping**: infração ao comércio exterior decorrente da exportação de mercadoria em patamares inferiores aos valores comercializados em seu mercado de origem
- **Valor Normal**: preço do produto similar, em operações comerciais normais, destinado ao consumo no mercado interno do país exportador
- **Produto Similar**: produto idêntico, igual sob todos os aspectos ao produto objeto da investigação ou, na sua ausência, outro produto que apresente características muito próximas às do produto objeto da investigação

### Referências legais
- Art. 7º do Decreto n°. 8.058/2013
- Art. 8º do Decreto n°. 8.058/2013
- Art. 9º do Decreto n°. 8.058/2013

### Dicas de prova
- Entenda a definição de dumping e como ele é regulamentado pelo Decreto n°. 8.058/2013
- Conheça o conceito de valor normal e produto similar, e como eles são avaliados nos procedimentos antidumping', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direito Econômico", "legal_refs": ["Art. 7º do Decreto n°. 8.058/2013", "Art. 8º do Decreto n°. 8.058/2013", "Art. 9º do Decreto n°. 8.058/2013"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-26T22:11:20.310226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=143", "doc_key": "eb4c74fbc592f303c05a7f7d9fa6f247"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'af6d23949290ddffd0bcb8d1a6ae4bc6587d6753e14ef7d8ebfc248397eca7ab'),
  ('cpiuris2025::3f44725a119a8b3f77bad83d1cba0709', 'doutrina', 'cp_iuris', 'Direito Econômico — Triangulação em casos de medida antidumping', '## Triangulação em casos de medida antidumping

A triangulação ocorre quando, após a aplicação de uma medida antidumping contra um país, o produto é revendido com pequenas alterações procedente de outros países.

### Conceitos
- **Triangulação**: Caso em que a medida antidumping é contornada por revenda do produto com pequenas alterações procedente de outro país.
- **Medida antidumping**: Ação tomada pelo governo para proteger os produtos nacionais contra a importação de produtos estrangeiros que prejudicam o mercado interno.

### Referências legais
- Art. X da Lei Y
- ...

### Dicas de prova
- Entenda a diferença entre medida antidumping e triangulação.
- Identifique os casos em que a triangulação é aplicável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:11:41.403862+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=143", "doc_key": "3f44725a119a8b3f77bad83d1cba0709"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'a2e24f65c9dd013df163b9f682cbec08720dc5c7aa49ea21762719005f294d35'),
  ('cpiuris2025::43b85d1cf8a4ce93c8ec99ef50dfa6c3', 'doutrina', 'cp_iuris', 'Direito Econômico — Instrumentos de Defesa Comercial', '## Instrumentos de Defesa Comercial

São definidos os instrumentos de defesa comercial do Estado brasileiro para proteger seus exportadores e evitar prejuízos causados por agentes econômicos estrangeiros.

### Conceitos
- **Acordo Antidumping**: Acordo internacional que estabelece regras para a aplicação de direitos antidumping
- **Acordo de Subsídios e Direitos Compensatórios**: Acordo internacional que estabelece regras para a aplicação de direitos compensatórios
- **Direito Antidumping**: Direito que protege os exportadores brasileiros contra dumping
- **Direito Compensatório**: Direito que compensa os danos causados por dumping

### Referências legais
- Art. 1º da Lei n° 9.019/1995

### Dicas de prova
- Entenda a diferença entre direitos antidumping e compensatórios
- Conheça os acordos internacionais que fundamentam esses direitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.144 (1)", "page_number": 144, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º da Lei n° 9.019/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:12:21.723185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=144", "doc_key": "43b85d1cf8a4ce93c8ec99ef50dfa6c3"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '861dbffd29051acc4e2b4f1b3da6514dc855202b2052fd70f0c693eee88a88ed'),
  ('cpiuris2025::5a469a20b1612484e5e51f96fc0b1ead', 'doutrina', 'cp_iuris', 'Direito Econômico — Provisório Direitos e Análise Preliminar', '## Provisório Direitos e Análise Preliminar

Aplicação de direitos provisórios durante a investigação para verificar indícios de dumping ou concessão de subsídios que causam dano à indústria doméstica.

### Conceitos
- **Dumping**: Prática comercial que envolve a exportação de produtos com preços inferiores aos custos de produção em outro país.
- **Subsídios**: Apoio econômico concedido por um governo a uma empresa ou setor para promover sua competitividade.
- **Indústria Doméstica**: Setor produtor de bens agrícolas, minerais ou industriais dentro de um país.

### Referências legais
- Art. 1º Acordos Antidumping e Acordos de Subsídios e Direitos Compensatórios

### Dicas de prova
- Entenda a diferença entre dumping e subsídios
- Conheça o conceito de indústria doméstica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.144 (2)", "page_number": 144, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º Acordos Antidumping e Acordos de Subsídios e Direitos Compensatórios"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:12:49.782964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=144", "doc_key": "5a469a20b1612484e5e51f96fc0b1ead"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'b8253464fb660bfa4705cd32d6216f4c5f1f1eecab893b277b59275ee90a1e35'),
  ('cpiuris2025::394c9e473fecbaddbe8e6b5ee0adade7', 'doutrina', 'cp_iuris', 'Direito Econômico — Ordem Econômica Internacional e OMC', '## Ordem Econômica Internacional e OMC

A Organização Mundial de Comércio (OMC) pode adotar medidas compensatórias para regular a ordem econômica internacional, mas não possui objetivo de favorecer acordos preferenciais.

### Conceitos
- **GATT**: Organização comercial internacional que surgiu em 1947
- **OMC**: Sucedente do GATT, com sede em Genebra
- **Princípio da união mais favorecida**: Vantagens alfandegárias extensas para todas as nações
- **Cláusula de habilitação**: Exceção da cláusula de nação mais favorecida, visando beneficiar países em desenvolvimento

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre GATT e OMC
- Entendimento do princípio da união mais favorecida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.145", "page_number": 145, "discipline": "Direito Econômico", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:13:16.298103+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=145", "doc_key": "394c9e473fecbaddbe8e6b5ee0adade7"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '657a30345b1754d50cb802f71c18e143cf57194cfa902bb393fc57841dfd8650'),
  ('cpiuris2025::ef9b46555d2831b9916c0e2dd64dc9ce', 'doutrina', 'cp_iuris', 'Direito Econômico — Índices de ações cíveis e processos judiciais', '## Índices de ações cíveis e processos judiciais

Lista de índices de ações cíveis, ações diretas de inconstitucionalidade, recursos extraordinários e outros processos judiciais.

### Conceitos
- **Ação Cível Originária**: Processo civil que busca resolver um litígio entre duas ou mais partes.
- **ADI**: Ação direta de inconstitucionalidade, que visa declarar a inconstitucionalidade de uma lei ou ato do Poder Executivo.
- **RE**: Recursos extraordinários, que são apelações contra decisões do Tribunal Superior Eleitoral (TSE) ou do Supremo Tribunal Federal (STF).
- **Agruamento de Descumprimento de Preceito**: Processo em que uma parte alega que outra parte não cumprimentou um decreto ou lei.
- **Constituições Brasileiras**: Leis fundamentais do Brasil, que estabelecem os princípios e direitos dos cidadãos.
- **Decreto**: Ato do Poder Executivo que decreta uma medida ou norma.
- **Emenda Constitucional**: Mudança na Constituição Federal, feita por meio de um processo legislativo.
- **Lei Complementar**: Lei que complementa a Constituição Federal e estabelece regras específicas para certos assuntos.

### Referências legais
- Art. 2.654 do Código de Processo Civil
- Súmula 1.097.266/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Ação Cível Originária

### Dicas de prova
- Entenda a estrutura dos processos judiciais brasileiros.
- Conheça as diferentes espécies de ações cíveis e recursos extraordinários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.146", "page_number": 146, "discipline": "Direito Econômico", "legal_refs": ["Art. 2.654 do Código de Processo Civil", "Súmula 1.097.266/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ação Cível Originária"], "confidence": 0.8, "extracted_at": "2026-05-26T22:14:15.399544+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=146", "doc_key": "ef9b46555d2831b9916c0e2dd64dc9ce"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'bdf19304090e2b04d3913eb8ea5e82ca37e538d033a2c72c1d02207282fd1e3c'),
  ('cpiuris2025::75762585ff5fdce497fe24c6aeb0ffe0', 'doutrina', 'cp_iuris', 'Direito Econômico — Leis e Medidas Provisórias', '## Leis e Medidas Provisórias

Lista de leis e medidas provisorias emitidas entre 1994 e 2021, incluindo a Lei n.º 8.884/1994 e a Medida Provisória n.º 2.228-1/2000.

### Conceitos
- **Lei**: Estatuto que regula um assunto específico
- **Medida Provisória**: Decrito que tem força de lei até que seja convertido em lei por Congresso

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 220906/DF
- RE 422.941

