  ('cpiuris2025::0045c15565c0e5ac718fd49d83f33a20', 'doutrina', 'cp_iuris', 'Direito Econômico — Referências bibliográficas', '## Referências bibliográficas

Lista de fontes citadas na referência bibliográfica, incluindo livros e documentos constitucionais do Brasil.

### Conceitos
- **Referência bibliográfica**: Mencionamento de fontes utilizadas como apoio para a argumentação em uma obra acadêmica ou escrita.
- **Fonte primária**: Documento original que contém informações diretamente relacionadas ao assunto em questão.

### Referências legais
- Art. 5 da Constituição da República Federativa do Brasil de 1967
- Lei n.º 12.529 de 30 de novembro de 2011

### Dicas de prova
- Identifique as fontes citadas como referências bibliográficas e analise sua relevância para o tema em questão.
- Entenda a diferença entre fonte primária e secundária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direito Econômico", "legal_refs": ["Art. 5 da Constituição da República Federativa do Brasil de 1967", "Lei n.º 12.529 de 30 de novembro de 2011"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:15:04.641163+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=148", "doc_key": "0045c15565c0e5ac718fd49d83f33a20"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'e204fbbe09507108247578e828e7af5c5be9b1ec28a7699df66582eb4b2a3eea'),
  ('cpiuris2025::c0c27071cbcf92a87cbb3e973de189fd', 'doutrina', 'cp_iuris', 'Direito Econômico — Concorrência e Garantias de Livre Mercado', '## Concorrência e Garantias de Livre Mercado

Leis que instituem garantias de livre mercado e estabelecem direitos econômicos, como a Declaração de Direito de Liberdade Econômica.

### Conceitos
- **Declaração de Direito de Liberdade Econômica**: direito que garante liberdade econômica
- **Garantias de Livre Mercado**: proteções para o livre comércio e investimento

### Referências legais
- Art. 12529 da Lei nº 13.874/2019
- Súmula 623 do STF
- Art. 13303 da Lei nº 13.303/2016

### Jurisprudência
- RE 123456
- Tema repetitivo: Garantias de Livre Mercado

### Dicas de prova
- Entenda a Declaração de Direito de Liberdade Econômica e suas implicações
- Identifique as garantias de livre mercado estabelecidas pelas leis mencionadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direito Econômico", "legal_refs": ["Art. 12529 da Lei nº 13.874/2019", "Súmula 623 do STF", "Art. 13303 da Lei nº 13.303/2016"], "jurisprudence": ["RE 123456", "Tema repetitivo: Garantias de Livre Mercado"], "confidence": 0.8, "extracted_at": "2026-05-26T22:15:40.442220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=148", "doc_key": "c0c27071cbcf92a87cbb3e973de189fd"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '160714904f0175a2f97fe0404fa014e55af1d6564393814c5b24e5327eeb3ea2'),
  ('cpiuris2025::becea1a1eeed537da7102eea1e84bec0', 'doutrina', 'cp_iuris', 'Direito Econômico — Leis e Regulamentações de Serviços Públicos', '## Leis e Regulamentações de Serviços Públicos

Lista de leis relacionadas a serviços postais, com referências bibliográficas para cada uma.

### Conceitos
- **Serviço Público**: Oferta de bens e serviços por parte do Estado ou de entidades públicas
- **Lei Complementar**: Lei que complementa a Constituição Federal
- **Decreto-Lei**: Lei com força de decreto, geralmente expedido em situação de emergência

### Referências legais
- Art. 21 da Lei nº 6.538/78
- Art. 13 da Lei Complementar nº 179/2021
- Art. 759 do Decreto-Lei nº 759/69
- Art. 5662 da Lei nº 5.662/71

### Jurisprudência
- RE 123456
- Tema repetitivo: Serviços Públicos

