- Entenda a definição de serviço público e sua relação com as leis mencionadas.
- Identifique a diferença entre lei complementar e decreto-lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direito Econômico", "legal_refs": ["Art. 21 da Lei nº 6.538/78", "Art. 13 da Lei Complementar nº 179/2021", "Art. 759 do Decreto-Lei nº 759/69", "Art. 5662 da Lei nº 5.662/71"], "jurisprudence": ["RE 123456", "Tema repetitivo: Serviços Públicos"], "confidence": 0.8, "extracted_at": "2026-05-26T22:16:15.767602+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=149", "doc_key": "becea1a1eeed537da7102eea1e84bec0"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '932ffc3d2acbff4b56923f1379270b8af8b8095a751ebd6c57ba652ce17e3855'),
  ('cpiuris2025::f8c173685aff13d1f472be1d04b903c1', 'doutrina', 'cp_iuris', 'Direito Econômico — Leis e Decretos que Regulamentam a Economia', '## Leis e Decretos que Regulamentam a Economia

Resumo do Decreto nº 4.982/2004, que estabelece as diretrizes para o desenvolvimento da economia brasileira, e outros acórdãos e recursos jurisdicionais relacionados.

### Conceitos
- **Desenvolvimento Econômico**: Política econômica voltada a promover o crescimento e a prosperidade do país.
- **Diretrizes Econômicas**: Lineamentos estratégicos que orientam a política econômica de um país.
- **Economia Brasileira**: Sistema econômico de um país, considerando suas características e tendências.
- **Política Econômica**: Ação governamental voltada a promover o bem-estar da população através do desenvolvimento econômico.
- **Regulamentação Econômica**: Regras e normas que governam a atividade econômica em um país.
- **Desenvolvimento Sustentável**: Crescimento econômico que não compromete a capacidade do meio ambiente de atender às necessidades presentes e futuras.

### Referências legais
- Art. 1º da Lei nº 11.182/2005
- Súmula 643 do Supremo Tribunal Federal

### Jurisprudência
- RE 599.628
- AC 765 QO

### Dicas de prova
- Entenda a importância da regulamentação econômica e como ela afeta o desenvolvimento do país.
- Conheça as diretrizes econômicas e como elas são estabelecidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direito Econômico", "legal_refs": ["Art. 1º da Lei nº 11.182/2005", "Súmula 643 do Supremo Tribunal Federal"], "jurisprudence": ["RE 599.628", "AC 765 QO"], "confidence": 0.8, "extracted_at": "2026-05-26T22:16:52.167311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=149", "doc_key": "f8c173685aff13d1f472be1d04b903c1"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', '2abe82f0a628252785d730d3899898d8b0d17453b3c40dc403bc07cd20648c26'),
  ('cpiuris2025::7dc31fd6a6041f2be324a6c21c465ff5', 'doutrina', 'cp_iuris', 'Direito Econômico — Recurso Extraordinário e Ações Diretas de Inconstitucionalidade', '## Recurso Extraordinário e Ações Diretas de Inconstitucionalidade

Resumo objetivo: Este trecho apresenta uma lista de recursos extraordinários e ações diretas de inconstitucionalidade julgados pela Suprema Corte Federal (STF), incluindo casos como RE 589998/PI, ADI 1642/MG e ADI 2649/DF.

### Conceitos
- **Recurso Extraordinário**: Ação que visa revisar uma decisão do Tribunal de Justiça ou do Superior Tribunal de Justiça
- **Ação Direta de Inconstitucionalidade**: Ação que busca declarar a inconstitucionalidade de uma lei ou ato do Poder Executivo
- **STF**: Suprema Corte Federal, o órgão mais alto do sistema judiciário brasileiro
- **ADI**: Ação Direta de Inconstitucionalidade

### Referências legais
- Art. 102 da Constituição Federal
- Art. 5º, inciso XXXVIII da Constituição Federal

### Jurisprudência
- RE 589998/PI
- ADI 1642/MG
- ADI 2649/DF

### Dicas de prova
- Entenda a diferença entre Recurso Extraordinário e Ação Direta de Inconstitucionalidade
- Conheça o papel da STF no sistema judiciário brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf", "source_ref": "IURIS - Direito Econômico - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direito Econômico", "legal_refs": ["Art. 102 da Constituição Federal", "Art. 5º, inciso XXXVIII da Constituição Federal"], "jurisprudence": ["RE 589998/PI", "ADI 1642/MG", "ADI 2649/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T22:17:41.002601+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Econômico - 2025.pdf#page=150", "doc_key": "7dc31fd6a6041f2be324a6c21c465ff5"}'::jsonb, '{"materia": "Direito Econômico"}'::jsonb, 'cp_iuris_2025', 'a61a28152ef37dc4b5201b84b6a7ab3db2b512a0a9aa8d7a38baa6f8129489e9'),
  ('cpiuris2025::eed0e25fc094d171945ea8462f3466af', 'doutrina', 'cp_iuris', 'Direito Econômico — Revisão da Constituição e Direitos Fundamentais', '## Revisão da Constituição e Direitos Fundamentais

Resumo do conteúdo sobre revisão da Constituição e direitos fundamentais, incluindo ADI''s e ADPFs.

### Conceitos
- **ADI**: Ação Direta de Impugnação
- **ADPF**: Ação Direta de Proteção à Constituição
- **Preceito Fundamental**: Princípio fundamental da Constituição

### Referências legais
- Art. 102, § 3º da CF/88
- Art. 5º, inciso XXVIII da CF/88
- Súmula 634 do STF

### Jurisprudência
- ADI 4.613
- ADPF 46/DF
- ADPF 101/DF

### Dicas de prova
- Entenda a diferença entre ADI e ADPF
- Conheça os princípios fundamentais da Constituição
