  ('cpiuris2025::1625213da0909d30423dfe5076aa7d0c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Introdução ao Direito Eleitoral', '## Introdução ao Direito Eleitoral

Resumo objetivo: Este texto apresenta a introdução ao direito eleitoral, destacando sua importância e estrutura.

### Conceitos
- **Eleição**: Processo pelo qual os cidadãos escolhem seus representantes
- **Direito Eleitoral**: Brancha do direito que regula as eleições e o processo de participação política

### Referências legais
- Art. 5º da Constituição Federal
- Lei nº 4.737/1965

### Dicas de prova
- Entenda a estrutura do direito eleitoral e seus principais conceitos.
- Conheça as normas constitucionais que regem as eleições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.2", "page_number": 2, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º da Constituição Federal", "Lei nº 4.737/1965"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:19:03.961111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=2", "doc_key": "1625213da0909d30423dfe5076aa7d0c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5312278ba02cd5885699f87ba975aeb21a10b5d2f1748533b3b18fe704d0b71d'),
  ('cpiuris2025::6d4901517cca9f576ff076ea9207eb40', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Biografia do Autor', '## Biografia do Autor

Resumo da biografia do autor Adalberto Biazzo Junior, promotor de justiça e especialista em Direito Constitucional.

### Conceitos
- **Promotor de Justiça**: Membro do Poder Judiciário que atua como advogado do Estado.
- **Especialista em Direito Constitucional**: Esperiente com conhecimento especializado em Direito Constitucional.
- **Concurso Público**: Processo seletivo para acesso a cargos públicos.

### Dicas de prova
- Reconheça os cargos e funções do promotor de justiça.
- Entenda o conceito de especialista em Direito Constitucional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.3", "page_number": 3, "discipline": "Direito Eleitoral", "legal_refs": [], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:19:23.131121+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=3", "doc_key": "6d4901517cca9f576ff076ea9207eb40"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a5f56481ad4e177ff6a1fde3134ebe9319efb2a0c8784d6eaf2219105315267c'),
  ('cpiuris2025::c53e6ae05e65e032edcc4cd5bc560d17', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Noções introdutórias e conceitos fundamentais do Direito Eleitoral', '## Noções introdutórias e conceitos fundamentais do Direito Eleitoral

O texto apresenta uma visão geral das noções introdutórias do Direito Eleitoral, incluindo o conceito, fontes e princípios que o regem.

### Conceitos
- **Conceito de Direito Eleitoral**: A área do direito que se ocupa da organização e regulamentação dos processos eleitorais.
- **Fontes do Direito Eleitoral**: As leis, constituições e outros documentos legais que regem o Direito Eleitoral.
- **Democracia**: Sistema político em que a população tem poder para escolher seus representantes.
- **Poder de Sufrágio Popular**: O direito do cidadão de participar diretamente na tomada de decisões políticas.
- **Mandato Político**: A relação entre o eleitor e o representante eleito.
- **Princípio da Isonomia**: O direito de todos os cidadãos ser tratados igualmente perante a lei.
- **Princípio da Celeridade**: A necessidade de resolver questões eleitorais de forma rápida e eficiente.
- **Princípio da Anualidade Eleitoral**: A realização das eleições em um período anual.

### Referências legais
- Art. 5º da Constituição Brasileira
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de Direito Eleitoral e suas fontes.
- Conheça os princípios fundamentais do Direito Eleitoral, como a isonomia e a celeridade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º da Constituição Brasileira", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:20:04.727065+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=4", "doc_key": "c53e6ae05e65e032edcc4cd5bc560d17"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '97856ed2dd5b7b8be48db8ef85b7f13561c0dd85b1f57c8ba90a533c6d616d55'),
  ('cpiuris2025::260c5f46f87394fcfd3393a0161a4ff7', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Nacionalidade e Cidadania', '## Nacionalidade e Cidadania

O texto discute a definição de nacionalidade, distinguindo-a da cidadania, e explora os termos afetos à nacionalidade, incluindo povo, população, nação, estado e nacionalidade originária e derivada.

### Conceitos
- **Nacionalidade**: status jurídico que caracteriza a relação de um indivíduo com o Estado em que nasceu ou foi naturalizado
- **Cidadania**: direito e dever de ser membro de uma nação, com direitos e obrigações correspondentes
- **Nacionalidade originária**: nacionalidade adquirida pelo nascimento em um país
- **Nacionalidade derivada**: nacionalidade adquirida por naturalização ou outros meios

### Referências legais
- Art. 12 da Constituição Brasileira de 1988

### Dicas de prova
- Entenda a distinção entre nacionalidade e cidadania
- Conheça os termos afetos à nacionalidade
- Aprenda sobre nacionalidade originária e derivada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 12 da Constituição Brasileira de 1988"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:20:41.535570+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=4", "doc_key": "260c5f46f87394fcfd3393a0161a4ff7"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3fc21d368c70d7b99ced059fd115fb9b35889e2ebfb1201a5b9914c2034d31e9'),
  ('cpiuris2025::d2319b975c7de4a1f8f6154a6ae02642', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Capacidade Eleitoral e Direitos Políticos', '## Capacidade Eleitoral e Direitos Políticos

Descreve as capacidades eleitorais ativa e passiva, direitos políticos negativos, desincompatibilização e perda/suspensão de direitos políticos.

### Conceitos
- **Capacidade Eleitoral Ativa**: Direitos Políticos Ativos
- **Capacidade Eleitoral Passiva**: Direitos Políticos Passivos
- **Desincompatibilização**: Impossibilidade de exercer cargos públicos simultaneamente
- **Perda e Suspensão dos Direitos Políticos**: Incapacidade temporária ou permanente do exercício dos direitos políticos

### Referências legais
- Art. 5º da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre capacidade eleitoral ativa e passiva.
- Conheça as regras de desincompatibilização e perda/suspensão de direitos políticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:21:07.173537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=4", "doc_key": "d2319b975c7de4a1f8f6154a6ae02642"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '869fbc2e739ec876fa6c30a5d514aab6e205ad5cdd1d540e08c77d85d1d27a49'),
  ('cpiuris2025::484dad5ce3b374c4d6fadd0e1f9f0570', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Regulamentação dos Partidos Políticos', '## Regulamentação dos Partidos Políticos

Rege a criação, fusão, incorporação e extinção dos partidos políticos, bem como o seu funcionamento e responsabilidades.

### Conceitos
- **Fusão de partidos políticos**: A união de dois ou mais partidos políticos para formar um novo partido.
- **Incorporação de partidos políticos**: O processo pelo qual um partido político é absorvido por outro partido político.
- **Extinção dos partidos políticos**: A dissolução de um partido político, geralmente devido à sua inatividade ou ao seu desmantelamento.
- **Cláusula de Barreira**: Uma regra que limita a participação de um partido político em eleições se o número de votos obtidos for inferior a um percentual determinado.
- **Filiação partidária**: O processo pelo qual uma pessoa se torna membro de um partido político.
- **Fundo Partidário**: Um fundo criado para financiar as atividades dos partidos políticos.

### Referências legais
- Art. 29 da Lei n.º 9.096/95

### Dicas de prova
- Entenda a diferença entre fusão e incorporação de partidos políticos.
- Conheça a importância da Cláusula de Barreira na regulamentação dos partidos políticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29 da Lei n.º 9.096/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:21:41.573747+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=5", "doc_key": "484dad5ce3b374c4d6fadd0e1f9f0570"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2371f73f7a017dc649cb40748d096eda1ef6c278512ffd66001fd40dba418cd2'),
  ('cpiuris2025::4d044e26fdb92b13c7ecc7d183ae55c0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Função da Justiça Eleitoral', '## Função da Justiça Eleitoral

A justiça eleitoral tem quatro funções: jurisdicional, administrativa, legislativa e consultiva.

### Conceitos
- **Função Jurisdicional**: processo de julgamento de recursos eleitorais
- **Função Administrativa**: gestão dos processos eleitorais
- **Função Legislativa (Normativa)**: estabelecimento das regras e normas para os processos eleitorais
- **Função Consultiva**: conselho de especialistas que orienta o processo eleitoral

### Referências legais
- Art. 102 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância das funções da justiça eleitoral
- Diferencie entre as quatro funções e suas responsabilidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 102 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:22:16.473642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=5", "doc_key": "4d044e26fdb92b13c7ecc7d183ae55c0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3dc65f24803443139b79971190cdfbce4f4ab6c2799bf547aa78a52ad8f947d1'),
  ('cpiuris2025::5f66a347ef011583e94379ac7a504bb7', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Princípios institucionais do MP eleitoral', '## Princípios institucionais do MP eleitoral

Descreve os princípios que regem o Ministério Público Eleitoral, incluindo federalização e delegação.

### Conceitos
- **Federalização**: Princípio que estabelece a competência do MP eleitoral para atuar em todo o território nacional.
- **Delegação**: Princípio que autoriza a delegação de poderes ao Procurador Regional Eleitoral e ao Promotor Eleitoral.

### Referências legais
- Art. 102 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da federalização no MP eleitoral.
- Conheça as atribuições do Procurador-Geral Eleitoral e do Procurador Regional Eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 102 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:22:38.524660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=5", "doc_key": "5f66a347ef011583e94379ac7a504bb7"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2120d947a2408e4a7ce008c8eaf4e271dc3e80c9550e71ed8f80f44258de8ba9'),
  ('cpiuris2025::673b49ef4138aa9b03d7de616b569fe2', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Revisão do eleitorado', '## Revisão do eleitorado

Revisão do eleitorado é a alteração da lista de eleitores, podendo ser feita por meio de registro de novos eleitores ou exclusão de outros.

### Conceitos
- **Eleitorado**: lista de eleitores aptos a votar
- **Revisão**: alteração da lista de eleitores

### Referências legais
- Art. 7º da Lei nº 4.737/1965

### Dicas de prova
- Entenda a importância da revisão do eleitorado para garantir a integridade do processo eleitoral.
- Diferencie entre registro de novos eleitores e exclusão de outros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.5 (4)", "page_number": 5, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º da Lei nº 4.737/1965"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:22:55.130049+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=5", "doc_key": "673b49ef4138aa9b03d7de616b569fe2"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '27c6f2c14aa4c14b16871fd0e755778a2c5e5bb5e6437ceb8a94759f811faaf7'),
  ('cpiuris2025::ac6d4073b4614b4387d396a326f4a6c2', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Discute as condições necessárias para a elegibilidade dos candidatos às eleições, bem como as causas que podem impedir o exercício do direito político.

### Conceitos
- **Elegibilidade**: Condição necessária para o exercício do direito político
- **Inelegibilidade**: Causa que impede o exercício do direito político

### Referências legais
- Art. 12 da Lei Eleitoral
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre elegibilidade e inelegibilidade
- Conheça as causas de inelegibilidade previstas na legislação eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 12 da Lei Eleitoral", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:23:26.566829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=6", "doc_key": "ac6d4073b4614b4387d396a326f4a6c2"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e67feeecad7837fe4f8c6401a406e201ed2bf0e850e8a471c4fb3c3c4a941529'),
  ('cpiuris2025::edb21529ff16a51d1f20eed837c347ba', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e inelegibilidade', '## Condições de elegibilidade e inelegibilidade

O texto discute as condições para a elegibilidade e as causas de inelegibilidade dos candidatos, incluindo hipóteses previstas na Constituição Federal e na LC n.º 64/90.

### Conceitos
- **Elegibilidade**: Condição necessária para que um cidadão possa ser eleito
- **Inelegibilidade**: Causa que impede a elegibilidade de um candidato
- **Hipóteses de inelegibilidade**: Situações previstas na Constituição Federal e na LC n.º 64/90 que justificam a inelegibilidade de um candidato

### Referências legais
- Art. 5º, § 2º da CF
- LC n.º 64/90

### Dicas de prova
- Entenda as hipóteses de inelegibilidade previstas na Constituição Federal e na LC n.º 64/90.
- Conheça a importância da desincompatibilização para os candidatos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º, § 2º da CF", "LC n.º 64/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:23:53.225032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=6", "doc_key": "edb21529ff16a51d1f20eed837c347ba"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e17999ca06d92c0e6f61be955bda554d4d4b4ef948cc1a8e112052d4c0f5f6a8'),
  ('cpiuris2025::224b93dbec471f10d12855772e1683e6', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prestação de contas nas campanhas eleitorais', '## Prestação de contas nas campanhas eleitorais

