  ('cpiuris2025::ecd76fea273de49a43e59a892632d53e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Eleitoral', '## Propaganda Eleitoral

Regras para a propaganda eleitoral, incluindo tipos de propaganda permitidas e proibidas.

### Conceitos
- **Propaganda partidária**: Propaganda realizada pelo partido político
- **Propaganda intrapartidária**: Propaganda realizada dentro do partido político
- **Bem público**: Espaço público aberto ao público em geral
- **Bem particular**: Propriedade privada de uma pessoa ou empresa
- **Material impresso**: Materiais impressos, como folhetos, cartazes, etc.
- **Comício**: Reunião pública para discutir um tema específico
- **Carros de som e trio elétrico**: Máquinas que reproduzem áudio para propaganda eleitoral
- **Outdoor**: Propaganda exibida em locais públicos, como placas, cartazes, etc.

### Referências legais
- Art. 4 da Lei nº 9.507/1998

### Dicas de prova
- Entenda a distinção entre propaganda partidária e intrapartidária
- Conheça as regras para a propaganda em diferentes meios de comunicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 4 da Lei nº 9.507/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:25:04.263101+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=7", "doc_key": "ecd76fea273de49a43e59a892632d53e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8055cbb41ceb6d9d7eb37431589298ce064b6f6cb63a5829044fd0fa4f09bd4a'),
  ('cpiuris2025::f39b64bf6177313c0787b99e7d42f0ef', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Organização das eleições e propaganda eleitoral', '## Organização das eleições e propaganda eleitoral

