### Conceitos
- **Poder de polícia**: Autoridade do Estado para regulamentar uma situação
- **Propaganda eleitoral**: Ação de divulgar informações sobre um candidato ou partido
- **Direito de resposta**: O direito de um candidato ou partido responder a acusações feitas por outro
- **Representação contra propaganda irregular**: Procedimento para denunciar e punir irregularidades na propaganda eleitoral

