  ('cpiuris2025::c538ee673c32685d2ecb90a5f9b86c8c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Garantias eletoras', '## Garantias eletoras

Discute-se as garantias para os eleitores, incluindo a não presença em prisão e as ações eleitorais.

### Conceitos
- **Legitimidade ativa**: O direito de agir em um processo
- **Prazo para interposição**: O período durante o qual uma ação pode ser iniciada
- **Competência**: A autoridade que tem jurisdição sobre um caso
- **Procedimento**: O processo pelo qual uma ação é resolvida
- **Legitimidade passiva**: O direito de ser defendido em um processo
- **Efeitos da procedência da AIJE**: As consequências de uma decisão favorável à ação de investigação judicial eleitoral

### Referências legais
- Art. 77, § 3º, da Lei nº 9.504/1997

