  ('cpiuris2025::c4d9881f68b051327f1b62205d435843', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ações de Impugnação e Representações por Descumprimento', '## Ações de Impugnação e Representações por Descumprimento

Trecho sobre ações legais relacionadas à eleição, incluindo legitimidade ativa e passiva, competência, procedimento e sanções.

### Conceitos
- **Legitimidade Ativa**: O direito de uma pessoa ou entidade participar do processo
- **Legitimidade Passiva**: O direito de uma pessoa ou entidade ser objeto de um processo
- **Competência**: A capacidade de um juiz ou tribunal decidir sobre um caso
- **Procedimento**: Os passos a seguir em um processo
- **Descumprimento à Lei**: O ato de não cumprir uma lei ou regulamento

### Referências legais
- Art. 41-A da Lei nº 9.504/97

### Dicas de prova
- Entenda a diferença entre legitimidade ativa e passiva
- Conheça as regras de competência para cada tipo de ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 41-A da Lei nº 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:26:56.553127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=8", "doc_key": "c4d9881f68b051327f1b62205d435843"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'baa0fb19107b37eaee62ecf120d4acfce588b2a5dd4f1a6bbed9e44864972a49'),
  ('cpiuris2025::1c2963f7ab494b82f3d630fedb239ffa', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recurso contra a expedição de diploma (RCED) e outros recursos eleitorais', '## Recurso contra a expedição de diploma (RCED) e outros recursos eleitorais

Trecho que aborda os recursos que podem ser apresentados perante o Tribunal Superior Eleitoral, incluindo o RCED, e seus requisitos e sanções.

### Conceitos
- **Legitimidade ativa**: O direito de uma pessoa para propor um recurso
- **Legitimidade passiva**: A capacidade de uma pessoa de ser processada por um recurso
- **Sanção**: A penalidade aplicada em caso de não cumprimento dos requisitos do recurso
- **Competência**: A autoridade que tem competência para julgar o recurso
- **Prazo**: O prazo dentro do qual deve ser apresentado o recurso
- **Recurso**: A ação de questionar uma decisão ou ato administrativo
- **Diploma**: O documento que certifica a elegibilidade de um eleitor para votar

### Referências legais
- Art. 30-A da Lei nº 9.504/97

### Dicas de prova
- Pergunte sobre a legitimidade ativa e passiva do recurso
- Entenda a sanção aplicada em caso de não cumprimento dos requisitos do recurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 30-A da Lei nº 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:27:27.199245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=8", "doc_key": "1c2963f7ab494b82f3d630fedb239ffa"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '638e4caffce6bc004abd83509add36b6a6cd018e973097b6a05a8f21a9933760'),
  ('cpiuris2025::197ebf9a285808ca7f225cc6845f4617', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recurso Eleitoral e Processo Penal Eleitoral', '## Recurso Eleitoral e Processo Penal Eleitoral

Trata-se de um capítulo que aborda os recursos eleitorais, incluindo a devolutividade, prazo para interposição, gratuidade e juízo de admissibilidade, além de crimes eleitorais e o processo penal eleitoral.

### Conceitos
- **Devolutividade**: Princípio que exige a devolução do caso ao órgão competente para julgamento
- **Prazo para interposição de recursos**: Prazo estabelecido para interpor recurso contra decisão eleitoral
- **Gratuidade dos recursos eleitorais**: Recurso que não exige custa e honorária
- **Juízo de admissibilidade**: Avaliação da legitimidade do recurso apresentado
- **Juízo de retratação**: Avaliação se o recurso apresentado é idêntico ao recurso anteriormente apresentado
- **Crimes eleitorais**: Atos ilegais cometidos durante as eleições
- **Processo penal eleitoral**: Procedimento jurídico que regula a punição dos crimes eleitorais

### Referências legais
- Art. 102 da Constituição Federal
- Código Eleitoral

### Dicas de prova
- Entenda o princípio da devolutividade e sua importância no processo eleitoral
- Conheça as especificidades dos crimes eleitorais e como são classificados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.8 (3)", "page_number": 8, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 102 da Constituição Federal", "Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:28:13.356032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=8", "doc_key": "197ebf9a285808ca7f225cc6845f4617"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '55e66c6971c5208c9a8e2a66ba7ce970ba48f76b12266d81cc3938f2fbe426f6'),
  ('cpiuris2025::8b0b6aa8e11d9baf78727dc39684937a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Processo Penal Eleitoral', '## Processo Penal Eleitoral

Descreve o processo penal relacionado a crimes eleitorais, destacando a investigação desses crimes.

### Conceitos
- **Investigação**: Ação de coleta de provas para identificar e responsabilizar os autores de crimes eleitorais.
- **Crimes Eleitorais**: Títulos legais que regulamentam as infrações cometidas durante o processo eleitoral.

### Referências legais
- Art. 215 da Lei Eleitoral

### Dicas de prova
- Investigação dos crimes eleitorais é fundamental para garantir a integridade do processo eleitoral.
- A investigação deve ser conduzida de forma imparcial e transparente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.8 (4)", "page_number": 8, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 215 da Lei Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:28:30.636567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=8", "doc_key": "8b0b6aa8e11d9baf78727dc39684937a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'bc92a964747096f50ee3e002510ecd61d5e9cee372718dbecee36c93cc63022e'),
  ('cpiuris2025::707052eabe0a634890ab9f264b4f1119', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Competência', '## Competência

Discute a competência para processar e julgar infrações eleitorais.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar uma causa
- **Jurisdição Eleitoral**: O poder do Estado para regular as eleições

### Referências legais
- Art. 102 da Constituição Federal

### Dicas de prova
- Entenda a competência como um direito fundamental
- Conheça o artigo 102 da Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.9", "page_number": 9, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 102 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:28:45.578479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=9", "doc_key": "707052eabe0a634890ab9f264b4f1119"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '63dd250ed3f871208b65e5627758e2f85687396d5b651a6494a8d4e428038456'),
  ('cpiuris2025::a6d9124f52fa396424675566a3b8728b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Conceito e objeto do Direito Eleitoral', '## Conceito e objeto do Direito Eleitoral

O Direito Eleitoral é o ramo do direito público que trata de institutos relacionados com os direitos políticos e com as eleições, com objetivo de garantir a normalidade e a legitimidade do processo eleitoral.

### Conceitos
- **Direito Eleitoral**: ramo do direito público que trata de institutos relacionados com os direitos políticos e com as eleições
- **Objeto do Direito Eleitoral**: normatização do processo eleitoral
- **Competência para legislar sobre Direito Eleitoral**: privativa da União (art. 22, I, da CF)
- **Fontes do Direito Eleitoral**: Constituição Federal, Código Eleitoral, Lei das Eleições, etc.

### Referências legais
- Art. 22, I, da CF
- Lei n.º 4.737/65
- Lei n.º 9.504/97
- Lei Orgânica dos Partidos Políticos (Lei n.º 9.096/95)
- LC n.º 64/90

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda o conceito e objeto do Direito Eleitoral
- Conheça as fontes do Direito Eleitoral
- Análise da competência para legislar sobre Direito Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.10", "page_number": 10, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 22, I, da CF", "Lei n.º 4.737/65", "Lei n.º 9.504/97", "Lei Orgânica dos Partidos Políticos (Lei n.º 9.096/95)", "LC n.º 64/90"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:29:34.285285+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=10", "doc_key": "a6d9124f52fa396424675566a3b8728b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '500efa71bc7a41da2bf6b3f142a18bb604175cd4be634383ddde4e6092df72b6'),
  ('cpiuris2025::b26fd415bbdde275b701ca5d0f4770f1', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Noções Introduatórias e Democracia', '## Noções Introduatórias e Democracia

Descreve as noções introdutórias do Direito Eleitoral, incluindo a vinculação dos órgãos da Justiça Eleitoral e a competência dos TREs para expedir atos normativos. Além disso, apresenta as espécies de democracia: direta, indireta e semidireta, bem como os mecanismos de intervenção direta do cidadão.

### Conceitos
- **Vinculação dos órgãos da Justiça Eleitoral**: Os órgãos da Justiça Eleitoral são vinculados para executar as decisões do Tribunal Superior Eleitoral
- **Competência dos TREs**: Os Tribunais Regionais Eleitorais (TREs) têm competência para expedir atos normativos e realizar eleições suplementares
- **Democracia direta**: O poder é exercido diretamente pelo povo, sem intermediários
- **Democracia indireta**: A participação popular consiste no poder de escolha de mandatários que exercerão os atos de governo
- **Democracia semidireta (participativa)**: O povo elege seus representantes para governar, com mecanismos de intervenção direta do cidadão
- **Plebiscito**: Consulta formulada ao povo para deliberar sobre matéria de acentuada relevância, de natureza constitucional, legislativa ou administrativa
- **Referendo**: Consulta formulada ao povo para ratificar ou rejeitar um ato legislativo ou administrativo

### Referências legais
- Art. 2º da Lei n.º 9.709/98

### Dicas de prova
- Entenda a vinculação dos órgãos da Justiça Eleitoral e a competência dos TREs
