  ('cpiuris2025::680fdd58c422f5d085246b1557c1f422', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Convocação de Plebiscito ou Referendo', '## Convocação de Plebiscito ou Referendo

O plebiscito ou referendo são convocados mediante decreto legislativo, por proposta de 1/3 dos membros do Congresso Nacional, para questões de relevância nacional, competência do Poder Legislativo ou do Poder Executivo, e em casos de incorporação, subdivisão e desmembramento de estado-membro.

### Conceitos
- **Plebiscito**: Processo eleitoral que permite à população decidir sobre uma questão específica
- **Referendo**: Processo eleitoral que permite à população decidir sobre uma questão específica, geralmente relacionada a mudanças constitucionais
- **Convocação**: Ato de convidar o plebiscito ou referendo para ser realizado
- **Proposta**: Solicitação feita por um membro do Congresso Nacional para convocar o plebiscito ou referendo
- **Relevância nacional**: Questão que afeta a nação como um todo, e não apenas uma região específica
- **Competência do Poder Legislativo**: Atribuição conferida ao Congresso Nacional para tomar decisões sobre questões específicas
- **Competência do Poder Executivo**: Atribuição conferida ao Presidente da República ou ao governo federal para tomar decisões sobre questões específicas
- **Incorporação**: Processo pelo qual um estado-membro se junta a outro, ou um novo estado ou território federal é criado

### Referências legais
- Art. 3º da Lei n.º 9.709/98
- Art. 4º da Lei n.º 9.709/98
- Art. 8º da Lei n.º 9.709/98
- Art. 10 da Lei n.º 9.709/98

### Jurisprudência
- EC n.º 111/2021

